window.__D("text/likkutei-sichot/c010",{"p":[[1301490271,"וקביעות הזמן של חג הפסח בשנה היא — שהשנה היא \"שנת הקהל\", שנת \"תש מח\" ו\"ת ש?מח\". דבר זה מדגיש עוד יותר, שכל ההוראות והענינים של חג הפסח צריכים לבוא לידי פועל באופן של \"הקהל\" (של כל פרטי הפרטים): \"את העם, האנשים, והנשים והטף<sup data-n=\"1689\">156</sup>\" ל\"קהל גדול\" (בלשון יחיד) אחד<sup data-n=\"1690\">157</sup>, שכולם חדורים בתחושה של \"יחיד\", של התאחדות: כל פרט שבפרט נשאר מציאות נפרדת, \"אנשים\" או \"נשים\" או \"טף\", אבל יחד עם זה — כולם יחד מתקשרים ומתאחדים לקהל אחד<sup data-n=\"1691\">158</sup>, גוי אחד<sup data-n=\"1692\">159</sup>, גוי שה' אחד הועיד אותו, באמצעות \"תורה אחת\" שלו, והוראותי' בפרטי פרטיות<sup data-n=\"1693\">160</sup>, להיות ל\"ממלכת כהנים וגוי קדוש<sup data-n=\"1694\">161</sup>\".\nכדי לבצע זאת מוכרח להיות \"להבדיל בין הקודש ובין החול<sup data-n=\"1695\">163</sup>\", אצל כל אחד ואצל סביבתו על-ידי \"להורות את בני ישראל את כל החוקים אשר דיבר ה' עליהם ביד משה<sup data-n=\"1696\">162</sup>\".\n* * *\nויהי רצון שכל עניני הפסח, בכל הפרטים ופרטי הפרטים, יבואו לידי מעשה בפועל ממש, באופן של שמחה כפולה, \"תש מח\" ו\"ת ש?מח\", השמחה של עצמו ולשמח את כל האנשים והנשים והטף שמסביב.\nוכל זה — כפי שהתורה מבטיחה — מחיש עוד יותר את הגאולה<sup data-n=\"1697\">164</sup> האמיתית והשלימה על ידי משיח צדקנו ובנין בית המקדש במקומו<sup data-n=\"1698\">165</sup>, ותחזינה עינינו — כולנו",[["1689","156","<b>הקהל. . והטף</b>: וילך לא, יב."],["1690","157","<b>ל\"קהל גדול\". . אחד</b>: ראה לקו\"ש ח\"ט ע' 300. שם ע' 305. שם ע' 615 ואילך."],["1691","158","<b>כל פרט שבפרט. . ומתאחדים לקהל אחד</b>: להעיר שעד\"ז הוא בקרבן פסח שהוא \"קרבן יחיד (דוקא אבל) דומה לקרבן ציבור\" — פיה\"מ להרמב\"ם בהקדמתו לסדר קדשים. וראה בארוכה מכתב עש\"ק שבת הגדול ה'תשל\"ט; מוצש\"ק מברכים חודש ניסן ה'תשמ\"ב (הגש\"פ הנ\"ל ע' תרצו ואילך. שם ע' תשכג). וש\"נ."],["1692","159","<b>גוי אחד</b>: שמואל­ב ז, כג. דברי הימים­א יז, כא. וראה אגה\"ק ס\"ט (קיד, א)."],["1693","160","<b>והוראותי' בפרטי פרטיות</b>: שבכל המצות, וגם בכל דרכיך (שצ\"ל דעהו) וכל מעשיך (שצ\"ל לשם שמים)."],["1694","161","<b>ממלכת כהנים וגוי קדוש</b>: יתרו יט, ו. ובאגדת בראשית פע\"ט [פ]: שכולם נקראו כהנים בסיני שנאמר ואתם תהיו לי ממלכת כהנים. . כל אחד ואחד מהן כאילו כהן גדול כו'. ובבעה\"ט עה\"פ: אלו זכו ישראל היו כולם כהנים גדולים, ולע\"ל תחזור להם שנא' (ישעי' סא, ו) ואתם כהני ה' תקראו."],["1695","163","<b>להבדיל. . החול</b>: שהוראת התורה היא גם נתינת כח והבטחה. וי\"ל הרמז בהלכה (רמב\"ם הל' אישות פרק טו\"ב בתחלתו — שיעור היום לפי החלוקה דג\"פ ליום): אין דין קדימה במטלטלין — כשיהודי עושה מכל עניניו וגם מעצמו מטלטלין מעוה\"ז החומרי לעוה\"ז ש\"נשמת\" העולם גוברת בו ומנהיגתו, בטלה טענת אקדמי' טעניתי' (זח\"ב קע, א)."],["1696","162","<b>להבדיל. . להורות. . ביד משה</b>: פרשתנו (שמיני) יו\"ד, י­יא. — סיום וחותם דשיעור יום זה."],["1697","164","<b>מחיש עוד יותר את הגאולה</b>: זריזות בהיציאה מן הגלות, והגאולה עצמה באופן ד\"בשובה ונחת תושעון\" (ישעי' ל, טו) — \"כי לא בחפזון תצאו ובמנוסה לא תלכון\" (שם נב, יב) — מכילתא עה\"פ בא יב, יא. שמו\"ר פי\"ט, ו. יל\"ש עה\"פ בא שם (רמז קצט). יל\"ש ישעי' עה\"פ כי לא בחפזון תצאו (רמז תעו). וראה ד\"ה וככה באוה\"ת בא כרך א ע' שה. כרך ח ס\"ע ב'תתקמא ואילך. המשך וככה תרל\"ז בסופו."],["1698","165","<b>בנין בית המקדש במקומו</b>: ראה רמב\"ם הל' מלכים ספי\"א."]]],[1301490272,"אנשים נשים וטף — \"כהנים בעבודתם ולויים בשירם ובזמרם<sup data-n=\"1699\">166</sup>\",\nובלשון התהלים<sup data-n=\"1700\">167</sup>, שהיא הוראה ובפרטי פרטים, בעבודת כל אחד מישראל: \"לבני קורח\" (שחידוש וההוראה שלהם היא עבודת התשובה וש\"אין לך דבר<sup data-n=\"1701\">169</sup> העומד בפני התשובה<sup data-n=\"1702\">170</sup>\", כמסופר על ידי חז\"ל<sup data-n=\"1703\">168</sup>) \"מזמור\" (— ויש לזמר ולשבח לה' \"בכלי\" — כלומר בכל השייך לאדם) \"שיר\" (— כך גם בפה<sup data-n=\"1704\">171</sup>, כלומר בגופו ובעצמו, ובאופן שמרגישים כי —) \"יסודתו\" (— כל זה חדור כי הוא מיוסד ומבוסס) \"בהררי\" (— בדרגות העליונות ביותר של —) \"קודש<sup data-n=\"1705\">172</sup>\".\nבכבוד ובברכה\nלחג הפסח כשר ושמח\nמקום החתימה\n<hr>",[["1699","166","<b>כהנים. . ובזמרם</b>: ע\"פ תפלת מוסף דיו\"ט."],["1700","167","<b>ובלשון התהלים</b>: התחלת מזמור פז דתהלים — להעיר מהמנהג לומר בכל יום הקאפיטל תהלים המתאים לשנות חייו — מכתב כ\"ק מו\"ח אדמו\"ר בקובץ מכתבים שבסו\"ס תהלים אהל יוסף יצחק ע' 214. אגרות­קודש שלו ח\"א ע' לא. ח\"י ע' נג. וראה גם מאמרי אדה\"ז הקצרים ע' שמא."],["1701","169","<b>אין לך דבר</b>: כי מקום נתבצר להם בגיהנם (סנהדרין ותנחומא שבהערה הקודמת) למטה גם מפתחו של גיהנם (ראה עירובין יט, א)."],["1702","170","<b>אין לך דבר העומד בפני התשובה</b>: ירושלמי פאה פ\"א ה\"א (ד, ב). רמב\"ם הל' תשובה ספ\"ג. זח\"ב קו, א. מדרש הנעלם בז\"ח ס\"פ בראשית (יט, ד). ועוד."],["1703","168","<b>לבני קורח. . עבודת התשובה. . כמסופר על ידי חז\"ל</b>: ראה סנהדרין קי, סע\"א. תנחומא קרח יא. זח\"ג נו, ב."],["1704","171","<b>מזמור. . בכלי. . שיר. . בפה</b>: לקו\"ת ברכה ד\"ה מזמור שיר חנוכת הבית (הא' — צח, ג): ד\"ה זה בסידור (עם דא\"ח) שער החנוכה רעז, ג­ד (וראה אוה\"ת וישב כרך ה תתקו, א). וראה לקוטי לוי\"צ לזח\"ג ע' רפב ואילך."],["1705","172","<b>קודש</b>: מלה בגרמי' (זהר ח\"ג צד, ב. נתבאר בסידור (עם דא\"ח) סדר סעודת שבת ר, ג ואילך)."]]],[1301490273,"ב\"ה, יום חמישי פ' תזריע<sup data-n=\"1706\">173</sup>,\nראש-חודש<sup data-n=\"1707\">176</sup> ניסן<sup data-n=\"1708\">177</sup><sup data-n=\"1709\">174</sup>, ה'תשמ\"ט<sup data-n=\"1710\">178</sup>\nברוקלין, נ.י.\nאל בני ובנות ישראל\nבכל מקום שהם\nה' עליהם יחיו\nשלום וברכה!\nראש-חודש ניסן<sup data-n=\"1711\">175</sup> חל תמיד באותו יום בשבוע שבו חל גם היום הראשון של חג הפסח. השנה הרי זה היום החמישי בשבוע<sup data-n=\"1712\">180</sup>, הוא היום בשבוע שבו היתה יציאת מצרים<sup data-n=\"1713\">179</sup>.\nחג הפסח הוא הראשון שבכל החגים, ובמיוחד של שלוש רגלים<sup data-n=\"1714\">181</sup>, פסח שבועות וסוכות<sup data-n=\"1715\">182</sup>, ראשון בזמן וגם בחשיבות כפי שהדבר מתבטא גם בכך שהשבת<sup data-n=\"1716\">183</sup> והחגים הם \"זכר ליציאת מצרים\": פסח הוא היסוד של כולם<sup data-n=\"1717\">184</sup>.",[["1706","173","<b>יום חמישי פ' תזריע</b>: ראה מכתב יום ה' פ' תזריע ר\"ח ניסן ה'תשמ\"ו הערה ד\"ה זה (הגש\"פ עם לקוטי טעמים, מנהגים וביאורים — קה\"ת תשמ\"ז — ע' תתפג (בהוצאת תנש\"א ע' תשעה))."],["1707","176","<b>חודש ניסן</b>: ראה מכתב הנ\"ל הערה ד\"ה זה (הגש\"פ הנ\"ל שם)."],["1708","177","<b>ניסן</b>: נסי נסים — ע\"פ ברכות נז, רע\"א ובפרש\"י. וראה חדא\"ג מהרש\"א שם. וראה מדרש לקח טוב עה\"פ (בא יב, ב) החודש הזה לכם: ניסן שבו נעשו נסים לישראל. וראה מכתב י\"א ניסן ה'תשמ\"ג הערה ד\"ה זה (הגש\"פ הנ\"ל ע' תשדמ)."],["1709","174","<b>ראש­חודש ניסן</b>: שאותו היום נטל עשר עטרות — שבת פז, סע\"ב. פרש\"י ר\"פ שמיני. וראה מכתב עש\"ק ר\"ח ניסן ה'תשמ\"ה הערה ד\"ה זה (הגש\"פ הנ\"ל ע' תשסא)."],["1710","178","<b>תשמ\"ט</b>: להעיר מהרמז בסימנה של שנת תשמ\"ט — \"ואשר יהי' לך את אחיך תשמט ידיך\" (ראה טו, ג), שהקב\"ה משמט כל החובות דבנ\"י (\"אחיך\", שנקראו אחים למקום, כמ\"ש \"למען אחי ורעי\" — תהלים קכב, ח. קה\"ר פ\"ד, ח (בתחילתה). זח\"ב קכב, רע\"א. ועוד. רש\"י שבת לא, א ד\"ה דעלך, משמו\"ר ר\"פ כז), וכשבטלה סיבת הגלות (ה\"חובות\" דבנ\"י, \"חטאינו\") בטל המסובב, הגלות, ובאה הגאולה האמיתית והשלימה תיכף ומיד."],["1711","175","<b>ראש­חודש ניסן</b>: דאז לכו\"ע, אפילו לדעת רשב\"ג (פסחים ו, סע\"א) \"שואלין ודורשין בהלכות הפסח קודם הפסח\". וראה שקלים רפ\"ג ובירושלמי שם. וראה ד\"ה החודש תרכ\"ו ס\"ד (סה\"מ תרכ\"ו ס\"ע מב ואילך)."],["1712","180","<b>חמישי בשבוע</b>: ובחו\"ל ה\"ה יום אחש\"פ וסעודת יו\"ט — יחד כל בנ\"י אוכלי שמורה מהדרין לאכול מצה שרוי'."],["1713","179","<b>היום החמישי בשבוע, הוא היום בשבוע שבו היתה יציאת מצרים</b>: שבת פז, ב. שו\"ע אדה\"ז או\"ח הל' פסח ר\"ס תל. וראה גם שם סתצ\"ד ס\"א."],["1714","181","<b>הפסח הוא הראשון. . של שלוש רגלים</b>: ר\"ה ד, א."],["1715","182","<b>שבועות וסוכות</b>: שהם המשך לחג הפסח — ראה מכתב יום ה' פ' תזריע ר\"ח ניסן ה'תשמ\"ו, ובהערה שם ד\"ה אַנדערע צוויי; מכתב י\"א ניסן ה'תשמ\"ו (הגש\"פ הנ\"ל ריש ע' תתפד. שם ע' תתפט (בהוצאת תנש\"א ע' תשעו. שם ע' תשפא))."],["1716","183","<b>שהשבת. . \"זכר ליציאת­מצרים\"</b>: ואתחנן ה, טו. — וראה מו\"נ ח\"ב פל\"א (הובא ברמב\"ן ואתחנן שם, יב). חינוך מצוה לב. וראה שער הכולל (להרא\"ד לאַוואוט) פי\"ז סכ\"ט."],["1717","184","<b>פסח. . היסוד של כולם</b>: ראה חינוך מצוה כא (סיפור יציאת מצרים): כי הוא יסוד גדול ועמוד חזק בתורתינו ובאמונתינו, וע\"כ אנו אומרים לעולם בברכותינו ובתפלתנו זכר ליציאת מצרים כו'."]]],[1301490274,"שלושת החגים הללו קשורים זה בזה בתוכן אחד, קווים ודינים זהים, השייכים לכל אלה במדה שוה, יחד עם זה יש לכל אחד מהם קווים ודינים ומנהגים משלו, שבהם הוא מצטיין ומתייחד: חג הפסח — \"זמן חירותנו<sup data-n=\"1718\">185</sup>\", חג השבועות — \"זמן מתן תורתנו\", חג הסוכות — \"זמן שמחתנו\", נוסף על ששלשתם הם — \"מועדים לשמחה<sup data-n=\"1719\">186</sup>\".\nהענין של שבת ויום טוב הוא שנוסף על כך שהימים האלה עצמם חדורים בקדושת שבת ובשמחת יום טוב — צריכה הקדושה והשמחה להימשך גם בימי החול ולחדור את חיי היום-יום של כל יהודי, אנשים ונשים וטף, במשך כל השנה<sup data-n=\"1720\">187</sup>.\nהשנה נוסף עוד ענין: זו \"שנה מעוברת<sup data-n=\"1721\">188</sup>\", אשר הודות לכך שמתווסף בה עוד חודש<sup data-n=\"1722\">189</sup>, \"מסתדר\" חג הפסח כ\"חג האביב\".\nהענינים האמורים (ועוד רבים שלא הוזכרו) כוללים הוראות כלליות ופרטיות רבות, עד לידי מעשה בפועל<sup data-n=\"1723\">190</sup>, הן לגבי ימי החג עצמם והן לגבי כל ימי השנה. על מספר נקודות נתעכב להלן.\n* * *\nהענין של שנה מעוברת ידוע, ודובר עליו פעמים רבות<sup data-n=\"1724\">191</sup>, שכן אין זו תופעה נדירה: שנה מעוברת מופיעה שבע פעמים במחזור של כל תשע-עשרה שנה<sup data-n=\"1725\">192</sup>, הוא המבטיח שחג הפסח יחול תמיד בתקופת האביב, כפי שדורשת התורה<sup data-n=\"1726\">193</sup> כיון",[["1718","185","<b>פסח. . זמן חירותנו</b>: ראה לקו\"ש חי\"ז ע' 71 ואילך (הגש\"פ הנ\"ל ס\"ע תקז ואילך). וראה גם מכתב ר\"ח ניסן ה'תשמ\"ג (הגש\"פ הנ\"ל ע' תשלד ואילך)."],["1719","186","<b>זמן חירותנו. . זמן מתן תורתנו. . זמן שמחתנו. . מועדים לשמחה</b>: כן נקראים בנוסח התפלה והקידוש."],["1720","187","<b>צריכה הקדושה והשמחה להימשך גם בימי החול. . כל השנה</b>: ראה מכתב ר\"ח ניסן ה'תשד\"מ, ובהערות שם (הגש\"פ הנ\"ל ע' תנשא)."],["1721","188","<b>שנה מעוברת</b>: הנקראת בשם \"שנה תמימה\" — בהר כה, ל. ערכין לא, א (במשנה). רמב\"ם הל' שמיטה ויובל פי\"ב ה\"ה. וראה אוה\"ת להצ\"צ (יהל אור) לתהלים יט, ח (ס\"ד וס\"ח — ע' סז­ח).\nולהעיר, אשר על מצות קידוש החודש ועיבור שנים נצטוו בר\"ח ניסן לפני יצי\"מ (בא יב, א ואילך) — ראה מכתב ר\"ח ניסן הנ\"ל, ובהערות שם (הגש\"פ הנ\"ל ס\"ע תשמז ואילך).\nוראה לקו\"א להה\"מ (הוצאת קה\"ת) סי' קכד. או\"ת (הוצאת קה\"ת) עה\"פ משכו וקחו (ל, סע\"א ואילך)."],["1722","189","<b>עוד חודש</b>: והוא חודש מלא — רמב\"ם הל' קידוש החודש פ\"ח ה\"ה (וראה \"פירוש\" שם פ\"ד ה\"א). טור או\"ח הל' ר\"ח סתכ\"ח."],["1723","190","<b>לידי מעשה בפועל</b>: שהמעשה הוא העיקר — אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["1724","191","<b>דובר עליו פעמים רבות</b>: ראה בארוכה מכתבי וא\"ו תשרי: ה'תשל\"ח (לקו\"ש חי\"ד ע' 478 ואילך); ה'תשד\"מ (לקו\"ש חכ\"ד ע' 633 ואילך); שנה זו (סה\"ש תשמ\"ט ח\"ב ע' 767). מכתב ר\"ח ניסן ה'תשד\"מ (הגש\"פ הנ\"ל ע' תשמז ואילך)."],["1725","192","<b>שנה מעוברת. . שבע פעמים במחזור של כל תשע­עשרה שנה</b>: רמב\"ם שם פ\"ו ה\"י: כל תשע עשרה שנה שיהיו מהן שבע שנים מעוברות ושתים עשרה פשוטות."],["1726","193","<b>הפסח. . בתקופת האביב, כפי שדורשת התורה</b>: משפטים כג, טו. תשא לד, יח. ראה טז, א. וראה סנהדרין יג, א­ב. ר\"ה כא, א. רמב\"ם שם פ\"ד ה\"א. וראה אוה\"ת משפטים ע' א'קפ ואילך. ד\"ה כי תבואו גו' ושבתה וד\"ה קדש ישראל לה' תר\"ל (סה\"מ תר\"ל ע' קלג ואילך. שם ע' רח ואילך). — בענין \"חודש האביב\" — ראה ל\"ת להאריז\"ל פ' בא בטעהמ\"צ (ד\"ה מצות קידוש חודש). אוה\"ת וד\"ה כי תבואו גו' ושבתה שם. ספר הליקוטים — דא\"ח צ\"צ ערך חדשים (פרטי החדשים) — ניסן ס\"י."]]],[1301490275,"ש\"ישראל מונין ללבנה<sup data-n=\"1727\">194</sup>\", חדשי השנה נקבעים לפי הירח<sup data-n=\"1728\">195</sup>, ושנת הירח קצרה במספר ימים<sup data-n=\"1729\">196</sup> משנת החמה — והוספת חודש בכל שנה שני' או שלישית<sup data-n=\"1730\">197</sup>, \"משווה\" את החשבון<sup data-n=\"1731\">198</sup>.\nמה שפורסם פחות הוא העובדה שבענין זה של שנה מעוברת ישנה נקודה פנימית — החיבור של השמש והירח<sup data-n=\"1732\">199</sup>, שכל אחד מהם שונה מחבירו: השמש — יום והירח — לילה<sup data-n=\"1733\">200</sup>, לשמש אור עצמי ואילו בירח משתקף אור השמש<sup data-n=\"1734\">201</sup>. לשמש ולירח יש פעילות עצמית ויחודית של כל אחד מהם, והם פועלים בזמנים נפרדים<sup data-n=\"1735\">202</sup>.\nמבחינה רוחנית וסמלית: השמש הוא \"משפיע\" (נותן) והירח \"מקבל<sup data-n=\"1736\">203</sup>\".\nכך גם בחיי האדם: יש \"משפיעים\" ויש \"מקבלים\", המשפיע והמקבל מהווים עולמות שונים, ומלבד העובדה שזה משפיע וזה מקבל, אין, לכאורה, קשר ביניהם. כך, לדוגמא, עלול לחשוב יהודי הנותן צדקה לעני שבעצם אין לו שייכות לעני, ובשעה שהוא עסוק עם עצמו, במיוחד בתורה ובמצוות ובתפלה, כאשר הוא רוצה לזרוח \"כשמש\" באור של \"נר מצוה ותורה אור<sup data-n=\"1737\">204</sup>\" — אין הזמן מוכשר לטפל בעני, כפשוטו, או ב\"עני\" ביהדות<sup data-n=\"1738\">205</sup> וכו' —",[["1727","194","<b>ישראל מונין ללבנה</b>: סוכה כט, א. וראה גם ב\"ר פ\"ו, ג. וראה ד\"ה ויאמר לו יהונתן מחר חודש תקס\"ז (סה\"מ תקס\"ז ע' מח ואילך. ועם הגהות — באוה\"ת בראשית ד, סע\"ב ואילך). ד\"ה זה במאמרי אדהאמ\"צ במדבר ח\"א ע' קכ ואילך. ובסה\"מ תרס\"ג ע' ע ואילך. ובכ\"מ."],["1728","195","<b>חדשי השנה נקבעים לפי הירח</b>: רמב\"ם ריש הל' קידוש החודש. וראה לקו\"ש חכ\"ו שיחה א' לפ' בא (ע' 63 ואילך)."],["1729","196","<b>קצרה במספר ימים</b>: ראה רמב\"ם שם פ\"א ה\"ב: וכמה יתרה שנת החמה על שנת הלבנה קרוב מאחד עשר יום. ובפירוט יותר — שם פ\"ו ה\"ד: נמצא תוספת שנת החמה על שנת הלבנה עשרה ימים ואחת ועשרים שעות ומאתים וארבעה חלקים. — ו\"יש מי שאמר (תקופת רב אדא). . תוספת שנת החמה על שנת הלבנה י' ימים וכ\"א שעה וקכ\"א חלק ומ\"ח רגע\" (שם פ\"י ה\"א)."],["1730","197","<b>בכל שנה שני' או שלישית</b>: ראה רמב\"ם שם פ\"ו הי\"א: שנים המעוברות שבכל מחזור. . הם שנה שלישית מן המחזור וששית ושמינית ושנת אחת עשרה ושנת ארבע עשרה ושנת שבע עשרה ושנת י\"ט."],["1731","198","<b>\"משווה\" את החשבון</b>: רמב\"ם שם פ\"א ה\"ב. פ\"ד ה\"א­ב."],["1732","199","<b>השמש והירח</b>: להעיר מתורת הה\"מ בענין \"ועינינו מאירות כשמש וכירח\" — או\"ת (הוצאת קה\"ת) פד, ד (בהוצאת תש\"מ ואילך — סי' רצז). אוה\"ת דרושים לר\"ה ע' א'ת ואילך. וראה גם מאמרי אדה\"ז על מארז\"ל (תפילה) ע' תס ואילך. ועוד."],["1733","200","<b>השמש — יום והירח — לילה</b>: ובלשון חז\"ל \"גבולות חלק הקב\"ה בעולמו יכולים אתם לערב יום ולילה (בתמי')\" — במדב\"ר פי\"ח, ז. תנחומא קרח ה. הובא בפרש\"י עה\"פ קרח טז, ה."],["1734","201","<b>בירח משתקף אור השמש</b>: ראה זהר ח\"א לג, ב (עה\"פ — בראשית א, יד — יהי מאורות ברקיע השמים). שם רלו, סע\"ב. רמט, ב. ובכ\"מ."],["1735","202","<b>לשמש ולירח. . פועלים בזמנים נפרדים</b>: להעיר גם מזהר שם רלו, סע\"ב. ובכ\"מ."],["1736","203","<b>משפיע. . מקבל</b>: ראה ד\"ה תקעו תרכ\"ח (סה\"מ תרכ\"ז ע' שצח ואילך). ובכ\"מ."],["1737","204","<b>נר מצוה ותורה אור</b>: משלי ו, כג."],["1738","205","<b>ב\"עני\" ביהדות</b>: ראה לקו\"ד ח\"ד תשכט, א. והוא ע\"פ תדא\"ר פכ\"ז."]]],[1301490276,"באה שנת העיבור ומלמדת, מזכירה ודורשת, שלא כך הדבר: ה\"שמש\" וה\"ירח\" אינם שני עולמות נפרדים, אלא משום העובדה ששניהם נוצרו על-ידי בורא-עולם אחד ושניהם מהווים חלקים של עולם אחד וזהה — יש ביניהם שייכות גדולה וקשר של אחד לרעהו, והקשר הוא תמידי ופנימי, כפי שרואים גם בטבע שהשמש אינה חדלה לזרוח<sup data-n=\"1739\">206</sup>, שכן כאשר במקום מסויים שורר לילה שורר במקום אחר היום באותה שעה.\nיתר על כן: דווקא על-ידי חיבור ה\"שמש\" וה\"ירח\", המשפיע והמקבל, מתבצעת הכוונה האלוקית.\nבמיוחד כשמדובר בשני יהודים, ששניהם חלק מ\"גוי אחד בארץ<sup data-n=\"1740\">207</sup>\", ורק מצד גופותיהם הם חלוקים ושונים, אבל מצד נשמתם, חלק אלוקה ממעל ממש<sup data-n=\"1741\">209</sup>, הם דבר אחד ממש<sup data-n=\"1742\">208</sup>.\nשנת העיבור מדגישה גם, שהמשפיע והמקבל (הן בנושא של השפעה גשמית, כגון עשיית טובה ליהודי בעניני פרנסה וכדומה, וכל-שכן ברוחניות) הם זוג קרובים ביותר, שהשגחה האלוקית מזמנת באופן מיוחד את שניהם ביחד במקום אחד ובזמן אחד, כדי שהמשפיע יתן למקבל, אך יחד עם זה \"יקבל\" ממנו דווקא, והמקבל יקבל מן המשפיע, אבל יחד עם זה יתן לו, ולו דווקא, ואף, אדרבה, יתן למשפיע יותר ממה שהלה נותן לו, בהתאם למאמר הידוע של תורתנו<sup data-n=\"1743\">210</sup> שיותר ממה שבעל-הבית עושה עם העני — עושה העני עם בעל-הבית.\n* * *\nויהי רצון שבתוך ההכנות לחג הפסח, יתבוננו כל אחד ואחת בנקודה האמורה, במיוחד בקשר למלים שמתכוננים להשמיע ולהדגיש בתחלת \"סדר\" הפסח: \"כל דכפין ייתי וכו' כל דצריך ייתי וכו'\".\nונזכה שיהא זה \"זמן חירותנו\" במלוא המשמעות, הגאולה האמיתית והשלימה<sup data-n=\"1744\">211</sup> על ידי משיח צדקנו.",[["1739","206","<b>השמש אינה חדלה לזרוח</b>: ראה גם מכתב ר\"ח ניסן וי\"א ניסן ה'תשד\"מ (הגש\"פ הנ\"ל ע' תשנ. שם ע' תשנה)."],["1740","207","<b>גוי אחד בארץ</b>: שמואל­ב ז, כג. דברי הימים­א יז, כא. וראה אגה\"ק ס\"ט (קיד, א). תו\"א וישב כז, סע\"ד. ועוד."],["1741","209","<b>חלק אלוקה ממעל ממש</b>: תניא רפ\"ב."],["1742","208","<b>מצד גופותיהם הם חלוקים ושונים, אבל מצד נשמתם. . דבר אחד ממש</b>: ראה תניא ר\"פ לב. רדב\"ז לרמב\"ם הל' ממרים פ\"ב ה\"ד."],["1743","210","<b>בהתאם למאמר הידוע של תורתנו</b>: ויק\"ר פל\"ד, ח (בסופה). רות רבה פ\"ה, ט (בתחילתה). וראה כש\"ט (הוצאת קה\"ת) בסופו (סי' תל — סג, ד ואילך)."],["1744","211","<b>הגאולה האמיתית והשלימה</b>: שאין אחרי' גלות (תוד\"ה ה\"ג ונאמר — פסחים קטז, ב, ממכילתא עה\"פ בשלח טו, א)."]]],[1301490277,"ויקויים תיכף ומיד היעוד<sup data-n=\"1745\">212</sup>: \"ולציון יאמר איש ואיש יולד בה<sup data-n=\"1746\">213</sup> והוא יכוננה עליון\", בקרוב בימינו ממש.\nבכבוד ובברכה\nלחג הפסח כשר ושמח<sup data-n=\"1747\">214</sup>\nמקום החתימה\n<hr>",[["1745","212","<b>היעוד</b>: תהלים פז, ה. וראה קונטרס משיחות ש\"פ בשלח שנה זו ס\"ט ובהערות שם (סה\"ש תשמ\"ט ח\"א ע' 217 ואילך); ש\"פ תצוה, ערב פורים קטן בסופה ובהערות שם (סה\"ש שם ע' 279)."],["1746","213","<b>יולד בה</b>: להעיר מהשייכות ליציאת מצרים (חג הפסח — זמן חירותנו) שנמשל ללידה — יחזקאל קאַפּיטל טז. וראה מכתב עש\"ק ר\"ח ניסן ה'תשמ\"ח, ובהערות שם<sup data-n=\"e306\">*</sup>."],["1747","214","<b>לחג הפסח כשר ושמח</b>: ראה לקוטי לוי\"צ אגרות ע' קצז. וראה מכתב י\"א ניסן ה'תשמ\"ו בסופו הערה ד\"ה ושמח (הגש\"פ הנ\"ל ע' תתצד. בהוצאת תנש\"א ע' תשפו)."],["e306","*","נדפס לעיל ע' 207 ואילך. המו\"ל.)"]]],[1301490278,"ב\"ה, מוצאי שבת הגדול<sup data-n=\"1748\">215</sup>,\nאור ליום<sup data-n=\"1749\">216</sup> א' י\"א<sup data-n=\"1750\">217</sup> ניסן<sup data-n=\"1751\">218</sup>, ה'תשמ\"ט\nברוקלין, נ.י.\nאל בני ובנות ישראל\nבכל מקום שהם\nה' עליהם יחיו\nשלום וברכה!\nבהמשך למכתב מראש-חודש ניסן, ובעמדנו ימים ספורים<sup data-n=\"1752\">219</sup> לפני חג הפסח, ראוי להתבונן במספר נקודות שהוזכרו במכתב הקודם, ובמיוחד ההתייחסות לקשר המיוחד שבין שנת העיבור וחג הפסח (כפי שזה השנה).\nבקשר לאמור הודגש הלימוד משנת העיבור, במובן של משפיע, נותן (— השמש, המקרינה אור במלוא פני') ומקבל (— הירח, שבו משתקף האור שהוא מקבל מן השמש).\nנקודת התוכן של הדברים היא, שהשמש והירח, שהם שני נבראים השונים באופיים, מזמן אותם הקב\"ה בחישוב משותף ובסדר קבוע, באופן שעל-ידי שניהם יחד (השמש והירח) מתבצעת הכוונה האלוקית שחג הפסח יחול תמיד בחודש האביב וכו'.\n— וכך גם בחיי האדם, בהם ישנם \"נותנים\" ו\"מקבלים\", שהם, לכאורה, עולמות שונים, הרי מנקודת מבט פנימית ומעמיקה הנותן הוא גם בד בבד מקבל והמקבל הוא גם בד בבד נותן, אשר ההשגחה האלוקית מזמנת אותם יחד<sup data-n=\"1753\">220</sup> כדי שעל-ידי שניהם יחד תתבצע הכוונה האלוקית, ותוך כדי כך, אדרבה, ה\"מקבל\" מעניק ל\"נותן\" יותר מאשר הנותן מעניק ל\"מקבל\", כפי שזה גם בדוגמא של שנת-העיבור שהיא גדולה יותר משנת-חמה.",[["1748","215","<b>שבת הגדול</b>: ראה תוד\"ה ואותו — שבת פז, ב. טושו\"ע (ואדה\"ז) או\"ח הל' פסח ר\"ס תל. וש\"נ. וראה לקו\"ש ח\"ז ע' 212 ואילך. חי\"ב ע' 33 ואילך. חי\"ז ע' 57 ואילך (הגש\"פ עם לקוטי טעמים, מנהגים וביאורים — קה\"ת תשמ\"ז — ע' תצ ואילך). שיחת שבת הגדול שנה זו (סה\"ש תשמ\"ט ח\"א ע' 385 ואילך). ולהעיר אשר הקביעות דשבת הגדול בשנה זו היא כבשנת יציאת מצרים."],["1749","216","<b>אור ליום</b>: ראה מסכת פסחים בתחילתה."],["1750","217","<b>י\"א</b>: ראה שיחת שבת הגדול שנה זו (סה\"ש שם ע' 388 ואילך)."],["1751","218","<b>י\"א ניסן</b>: נשיא לבני אשר — שו\"ע אדה\"ז שם סט\"ו. וראה שם ס\"ט. וראה לקוטי לוי\"צ אגרות ע' שכג­שכה. שם ע' תיט. וראה מכתבי י\"א ניסן: ה'תשד\"מ הערה ד\"ה זה; ה'תשמ\"ה הערה ד\"ה אשר (הגש\"פ הנ\"ל ע' תשנג. שם ע' תשסז)."],["1752","219","<b>ימים ספורים</b>: ראה מכתב י\"א ניסן ה'תשמ\"ה הערה ד\"ה געציילטע טעג (הגש\"פ הנ\"ל ע' תשסז)."],["1753","220","<b>השגחה האלוקית מזמנת אותם יחד</b>: ראה כש\"ט (הוצאת קה\"ת) הוספות סי' קכו."]]],[1301490279,"וכאן אנו מגיעים להמשך, להבין ביתר עומק את הקשר ההדדי בין המשפיע והמקבל.\n* * *\nאצל יהודים מתבטא בענין זה של משפיע ומקבל קשר עמוק יותר — שייכות הדדית שלגביה שניהם יחד, המשפיע והמקבל, נעשים דבר אחד שלם, מציאות אחת.\nכיוון שכאמור קשור הענין של שנת-העיבור קשר הדוק עם חג הפסח, אנו מוצאים את הנקודה האמורה — ההתאחדות של חלקים שונים שמהם נוצר דבר אחד — בעניני חג הפסח, ובמיוחד בענין קרבן הפסח (שגם עליו נצטוו בראש-חודש ניסן<sup data-n=\"1754\">221</sup> במצרים כמו על מצוות עיבור שנים וקידוש חדשים<sup data-n=\"1755\">222</sup>).\nקרבן הפסח שונה מכל הקרבנות<sup data-n=\"1756\">223</sup> האחרים, הן מן הסוג של קרבן-צבור והן מן הסוג של קרבן-יחיד<sup data-n=\"1757\">224</sup>, בפרטים שונים הקשורים אך ורק בקרבן הפסח.\nאחד הפרטים האמורים הוא, שקרבן הפסח הוא צריך להיות קרב \"ראשו על כרעיו ועל קרבו<sup data-n=\"1758\">225</sup>\". השוני והמרחק בין הראש לבין הכרעים וכו' מובן מאליו, ועם זאת נדרש שכל החלקים יקרבו יחד ובאופן זהה<sup data-n=\"1759\">226</sup>.\nכן נדרש שקרבן הפסח ייקבע רק ל\"מנויים\"<sup data-n=\"1760\">227</sup> — אנשים שנמנו מראש, יחידים שהתאחדו ליחידה אחת כדי להביא ולאכול<sup data-n=\"1761\">228</sup> את קרבן הפסח כולם יחד בחבורה אחת<sup data-n=\"1762\">229</sup> דוקא<sup data-n=\"1763\">230</sup> ובמחיצה אחת. ההשתתפות של כל אחד מהם היתה שונה אך כולם אכלו על השובע<sup data-n=\"1764\">231</sup>.",[["1754","221","<b>קרבן הפסח. . עליו נצטוו בראש­חודש ניסן</b>: בא יב, א ואילך. ולקיחתו היתה בעשור בחודש — שבת הגדול דשנה ההיא."],["1755","222","<b>על מצוות עיבור שנים וקידוש חדשים</b>: ראה מכתב ר\"ח ניסן ה'תשד\"מ, ובהערות שם (הגש\"פ הנ\"ל ס\"ע תשמז ואילך)."],["1756","223","<b>קרבן הפסח שונה מכל הקרבנות</b>: בהבא להלן ראה גם לקו\"ש חי\"ח ע' 104 ואילך (הגש\"פ הנ\"ל ע' שנד ואילך). מכתב עש\"ק שבת הגדול ה'תשל\"ט (הגש\"פ הנ\"ל ע' תרצו ואילך)."],["1757","224","<b>הן מן הסוג של קרבן­צבור והן מן הסוג של קרבן­יחיד</b>: ובלשון הרמב\"ם (בפיה\"מ שלו בהקדמתו לסדר קדשים): והמין הרביעי קרבן יחיד דומה לקרבן ציבור והוא קרבן פסח."],["1758","225","<b>ראשו. . קרבו</b>: בא יב, ט. פסחים ע, רע\"א במשנה. רמב\"ם הל' ק\"פ פ\"ח ה\"י."],["1759","226","<b>ובאופן זהה</b>: צלי אש — בא שם, ח. פסחים צה, רע\"א במשנה. רמב\"ם שם ה\"ד."],["1760","227","<b>שקרבן הפסח. . רק ל\"מנויים\"</b>: זבחים נו, ב במשנה. רמב\"ם שם רפ\"ב."],["1761","228","<b>כדי. . ולאכול</b>: שאכילת קרבן פסח היא עיקר בו יותר מבשאר קרבנות — שמעיקרו לאכילה ניתן (משנה פסחים עו, ב)."],["1762","229","<b>בחבורה אחת</b>: \"המתמנים על הפסח הם הנקראים בני חבורה\" (רמב\"ם שם), ו\"כל האוכל מן הפסח אינו אוכל אלא בחבורה אחת\" (רמב\"ם שם רפ\"ט)."],["1763","230","<b>בחבורה אחת דוקא</b>: ובאכילתו פניהם זא\"ז (ראה פסחים פו, א (במשנה). רמב\"ם הל' ק\"פ פ\"ט ה\"ג)."],["1764","231","<b>על השובע</b>: פסחים ע, א. רמב\"ם שם פ\"ח ה\"ג."]]],[1301490280,"והתאחדות זו של בני ישראל, שבאה לידי ביטוי בולט בקרבן הפסח, היתה ההכנה לגאולה<sup data-n=\"1765\">232</sup> של כל כלל ישראל — ממשה רבנו ועד לקטן שבישראל — כשכולם יחד נגאלו ברגע אחד<sup data-n=\"1766\">233</sup>, בחצות הלילה<sup data-n=\"1767\">234</sup>, והגאולה היתה לא על-ידי מלאך ולא על-ידי שליח אלא על-ידי הקב\"ה בכבודו ובעצמו<sup data-n=\"1768\">235</sup>, וכולם יצאו ממצרים בעצם היום הזה — בו ברגע<sup data-n=\"1769\">236</sup> וביד רמה<sup data-n=\"1770\">237</sup> (בלשון יחיד).\n* * *\nויהי רצון שההתבוננות בענינים האמורים, ההוראה הכללית מחג הפסח שחל בשנת-עיבור (כמו השנה), תחזק יותר אצל כל אחד ואחת את ההכרה, שכל יהודי — איש ואשה וילד — הוא משפיע ומקבל, ויתירה מזו — הם שייכים לגוי אחד<sup data-n=\"1771\">238</sup>, ויתירה מזו — הם כאיש אחד, ויתירה מזו — הם לב אחד<sup data-n=\"1772\">239</sup>.\nאחדות יהודית אמיתית היא כאשר יודעים וחשים שכל היהודים הם דבר אחד ממש<sup data-n=\"1773\">240</sup>, וממילא היחס של יהודי אחד לשני הוא ממש כמו אל עצמו הוא, וכיוצא בזה.\nודבר זה יהווה ודאי ההכנה השלימה לגאולה האמיתית והשלימה על ידי משיח צדקנו.\n— זה גם התוכן של בקשתו הפנימית של דוד, נעים זמירות ישראל<sup data-n=\"1774\">241</sup>, מן הקב\"ה: \"תבוא לפניך תפלתי, הטה אזנך לרינתי<sup data-n=\"1775\">242</sup>\", שתפלתי תבוא אליך ואל פניך כך שהתפלה (מלשון חיבור<sup data-n=\"1776\">243</sup>) תהיה ל\"רינה\" (שירה) — השתפכות הנפש והתחברות עם הקב\"ה, התמזגות הנשמה עם מקורה — הקדוש ברוך הוא.",[["1765","232","<b>בקרבן הפסח. . ההכנה לגאולה</b>: ראה מכילתא ופרש\"י עה\"פ בא יב, ו. נתבאר בלקו\"ש חט\"ז שיחה ג' לפ' בא — ע' 114 ואילך (הגש\"פ הנ\"ל ע' רכד ואילך)."],["1766","233","<b>ברגע אחד</b>: ראה מכתב י\"א ניסן ה'תשד\"מ (הגש\"פ הנ\"ל ע' תשנד ואילך). וש\"נ."],["1767","234","<b>בחצות הלילה</b>: ראה ברכות ט, סע\"א. פרש\"י עה\"פ ראה טז, א. וראה לקו\"ש ח\"ו ע' 69 (הגש\"פ הנ\"ל ע' תמא). מכתב הנ\"ל."],["1768","235","<b>לא על­ידי מלאך. . שליח אלא על­ידי הקב\"ה בכבודו ובעצמו</b>: הגש\"פ פיסקא ויוציאנו."],["1769","236","<b>בעצם היום הזה — בו ברגע</b>: בא יב, מא. שם, נא. וראה מכתב י\"א ניסן הנ\"ל."],["1770","237","<b>ביד רמה</b>: בשלח יד, ח. וראה תו\"א מג\"א צה, ד. לקו\"ת נשא כא, ב ואילך. ובכ\"מ."],["1771","238","<b>גוי אחד</b>: שמואל­ב ז, כג. דברי הימים­א יז, מא. וראה אגה\"ק ס\"ט. תו\"א תולדות כז, ד. מקץ לה, א. ויקהל פז, סע\"ג."],["1772","239","<b>כאיש אחד. . לב אחד</b>: פרש\"י יתרו יט, ב."],["1773","240","<b>שכל היהודים הם דבר אחד ממש</b>: ראה אגה\"ק ס\"ב (קלה, ב). וראה ירושלמי נדרים פ\"ט ה\"ד. סהמ\"צ להצ\"צ מצות אהבת ישראל. וראה לקו\"ש חי\"ח ע' 115 (הגש\"פ הנ\"ל ע' שסו)."],["1774","241","<b>דוד, נעים זמירות ישראל</b>: שמואל­ב כג, א. וראה שהש\"ר פ\"ד, ד (בתחילתה) — שאמר ה\"זמירות (בשם כל) ישראל\"."],["1775","242","<b>תבוא. . לרינתי</b>: תהלים פח, ג. — ע\"פ המנהג לומר בכל יום הקאפיטל תהלים המתאים לשנות חייו (מכתב כ\"ק מו\"ח אדמו\"ר בקובץ מכתבים שבסו\"ס תהלים אהל יוסף יצחק ע' 214. אגרות­קודש שלו ח\"א ע' לא. ח\"י ע' נג. וראה גם מאמרי אדה\"ז הקצרים ע' שמא) — הותחל בי\"א ניסן שנה זו אמירת מזמור פ\"ח שבתהלים."],["1776","243","<b>תפלה (מלשון חיבור)</b>: תו\"א תרומה עט, סע\"ד. סה\"מ תרל\"ד ע' קנד (וראה בהנסמן שם הע' 1). תרפ\"ג ע' רטו (וסה\"מ ה'תש\"ט ע' 79 הב'), ובהערה שם."]]],[1301490281,"שזו גם נקודת התוכן של \"יציאת-מצרים\" בכל יום<sup data-n=\"1777\">244</sup>, יציאה ממיצרים ומגבולים<sup data-n=\"1778\">245</sup>, עד להתאחדות עם אין-סוף ברוך הוא.\nעד שנזכה כולנו יחד בקרוב ממש לגאולה האמיתית והשלימה, עד — לקיום ההבטחה: כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"1779\">246</sup>.\nבכבוד ובברכה\nולחג הפסח כשר ושמח<sup data-n=\"1780\">247</sup>\nמקום החתימה\nוראה בהערות למכתב מוצש\"ק פ' ויק\"פ, כ\"ה אדר ה'תשמ\"ב בתחלתו (הגש\"פ עם לקוטי טעמים, מנהגים וביאורים — קה\"ת ה'תשמ\"ו ואילך — ע' תשכב).\nובעץ יוסף לעין יעקב ליבמות שם: והוא אמר זה מסברא דנפשי', והוא מפורש בבמדבר רבה פ\"ח, ד (כב, ד): ואלו אין בהם אחד מאלה מיד עמד וריחקם. וביפה תואר שם.\n— ולהעיר — מלשון הרמב\"ם הל' איסו\"ב פי\"ט הי\"ז: ובגבעונים. . לפי שהעיזו פניהם ולא נתפייסו ולא רחמו. . ולא גמלו — היינו שלא הי' בהם אפילו סימן א'.\nוהוא השבת שלפני החג, ו\"נהגו בדורות האחרונים שהחכם דורש הלכות פסח בשבת שלפניו. . והעיקר לדרוש ולהורות דרכי ה' וללמד להם המעשה אשר יעשון\" (שו\"ע אדה\"ז שם סתכ\"ט ס\"ב. וש\"נ).\n<hr>",[["1777","244","<b>\"יציאת­מצרים\" בכל יום</b>: ומזכיריו יציאת מצרים בכל יום, ביום ובלילה — רמב\"ם הל' ק\"ש פ\"א ה\"ג. שו\"ע אדה\"ז או\"ח סי' סז."],["1778","245","<b>\"יציאת­מצרים\". . ממיצרים ומגבולים</b>: ראה תניא פמ\"ז. תו\"א וארא נז, ב ואילך. בשלח סד, א­ב. שער האמונה לאדמו\"ר האמצעי פכ\"א (לט, א ואילך). ד\"ה ויהי בעצם היום הזה תרנ\"ה (סה\"מ תרנ\"ה ע' עא ואילך). ובכ\"מ."],["1779","246","<b>כימי צאתך. . נפלאות</b>: מיכה ז, טו. וראה אוה\"ת נ\"ך עה\"פ ס\"ק ז­ח (ע' תפז), מזח\"א בהשמטות סכ\"ה (רסא, ב). פע\"ח שער חג המצות פ\"ו (בד\"ה מהר\"י ז\"ל). וראה ד\"ה כימי צאתך די\"א ניסן ה'תשמ\"ב (סה\"מ מלוקט ח\"ב ע' לז)."],["1780","247","<b>לחג הפסח כשר ושמח</b>: ראה לקוטי לוי\"צ אגרות ע' קצז."]]],[1301490282,"<b>נוסח המברק שהואיל כ\"ק אדמו\"ר שליט\"א </b>\n<b>לשלוח לאנ\"ש שי' בכל מרחבי תבל </b>\n<b>לקראת חג הפסח, ה'תשמ\"ז</b>\nביום ההילולא של אדמו\"ר הצמח צדק ואור לי\"ד ניסן זמן הפסח\nאביע איחולי וברכותי ליום טוב הפסח כשר ושמח, מתאים לראשיתו יום השלישי שהוכפל בו כי טוב טוב לשמים וטוב לבריות\nולקיומה בקרוב ממש בעגלא דידן: תפלה לדוד (נעים זמירות (בשם כל אחד ואחת מ)ישראל) שמח נפש עבדך גו' כי חסדך גדול עלי, בגאולה האמתית והשלימה ע\"י מלכא משיחא.\nבכבוד ובברכת החג\nמקום החתימה\nשמח. . עלי: תהלים פו, ד. שם, יג.\n<hr>\n<b>נוסח המברק שהואיל כ\"ק אדמו\"ר שליט\"א </b>\n<b>לשלוח לאנ\"ש שי' בכל מרחבי תבל </b>\n<b>לקראת חג הפסח, ה'תשמ\"ח</b>\nביום ההילולא של אדמו\"ר הצמח צדק ואור לי\"ד ניסן זמן הפסח וערב שקויו\"ט\nאביע איחול?י וברכותי לחג הפסח כשר ושמח וכולי. וש\"ק ושלום שהוא ראשיתו, עונג וחירות בשלמותם לכל בנ\"י בכל מושבותיהם.\nותקויים בקשת כל אחד ואחת האנשים והנשים והטף<sup data-n=\"1781\">1</sup> בתוך כלל ישראל ועד לאופן דהקהל בציון שהוי' יכוננה עליון<sup data-n=\"1782\">2</sup> בגאולה האמתית והשלימה על ידי משיח צדקנו.\nבכבוד ובברכת שבת והחג\nמקום החתימה\n<hr>",[["1781","1","וילך לא, יב."],["1782","2","תהלים פז, ה."]]],[1301490283,"<b>נוסח המברק שהואיל כ\"ק אדמו\"ר שליט\"א </b>\n<b>לשלוח לאנ\"ש שי' בכל מרחבי תבל </b>\n<b>לקראת חג הפסח, ה'תשמ\"ט</b>\nביום השלישי שהוכפל בו כי טוב, יום ההילולא של אדמו\"ר הצמח צדק ואור לי\"ד ניסן,\nאביע אחולי וברכותי לחג הפסח כשר ושמח וכולי ולקיום בעגלא דידן, וכמפורש<sup data-n=\"1783\">*</sup> בספר דוד מלכא משיחא: הוי' אלקי ישועתי תבוא לפניו תפלתנו ויטה אזניו לרנתנו ויגאלנו בגאולתנו האמתית והשלימה תיכף ומיד ממש.\nבכבוד ובברכת החג\nמקום החתימה",[["1783","*","וכמפורש: ע\"פ תהלים פח, ב­ג."]]],[1301490284,"<h3>ספירת העומר</h3>\n... בהנוגע לנסיעת כת\"ר שי', כבר מלתי אמורה<sup data-n=\"1784\">*</sup> שאין דעתי נוחה כלל — לעבור קו התאריך באמצע ימי הספירה, כי אף שמצד הדין דעתי ברורה, שבהנוגע לחג השבועות תלוי אך ורק במספר הימים, ומספר זה מסור לכל אחד ואחד — ובמילא העובר את קו התאריך אין לו להתחשב כלל בזמן חגיגת חג השבועות דבנ\"י למקום שם בא, כ\"א לחוג אותו ביום החמשים למספרו הוא [שאז הוא משונה ביום אחד מחגיגת היהודים דרי המקום — כמובן באם לא יעבור קו התאריך בכיוון הפכי באמצע ימי הספירה] וכנ\"ל דעתי ברורה בהאמור — אבל בכ\"ז תמיהא מילתא ביותר [ובפרט שלדעתי החילוק הוא — מן התורה] שלכן יש להשתמט מלהכנס בהנ\"ל ככל האפשרי.\n<span data-k=\"q\">(ממכתב כ' שבט, תשכ\"א)</span>\n<hr>",[["1784","*","ראה לקו\"ש ח\"ג ע' 995 ואילך. ח\"ז ע' 285 ואילך. חי\"ב ס\"ע 168 ואילך. חי\"ז ס\"ע 466 ואילך. חכ\"ז ע' 335. המו\"ל."]]],[1301490285,"<h3>שמיני</h3>\nשלום וברכה!\nבנועם נודעתי ע\"ד עריכת סיום חלק השלישי של ספר התניא, הוא אגרת התשובה, ביום ראשון פרשת אמור וגו' ואמרת, פסח שני.\nויהי רצון אשר כבכל ענין דגמרה של תורה, סיום איזה ענין בתורתנו, ובפרט כשנעשה ברבים, יתוסף עי\"ז בלימוד התורה, כולל — גם בהחיות ואור שבלימוד זה, והוספה האמורה ע\"י הלומדים, הרי הובטחנו בזה ובכגון זה, וכסיום וחותם אגרת התשובה הנ\"ל, אדם מקדש עצמו מעט מלמטה מקדשין אותו הרבה מלמעלה.\nולא עוד אלא שמוסיף ביאור בזה: וכמ\"ש לעיל וכו' בחי' סוכ\"ע, ז.א. אשר הקידוש מלמעלה הוא לא רק הרבה בכמות, אלא גם באיכות, ולא עוד אלא — שבאין ערוך, אין ערוך דסובב כל עלמין לגבי ממלא כל עלמין.\nומההמשך תיכף לאחר זה: וככה ממש הוא בענין שכר וכו', מובן שככל האמור הוא גם בהנוגע לשכר מצוה האמורה, שכר בעולם הבא ובעולם הזה, שהרי תלמוד תורה הוא מהדברים שאדם אוכל פירותיהם בעולם הזה והקרן קיימת לעולם הבא. . .\n<span data-k=\"q\">(ממכתב ז' אייר, תשכ\"ד)</span>"],[1301490286,"<h3>תזריע</h3>\nבמענה למכתבו, וכבקשתו בא המענה מבלי לחכות על התור.\nבו כותב בשאלה אודות אשה, ששני פעמים כבר עשו לה נתוח קסרי (לידה באופן דיוצא דופן) וכיון שהיא עומדת עתה ללדת, מציע הרופא באם שגם בפעם הזאת, תהי' הלידה באופן האמור, אז לדעתו יש חשש באם תתעבר עוד הפעם, ולכן רוצה לעשות לאחרי הלידה, מעין נתוח באופן שלא תוכל להתעבר עוד.\nוהנה בכלל אין עניני לפסוק דינים, אבל מה שלכאורה פלא בהאמור, שהרי ידוע דעת הרופאים (דוקא בשנים האחרונות), שגם לאחרי שהיתה לידה באופן יוצא דופן, אפשרית לידה באופן נורמלי, כן לדעתם אין הגבלה מצד הבריאות, במספר לידות באופן יוצא דופן, כי אם תלוי במצב בריאות הכללי של האשה בעת הלידה, ז.א. שאין להחליט בהנוגע לחשש עבור ולידה כ\"א בהתאם למצב בריאות אז, ובזה הרי כמה תרופות להחזקת הבריאות בכלל, וגם לחיזוק האם וכיו\"ב."],[1301490287,"עוד זאת, ידוע פסק דין אדמו\"ר הצמח צדק, שבמקום חשש בעיבור כנ\"ל מתיר לשמש במוך, וע\"פ הטעמים נראה שזה קל יותר מאשר ע\"י נתוח ששוללים לגמרי אפשרית עבור.\nועוד להוסיף (ובטח גם זה יסבירו הרופא), כי על פי הרוב, הנתוח למניעת עבור, נעשה באופן שהם קושרים (וסותמים) את הצנורות אשר באשה, ולפעמים קרובות, קורה, אשר קשירה זו מתפרדת, ואפשרית העבור חוזרת לקדמותה אלא שאין יודעים עד\"ז, במלות אחרות, מצד המטרה להזהר מעבור, צריך עיון מה טוב יותר, האם באופן דפסק הצמח צדק הנ\"ל או באופן דקישור הצנורות הנ\"ל.\nועוד נקודה להוסיף וגם היא עיקר, שבכלל על פי החקירה ודרישה בשטח חכמת הרפואה בשנים האחרונות, עלול כל יום ויום לחידושים ותגליות שלכן על האדם להמנע לעשות ענינים כאלה, שאי אפשר לשנותם לאחרי כן, אפילו באם יתחדש טפול השולל הכרח הענין שעשו.\nכיון שכותב אשר הרופא הנ\"ל הוא שומר תורה ומצות, נוסף על היותו מומחה בהענין, מהנכון אשר לאחרי שיברר נקודות האמורות אצל רופא מומחה אחר באופן פרינציפיוני, ידבר עוד הפעם עם הרופא השומר תומ\"צ ויברר כל הנ\"ל.\nוהשי\"ת המשגיח על כאו\"א בהשגחה פרטית, יראם הדרך הנכונה איך להתנהג בהאמור.\nואכפול ברכתי אשר השי\"ת ימלא ימי הריונה כשורה ובנקל ותלד זחו\"ק בעתה ובזמנה כשורה ובקל.\nבברכה לבשו\"ט.\n<span data-k=\"q\">(ממכתב י\"ג טבת, תש\"כ)</span>\n... במ\"ש בסיום מכתבו על הקס\"ד להשתמש עם עלעקטרי<sup data-n=\"1785\">*</sup> — הרי אינו מפרט כוונתו בזה, כי השם עלעקטרי כולל כמה אופני טפול, ואם הכוונה להקרנה (באשטראלונג) יש להשתמט מזה, ואם הכוונה רק להמם ע\"י שמוליכין זרם עלעקטרי (מען לאָזט דורך עלעקטרישען שאָק) מובן שדרושה בזה זהירות, אבל באם רק איזה פעמים יש מקום לסברא זו כשנעשית ע\"י מומחה, ובכללות הדבר ובכדי להיות בטוח בכללות ההוראות יש לשאול עכ\"פ פעם אחת דעת רופא מומחה שיקבע הדיאַגנאָזע וכללות הטפול, ואם לא נמצא כזה ב... בודאי ישנו בעיר גדולה, והשי\"ת יצליחו לבשר טוב בעניניהם הכללים ובעניניהם הפרטים.\n<span data-k=\"q\">(ממכתב כ\"א טבת, תשי\"ז)</span>\n<hr>",[["1785","*","למחלתה ברחם המונעת העיבור. המו\"ל."]]],[1301490288,"... ולכתבו אודות ציווי הרופאים על זוגתו תחי' להמנע מהריון, ושאל דעת רב בזה, והתיר לו אמצעים שונים בזה, שמונה אותם במכתבו.\nולפלא שאין מזכיר ענין פשוט וביחד עם זה יעיל, ובפרט בצירוף עם האמצעים שכותבם, והוא אשר בנדון (דידי') שהרב מפורש התיר וכו' לדחות הטבילה לימים אחדים כפי שיורה אותו הרופא המכיר זוגתו תחי' ויודע ג\"כ היום שעלולה ביותר להכנס להריון וע\"פ רוב מספיק איחור של ב' ג' ימים וכו' וידבר בכל האמור עם הרב והרופא, ויורוהו.\nע\"פ סגנון מכתבו, תקותי שלמותר להדגיש על הכרח הנהגה בחיי היום יומים שתהא מתאימה להוראות תורתנו תורת חיים ובקיום מצותי' עליהם נאמר וחי בהם, שנוסף על העיקר שכן הוא ציווי השם הרי זה גם הדרך לקבלת ברכת השם בכל המצטרך, ובפרט כשזקוקים לברכה מיוחדת. — במקרה שלהם ההדגשה בפרט על הזהירות כדבעי בכל דיני טהרת המשפחה.\nומהנכון אשר יבדקו את התפילין שלו, וכן את המזוזות בדירתם שתהיינה כולן כשרות כדין, וזוגתו תחי' תשמור על מנהגן הטוב של בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב.\nתפירת השיחלות — נוסף על החששות שישנם בכל ניתוח ובפרט ניתוח הפנימי ובמיוחד — במצב בריאות רופף (ובכמה פרטים גם לא ברור כנראה ממכתבו) — יש בזה כמה צדדים שליליים: א) זוהי פעולה לשלול ההריון לתמיד, אפילו לכשתבריא וכו'. ב) חששות מצד הדין, כפי שיבארו הרב שלו. ג) היו מקרים שלמרות התפירה נכנסה לאח\"ז להריון (ביאור הרגיל ע\"ז, כי כנראה שהתפירה התפרקה מאלי', ולהיותה בפנים א\"א לדעת עד\"ז)...\n<span data-k=\"q\">(ממכתב כ\"ג שבט תשכ\"ה)</span>\n<hr>\n... כותבת אודות משאלות לבבם לטובה שיברכם השם יתברך בעוד ילדים חיים וקיימים נוסף על הבת שלהם שתליט\"א ומוסיפה אשר בעלה לא רצה לשאול דעת רופא, מפני מה זה איזה שנים שלא נפקדו בבנים.\nוהנה ידוע הנהגת התורה אשר אף שהשם יתברך הוא בורא העולם ומנהיגו והרופא כל בשר ומפליא לעשות, בכל זה צריך האדם לעשות מה גם בדרך הטבע, ובלשון חכמנו זכרונם לברכה, התורה נתנה רשות לרופא לרפאות, ולכן צריך לדבר עוד הפעם עם בעלה שי' אשר הוא וגם היא יתבקרו על ידי רופא מומחה במקצוע ויעשו כהוראתו.\nומובן שביחד עם זה צריכים להוסיף שניהם בעניני תורה ומצות וביחוד"],[1301490289,"בשמירת חוקי ודיני טהרת המשפחה צניעות וכיוצא בזה וכן בנתינתם לצדקה, ולהתפלל לנותן התורה והמצוה שימלא משאלות לבבם האמורות לטובה.\nומהנכון שיבדקו התפילין של בעלה ואת המזוזות בדירתם שיהיו כולן כשרות כדין, והיא תשמור על מנהגן הטוב של בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב למילוי משאלות לבבם האמורות.\nכנראה ממכתבה הנה היא בת כהן, ואם הבעל שלה אינו כהן, אזי נוסף על כל האמור לעיל, נכון שיהי' בעלה בקי בתוכן איזה מסכת ממסכתות הש\"ס ויכול להיות גם במסכתות קטנות וכמו מסכת כלה וכיו\"ב.\nבברכה לבשורות טובות.\n<span data-k=\"q\">(ממכתב כ\"ג שבט, תשי\"ז)</span>\n<hr>\nמאשר הנני קבלת מכ' ובו בקשת ברכה פ\"נ מיום 318.\nובעת רצון יקרא על ציון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.\nועליהם לדייק בחוקי ודיני טהרת המשפחה (נדה, הפסק טהרה, טבילה במקוה כשרה וכו'), וכיון שלפעמים במשך הזמן נשכחים פרטי דינים, ובנדו\"ז דיני טהרת המשפחה — כדאי שיחזרו על כל ההלכות הצריכות בזה.\nתספר לרב מורה הוראה בעירה אודות מצבה ודברי הרופאים — ובאם יאמר שע\"פ שו\"ע מותר לה להכנס להריון, תשתדל בזה, והשם יצליחה.\n<span data-k=\"q\">(ממכתב כ\"ו ניסן, תשמ\"ו)</span>\n<hr>\n... במ\"ש אודות מחשבת זוגתו תחי' ודאגותי' במילוי משאלות לבבם לטובה, כבר יודע אז וואס ווייניגער מען טראכט אין דעם איז אלץ מער מעלה, והשי\"ת יצליחו לבש\"ט בכל האמור.\n<span data-k=\"q\">(ממכתב ו' תשרי, תשי\"ז)</span>\n<hr>\n... במש\"כ ע\"ד מגע בעת ההריון ובגמרו — לא בירר ספקו, אם בנדו\"ד שיש"],[1301490290,"איזה חשש מצד הדין (ואז יפרשו לפני רב והוא יורהו), או מצד הטבע והבריאות, שאז אף שידוע מרז\"ל בזה (נדה לא, א) — כבר פסקו שנשתנו הטבעים (ראה רמ\"א בשו\"ע אה\"ע סקנ\"ו ס\"ד, שו\"ת מהר\"מ שיק חיו\"ד סרמ\"ד. שד\"ח כללים מע' ט' ס\"ה וש\"נ). [ולהעיר מרמב\"ם (הל' גירושין פי\"א הכ\"א). ובטעמי מצות — לרח\"ו — פ' בראשית ד\"ה ובענין העונה], — ולכן צריך לשאול דעת רופא מומחה בזה. ובפרט בנדו\"ד שראתה כתמים וכו'. ואכמ\"ל.\n<span data-k=\"q\">(ממכתב י\"ד מנ\"א, תשי\"ז)</span>\n<hr>\n... בהנוגע צו דעם אונטערזוכונג פון דעם דאָקטאָר, בכלל איז דער גאַנצער ענין פון דעם אונטערזוכען מער ניט ליתר שאת, און דעריבער דאַרף'ן אויסמיידען אַ אינוועניגסטע אונטערזוכונג אויף וויפיל עס איז מעגליך, און כמדומה ברור, אַז אַ חוץ אַ צוגאָב אין דער ידיעה פון דאָקטאָר, איז ניט פראַן קיין אַנדער נוצען אין דעם, און דעריבער איז אויף אַ איידעלען אופן ניט צו אָנרירען די געפילען פון דעם דאָקטאָר, דאַרפמען זיך אויסמיידען פון דעם, און האָפענטליך וועט דער ד\"ר ניט דוקא באַשטיין אויף דעם, זעהענדיק אַז מען איז ניט צופרידען פון דעם, און וויסענדיק פאַר זיך אַליין, אויף וויפיל דאָס איז ניט מוכרח צו פּראַקטישקייט.\nבהנוגע צו זייגען אַליין דעם קינד, איז דאָס זייער און זייער אַ גלייכע זאַך, און בפרט אין די לעצטע יאָרען האָבען אַפילו אַמעריקאַנער דאָקטוירים אָנגעהויבען צו ריידין און דרוקען אויף וויפיל דאָס איז גוט סיי פאַר דער מוטער און סיי פאַר דעם קינד. און דאָס וואָס איר שרייבט אַז איר זייט סענסיטיוו, איז אין דעם גאָר ניטאָ וואָס צו איבערטראַכטען, דאָס איז אַ נאָרמאַלע זאַך און אַזוי דאַרף דאָס זיין, וכמה שכתוב עשה האלקים את האדם ישר והמה בקשו וגו' און השם יתברך זאָל העלפען שהלידה תהי' באופן קל ובשעה טובה ומוצלחת ולד שלם ובריא ולגדלו לתורה ולחופה ולמעשים טובים.\n<span data-k=\"q\">(ממכתב כ\"ה אייר, תשי\"ז)</span>\n<hr>\n... ובמה שכותב שלפעמים מפחדת, יש לבדוק המזוזות בדירתם, והתפילין שלו. וכן, שנוסף על מה שבודאי נוהגת במנהג הטוב של בנות ישראל הכשרות להפריש לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב, הנה תעשה כן בכל יום חול בבקר להפריש לצדקה איזה פרוטות — עד לאחר הלידה בשעה טובה ומוצלחת. ויה\"ר שגם בזה יבשרו טוב הוא וזוגתו שיחיו. ומובן שמתענין הנני"],[1301490291,"בהצלחתה בעבודתה ובהשפעה על הזולת בכלל ועל חניכי המוסד ביחוד. והשי\"ת יצליחה.\n<span data-k=\"q\">(ממכתב י\"ד סיון, תשט\"ז)</span>\n<hr>\n... ת\"ח על הערתו אודות מקור לדברי אדה\"ז בשולחנו הזהב בנוגע לזמן כניסת נפש הקדושה באדם<sup data-n=\"1786\">*</sup>, ומציין לספר החינוך בשרשי מצות מילה.\nואף שאין משיבין על הדרוש, הרי הענין דכניסת נפש הקדושה נוגע להלכה ככתוב בשו\"ע לאדה\"ז שם, הרי בספר החינוך משמע דאדרבה, דאין זמן המילה מכוון לענין כניסת הנפש בשני השרשים שכתב:\nא) דהמילה להבדיל בצורת גופם (שזהו בעת המילה) כמו שהם מובדלים מהם בצורת נפשותם (לשון עבר בערך זמן המילה)\nב) לרמוז כי כאשר תשלים צורת הגוף ע\"י (בעת המילה) כן בידו להשלים צורת נפשו בהכשר פעולותיו (זמן רב לאחרי זה כשיהי' מחויב בפעולות במצות, וק\"ל).\nולהעיר ג\"כ מטעמי מצות מילה לדעת הרמב\"ם במו\"נ חלק ג' סוף פרק מ\"ט.\nנעם לי לקרות בסיום מכתבו אשר מתקדמת הדפסת ספרו, ויהי רצון שיברך בקרוב על המוגמר דחלקים אלו וגם אחרי כן ילך מחיל אל חיל כצווי תורה\"ק, והרי ציווי התורה הוא גם נתינת כח.\nבכבוד ובברכה.\n<span data-k=\"q\">(ממכתב כ' מ\"ח, תשכ\"ה)</span>\n<hr>\n... במענה לשאלותיו מאז: ג'<sup data-n=\"1787\">*</sup> הענינים שבמילה (פעולה, מהול, אינו ערל) —",[["1786","*","ראה גם לקו\"ש ח\"ג ע' 763. ח\"כ ע' 246. המו\"ל."],["1787","*","שאלה על המדובר בלקו\"ש ח\"ג ע' 760, דע\"פ המבואר בצפע\"נ שמילה היא פעולה נמשכת מתורצת קושיית התוס' (קידושין כט, א), כי אין מילה מצוה שהזמ\"ג (ע\"ש) — הרי סו\"ס פעולת המילה היא ביום הח' דוקא. המו\"ל."]]],[1301490292,"אין עושים אותה לג' מצות. והקביעות אם זהו הזמן גרמא א\"ל — צ\"ל בהמצוה (שאחת היא) ולא בפרטי'. ואין לך זמן (מיום הח' והלאה) שאין מחוייב במצוה זו...\n<span data-k=\"q\">(ממכתב מ\"ח, תשכ\"ה)</span>\n<hr>\n... להערתו דלפי' התוס' ונת' ביש\"ש (ב\"ק פ סע\"א) בטעם שלום זכר צ\"ל כן גם בלידת נקיבה, י\"ל דשאני נקבה דאז אין השמחה שלימה ע\"פ ב\"ר (טז, ב).\n<span data-k=\"q\">(ממכתב ג' אייר, תשכ\"ה)</span>\n<hr>"],[1301490293,"<h3>מצורע</h3>\n... ובמה שהעיר בפירוש המשנה נזיר פ\"ח משנה ו' בעיקר השני דתגלחת מצורע אחר הטבילה וזהו נגד הכתוב בתורה.\nויש להעיר גם מנגעים פי\"ד מ\"ב, ונזיר פ\"ו מ\"ו (והרי ילפינן תגלחת א' מהשני') — דמשמע דטבל ואח\"כ גלח לא עלתה לו טבילה. ויל\"ע ברמב\"ם הל' טומאת צרעת פי\"א ה\"ד ובמפרשים שם.\nומתחילה רציתי לתרץ שהי' כתוב בפיה\"מ \"אחר' הטבילה\", היינו אחרי' — הטבילה. וכשנגרר או נשמט הקו קטן שע\"ג תיבת אחר לא שמו לבם המדפיסים שלאח\"ז לתקן.\nאו — שצ\"ל \"אחר הכביסה\" וכלשון הכתוב. ועיין בתפא\"י ובמשנה אחרונה (נגעים פי\"ד מ\"ב). ובמנ\"ח מצוה קעג סק\"ז.\nשוב ראיתי שעדיין לא נתרץ עי\"ז תמי' יותר פנימית, והיא: מהי בכלל כוונת הרמב\"ם במה שמזכיר כאן הטבילה, והרי אינו נוגע כלל בנדו\"ד, והרי לא הביא ענין ההזי', צפרים וכו'.\nולכן נ\"ל שטה\"ד יש כאן. וצ\"ל \"אחר ההחלט\", או \"אחר ההחלטה\". והבחור הזעצער שלא הבין פירושו וראה בכתוב וטבל — \"תיקן\".\nוההודעה שהוא אחר ההחלט מוכרחת, כי זהו עיקר בעיקר השני, דמתוך הסגר אינו בתגלחת (נגעים פ\"ח מ\"ח).\nומדאתינן להכי יש להעיר, אשר בנזיר כנראה צ\"ל התגלחת טומאה דוקא לאחרי הטבילה. וטעם החילוק בין מצורע לנזיר, י\"ל ע\"פ המבואר בנזיר פ\"ו מ\"ו שמצורע טהרתו בתגלחתו ונזיר טהרתו תלוי' בימיו. וכיון שע\"פ הנ\"ל יכול לגלח"],[1301490294,"לאחר זמן צריך לגלח דוקא לאחר הטבילה, שהרי ילפינן תגלחת טומאה מתגלחת טהרה לכמה ענינים, ותגלחת טהרה צ\"ל בטהרה דוקא. ועוד — בתגלחת טומאה נתן השערות תחת הדוד יצא, זאת אומרת שהתגלחת צ\"ל דוקא לאחר הטבילה, ומה שלא הביא הרמב\"ם דין זה בפירוש, י\"ל שהוא כידוע בכללי הרמב\"ם שאינו מביא אלא דינים המפורשים להדיא ולא שיש ללמדם. ועיין ג\"כ לחם משנה להלכות נזירות פ\"ו הלכה י\"א (ועיין שם בדיוק לשון הרמב\"ם). כן במנחת חינוך מצוה ת\"ו שהתגלחת היא לאחר הטבילה. ואין הזמן גרמא לחפש אם הובא דין זה באיזה מקום אחר בפירוש. . .\n<span data-k=\"q\">(ממכתב יו\"ד מנ\"א, תשט\"ז)</span>\n<hr>\n... בקידושין נז, א בקושית הש\"ס בצפור מצורע דשחטה ונמצאת טריפה אמאי מותרת בהנאה — איסורה (הקדשה) היכן הותר (רש\"י).\nוקשה לכת\"ר אמאי לא נימא אדעתא דהכי לא אפרשה וכב\"ק (קי, ב) —\nע\"כ אי אפשר לומר כן, דא\"כ בנשפך דמה אמאי תמות המשתלחת — כסיום המשנה הנ\"ל (נגעים פי\"ד, מ\"ה).\nוטעם הדבר שאין אומרים בכגון דא אדעתא דהכי ל\"א יל\"פ מכמה נימוקים. והקרוב אלי — ע\"ד מש\"כ בתוד\"ה אדעתא (ב\"ק שם) דלא מסקא אנפשא גם בנדו\"ד לא מסקא אנפשי' שהרי אין חוששין לטרפות ובפרט לפי' הש\"ס בקדושין דנטרפה ע\"י השחיטה — והרי רוב מצוין אצל שחיטה מומחין הן. וביחוד בקדשים דבעי כוונה וביותר ע\"פ ההלכה בצפור מצורע דשחיטתה דוקא בכהנים — דזריזים הן.\nאו יאמר: בנשחטה לאו כל כמיני' לומר אדעתא דהכי ל\"א (וגם לא ניחא לי' להתנות כן בשחיטה) כיון דאז משוי לי' שחיטת חולין בעזרה.\nאו יאמר: בנשחטה — ה\"ה כבר ברשות כהן. ואין מתנין בכגון דא כנ\"ל.\nובדוגמת שאלה בתרומה וקדשים שאינה בשתי אופנים אלו (נדרים נט, א. ד\"מ וש\"ך יו\"ד סשכ\"ג ס\"ב).\n<span data-k=\"q\">(ממכתב ט' ניסן, תשי\"ח)</span>\n<hr>\nבמענה על מכתבו מב' כסלו, בו כותב אשר הרופא חפץ לעשות לו בדיקה מסוימת, וי\"א שאסור לעשות בדיקה זו ע\"פ שו\"ע."],[1301490295,"והנה כשידבר עם רופא מומחה במקצוע יוודע לו שבדיקה זו היא לא לשם ידיעה בעלמא אלא שבתוצאות הבדיקה תלוים אופני הטפול, ולכן יש רבנים<sup data-n=\"1788\">*</sup> מורי הוראה בישראל מתירים לעשותה, במקרים מסוימים, אלא שכיון שישנם כמה אופנים בבדיקה, מתחילים באופן הכי קל ע\"פ שו\"ע, ויבקש את הרופא המטפל, לבאר לו לרב מורה הוראה אשר בסביבתו אופני הבדיקה, וייעץ לו באיזה מהם להתחיל. . .\n<span data-k=\"q\">(ממכתב י\"ד כסלו, תשי\"ז)</span>\n<hr>\n... ולפלא וגם תמי' גדולה מה שכותב שלא יכול להחליט על ההיתר<sup data-n=\"1789\">*</sup>, כו', כי אין ההחלטה תלוי' בו כ\"א בתורתנו, ואין לחלק בין פסק לפסק, ועוד יותר פלא מה שכותב עד\"ז של אי החלטתו בקור רוח, כאילו זוהי מדת חסידות שלא להשמע להוראת מרא דאתרא, אבל כיון שכבר נעשה ענין, בודאי גם זה יהי' לטובה, וזכות התעסקותו בחינוך על טהרת הקדש וחסידות תעמוד לו ולזוגתו תי' אשר מתוך בריאות הנכונה והרחבת הדעת יגדלו את ילידיהם שיחיו לתורה ולחופה ולמעשים טובים.\n<span data-k=\"q\">(ממכתב כ\"ו אד\"ר, תשי\"ז)</span>\n<hr>\n... במ\"ש שמתאים להוראת הרופא נאלץ הבעל להשתמש בקונדס וכו' כיון שאין על האשה לעשות מה בדבר זה. — גם זה פלא, שאינם מזכירים אם שאלו דעת רב מורה הוראה בישראל בזה, ועוד שבאם יכיר הרב בכללות הדבר, הרי מהתרופות הנעשים ע\"י האשה, הוא לא רק השתמשות בחמרים כמיים, שאפשר בכגון דא אין יכולת להשתמש בהם, כי אם גם הענין דמוך, כיסוי מתאים במקום המתאים וכו' שלכאורה גם בנדון שלהם אפשרי להשתמש בזה כנ\"ל באם יהי' היתר של הרב בכללות הענין. . .\n<span data-k=\"q\">(ממכתב כ\"ז סיון, תשי\"ח)</span>\n<hr>",[["1788","*","מדובר בזה בשו\"ת חדות יעקב מייזלש ח\"ב. שו\"ת אחיעזר ח\"ג סכ\"ד (ושם מציין לערוך לנר יבמות עו. דברי מלכיאל ח\"א. דברי אליהו סכ\"א. תורת מרדכי). שו\"ת מהר\"ש מראדמישל ח\"ו. שדי חמד פאת השדה לאסיפת דינים מע' אישות סי\"ג. צפנת פענח (להגאון מראגצוב) ספ\"ט וסקי\"ג."],["1789","*","בשימוש ע\"י מוך. המו\"ל."]]],[1301490296,"... הכתוב במכתבי הקודם, בהחילוק שע\"פ שו\"ע וכו' לא היתה כוונתי לשלול לגמרי נתוח הפראסטאטא, באם רופא מומחה מייעץ לעשות אותו, כי אם להורות על חילוק אופני הנתוח בזה, אשר ישנם רופאים שבכלל אין מנתקים את השביל.\nועל זה הבאתי המועתק באוצר הפוסקים חלק א' [מהדורא שני' עם הוספות, ירושלים תשט\"ו].\nב) אפילו מהמנתקים — כמה עושים זה לאחרי שנעשה חלק העיקרי של הנתוח, שאז כבר יש צורך בפועל [לדעתם, עכ\"פ] לשמירה מסיבוכים, משא\"כ כשמתחילים בנתוק. וק\"ל.\nכן להוסיף אשר ישנם נתוחים דכיס השתן שמפני אותו הטעם דלהשמר מסיבוכים מפסיקים ומנתקים כו' בסמיכות למקום הנתוח ולפעמים גם במקומות שיש לדון בזה עפ\"י השו\"ע, שלכן העירותי על זה, אף שבמכתב כת\"ר הא' לא היה נזכר אלא הנתוח האחרון, ועל כת\"ר הסליחה על ההערה עוה\"פ. . .\n<span data-k=\"q\">(ממכתב ב' אייר, תשכ\"א)</span>\n<hr>\n... במש\"כ ע\"ד אמירת ד' מזמורים הראשונים דתהלים כו' — כ\"כ בקצש\"ע סקנ\"א (מס' יסוד יוסף) קצה המטה שעל מטה אפרים סו\"ס תקפג ועוד, ולדידן (ובפרט שאין אומרים תהלים קודם חצות לילה — מלבד בר\"ה ויוהכ\"פ) עצ\"ע ואכ\"מ.\n<span data-k=\"q\">(ממכתב י\"ט תמוז, תש\"כ)</span>\n<hr>\nבמענה על מכתבו, בשאלה:\nא) בהנוגע לפלוגתא הידוע, בענין בין השמשות, איך נוהגים בזה הנשים בהנוגע לבדיקה.\nוהנה אף כי בזמן האחרון דוקא רבו המפלפלים עוד הפעם בענין השקיעה ובין השמשות הנ\"ל, עד שגם ספרים נדפסו במקצוע זה נוסף על המאמרים בירחונים התורנים, מובן שלאנ\"ש אין להם אלא פסק דין רבנו הזקן בסידורו, שהוא מהדו\"ב לגבי השו\"ע שלו, וידוע שגם דעת הגר\"א כן היא (או\"ח סי' רס\"א, יו\"ד סי' רס\"ב ובשנות אלי' ריש ברכות, וראה ג\"כ ס' גור ארי' לשבת לה'). . .\n<span data-k=\"q\">(ממכתב ו' ניסן, תשט\"ז)</span>\n<hr>"],[1301490297,"במענה על המכתב מג' אד\"ש עם המוסגר בו, בו כותב אודות האשה אשר ישנו רופא אומר ומגביל הזמן שיכולה להתעבר שאינו מתאים לספירת ימי טהרה וכו' ושואל עצתי בזה.\nהנה לא ביאר כוונתו, כי בודאי אין מקום לשאלה להתיר להנ\"ל שלא כדין ח\"ו ובפרט שידוע שבזמן האחרון כמה רופאים מומחים המערערים על ודאיות הבחינות עליהן מבססים הרופאים את חוות דעתם בקביעות הימים הראוים ביותר לעיבור, וצ\"ע מי הם המרובים אם המערערים או המחזיקים בנכונות בחינות אלו, ובכלל כל ענין בחינות אלו נתחדש בשנים האחרונות, שבמילא מובן שאפילו לדעת המחייבים הודאות אינה בשלימות, ומובן שיש בזה עוד אופן והוא שהרופא המטפל בה יתן לה סממנים או זריקות המקצרים זמן הווסת, שלכן יוגמר בהקדם ויהי' די זמן לספירת ימי טהרה וכו' אבל גם בזה צ\"ע, כיון שטפול זה אין כל התוצאות שלו ברורות למדי, וגם ספק קרוב לשלילה אם שוות הן התוצאות בכל אחת ואחת, שלכן אי אפשר לדעת השפעתו על העבור, שכל שינוי קטן בזה עלול לגרום תוצאות רבות, ולכן אם הרופא יחשוב ע\"ד טפול מעין זה, נכון יותר שלא יהי' ע\"י זריקות חזקות אלא שינסה לשנות לאט לאט ווסתה והתלוי בזה באם אפשרי הדבר, והעיקר בכל הענין הוא שתשמור על חוקי ודיני טהרת המשפחה במילואם וכן בענינים הקשורים בזה ובפרט באשה והם עניני הצניעות שבתוכם כיסוי הראש, ועי\"ז יהי' מקום להניח ברכות השי\"ת כלשון הזהר הק' (חלק ג' קכ\"ו ע\"א) בעיא איתתא לאתכסיא כו' ואי עבדת כן מה כתיב בניך כשתילי זיתים כו' מתברך כו' בבנין בבני בנין, עיי\"ש. . .\n<span data-k=\"q\">(ממכתב ה' אד\"ש, תשי\"ז)</span>\n<hr>\n... ובמ\"ש אודות זוגתו תחי' שהרופאים מאשימים עכוב לע\"ע של העבור מצד שמירת חוקי התורה וכו' וכנראה כוונתו בזה שהרופאים ששאלום אומרים שהיום היותר מסוגל הוא קודם סיום הימים דהמנין הפסק וכו' ואם כן כוונתו.\nהנה ישנם כו\"כ רופאים שבכלל שוללים נכונות השערות אלו ואפילו היסודות שעלי' בנוי' השערה זו, שזה רק תקופה קצרה בערך שסומכים על הנ\"ל נוסף על הנ\"ל ברובא דרובא לפ\"ד הרופאים החילוק הוא רק ביום אחד או יומים, וישנם איזה טפולים שמקצרים את ימי הווסת וכיו\"ב ובמילא מתוקן הנ\"ל עכ\"פ למשך זמן אפילו לפי השערתם, ואף שבכלל טפול המתערב בעניני הווסת יש לנהוג בו בזהירות, אבל בנוגע לפעמים מועטות אין מקום לחשש באם נעשה ע\"י רופא מומחה, בכ\"א בודאי לדכוותי' למותר לעורר שאין מקום כלל להקל על פי דרישת הרופאים הנ\"ל בחוקים ודינים האמורים אפילו במילתא דרבנן."],[1301490298,"לפלא שאינו מזכיר באם שאל רופא בהנוגע לעצמו, ובטח ימלא עד\"ז בהזדמנות הבאה.\nבקשר עם האמור הנה ע\"פ מדתו של הקב\"ה שהיא מדה כנגד מדה אלא שכ\"פ ככה, הרי המלמד את בן חבירו תורה כאילו ילדו סגולה במיוחד ללידת בנים — נוספים — על בנם שליט\"א.\nבברכה לבשו\"ט בכל האמור ולכוח\"ט.\n<span data-k=\"q\">(ממכתב ז' אלול, תשי\"ז)</span>\n<hr>\nבנועם קבלתי ז\"ע ספרו טהרת מים מהדורא תליתאי.\nויהי רצון שגם מהדורא זו תשיג המטרה לבסס ולהפיץ ענין דטהרת בנות ישראל, אחד היסודות דבית ישראל בכללותו, וביתו הפרטי של כל אחד ואחת.\nוכיון שיסוד כשמו עליו מיוסד קיום הבית הנבנה עליו, מובן שכל הוספה בחוזק ואיתנות היסוד, יש להגדיל אותה ככל האפשרי בכל כגון זה. והובטחנו מחז\"ל הבא לטהר, וידוע דיוק רבנו הזקן, לטהר גם אחרים, מסייעין אותו.\nוכנראה במוחש דוקא בתקופתנו זו אשר הבע\"ב והצעירים בראשם, מקבלים בחפץ לב כל הוראה להידור בענין האמור, ועאכו\"כ בפרטים שלהם יסוד בדין.\nואת\"ל הרי בענין זה עצמו הודגש הדבר, הן בהטומאה — שהיא במשהו (ובחומרא דרבי זירא, דהלכה פסוקה היא להחמיר) וכן באופן הטהרה דאפילו שערה אחת מעכבת כל הענין.\nובעמדנו בימי הספירה שכביאור חז\"ל ספירה זו, דוספרתם לכם, הוא ברוחניות הענין דוספרה לה שבעת ימים,\nיהי רצון שבקרוב ממש יקוים היעוד, דהספירה תביא לואחר תטהר, לוזרקתי עליכם מים טהורים וטהרתם בגאולה האמיתית והשלימה על ידי משיח צדקנו.\nבכבוד ובברכה לאורך ימים ושנים טובות ולראות פרי טוב בעמלו עמל תורה המביא לידי הלכה למעשה ומתוך בריאות הנכונה.\nע\"פ הנ\"ל בסיום המכ' — יש לבאר שייכות בקשת יה\"ר כו' שיבנה ביהמ\"ק כו' לספירה. ואפילו להאומרים דגם בזמה\"ז היא מה\"ת.\n<span data-k=\"q\">(ממכתב כ\"ג אייר, תשכ\"ד)</span>\n<hr>"],[1301490299,"ב\"ה, ח\"י אלול, ה'תשכ\"ה.\nיום הולדת את שני המאורות הגדולים\n— כ\"ק הבעש\"ט וכ\"ק רבנו הזקן —\nברוקלין, נ.י.\nועד בנין המקוה,\nדק\"ק קהל בית דוד,\nה' עליהם יחיו\nשלום וברכה!\nבמענה למכתבם מאז, ע\"ד בנין מקוה טהרה בק\"ק שלהם, והודעתם עתה, אשר כבר התחילו להשתמש בה, ע\"פ הסכמת המרא דאתרא שלהם, והרבנים שצירף אליו — שליט\"א.\nע\"פ מ\"ש חבר אני לכל אשר יראוך ולשומרי פקודיך, הריני משתתף בהוצאות דבנין הכי נעלה, מקוה טהרה, ומצו\"ב השעק.\nואת\"ל הרי זה גם מענין ימים אלו, ימי רצון דלוחות האחרונות, סיום וחותם דמתן תורה, וכפירוש רז\"ל<sup data-n=\"1790\">1</sup>, אשר התחלת היות בני ישראל לעם וגירות שלהם, היתה:\nבארץ מצרים, במילה — עלי' אמר<sup data-n=\"1791\">2</sup> דוד שירה, למנצח על השמינית<sup data-n=\"1792\">3</sup>, וסיומה ע\"י הטבילה, בעת מתן תורה בחג השבועות,\nונוספה ע\"ז בלוחות האחרונות, שניתנו ביום הכפורים, ע\"י ששבו בני ישראל לה', — מעלת בעלי תשובה —\nוכמאמר רז\"ל<sup data-n=\"1793\">4</sup>: אשריכם ישראל כו' מקוה ישראל ה', מה מקוה מטהר כו' אף הקב\"ה מטהר את ישראל.\nבכבוד ובברכת כתיבה וחתימה טובה\nלשנה טובה ומתוקה.\n<hr>\n... זה מזמן שנתתי אל לבי, מה זה עשה ה' ככה לעמנו בני ישראל, בהתבונן בהמצב הירוד בענין זהירות בדיני וחוקי טהרת המשפחה, וכמציין גם כת\"ר לכ\"מ, שאף שכשר הוא וכו' וביותר קשה בהנוגע לארצוה\"ב, שכנראה במוחש השגחה העליונה הביאה לכאן רוב מנין ורוב בנין של בנ\"י ותורה מתפשטת מכאן וכו', והרי",[["1790","1","<b>וכפירוש רז\"ל</b>: יבמות מו, ב."],["1791","2","<b>עלי' אמר</b>: מנחות מג, ב. ונתבאר בלקוטי תורה ויקרא (כ, ג)."],["1792","3","<b>למנצח על השמינית</b>: בילקוט רמז תרל\"ג, הביא ע\"ז הכתוב למנצח בנגינות על השמינית, וי\"ל שמתאים לשתי דרשות אלו, הם ב' הטעמים (שבלי הלקט הל' מילה) שאין מברכין שהחיינו על המילה: משום צערא דינוקא או משום דרמי' אבי דינא וכיו\"ב."],["1793","4","<b>וכמאמר רז\"ל</b>: בחותם פרק יוהכ\"פ."]]],[1301490300,"פשיטא דאין להתנחם במרז\"ל דבעקבתא דמשיחא חוצפא יסגא ובן הנדה ה\"ה (לחד מ\"ד) עז פנים (כלה רבתי רפ\"ב).\nאבל התבוננתי בדין הברור לכל הדיעות, אשר טבילת נדה אין צריכה כוונה כלל, והרי דוקא בארצוה\"ב נפוץ ביותר וביותר הענין דרחיצה בנהרות ובימים, ולא רק בימות הקיץ, אלא לעתים תכופות גם בימות החורף, נוסף על הרחיצה במקום אסיפת מים רבים יותר מארבעים סאה פי כמה ובפרט שגם אמת המים מהנהר, לפעמים קרובות, מעורבת בהם או מי מעין.\nואף שפשוט שאין לפרסם הנ\"ל ולא רק בפני עמי הארץ אלא גם לאלו שבדרגא עליונה מהם, אבל ביחד עם זה אין לדחות ח\"ו כו\"כ מבני ובנות ישראל משידוכין למשפחות יראי ה' וחרדים לדברו, אפילו באם היתה ידיעה ברורה שלא נזהרים בטהרת מקוה בפרסום, ועאכו\"כ במקום שאין כאן אלא השערה, וק\"ל.\n<span data-k=\"q\">(ממכתב ט\"ו תמוז, תשי\"ט)</span>\n<hr>\nבמענה על מכתבו מא' דחדש מרבין בשמחה והקודם לו.\nבמה שנרשם בהנחת שיחה י\"ט כסלו תשט\"ו<sup data-n=\"1794\">1</sup> שבתוס' בכורות דנין שמעין מטהר דוקא בזוחלין. — כן הוא כפי שכותב שכוונתי היתה לתוספת בכורות נה, ב שנראה שם שתי דיעות (ודלא כתוס' שבת סה, ב דהביא בפשיטות דעת ר\"י), וכן צדק במה שכותב בדברי שהבה\"ג פסק כך, שכוונתי היתה במ\"ש היכא דסכיר נהרא לא סלקא לה טבילה. ובמה שמעתיק פירוש העמק שאלה לשאילתות סי' צ\"ו אות י\"ג דמפרש הכוונה דאין שם מ' סאה<sup data-n=\"1795\">*</sup>, הנה במחכת\"ר של ההעמק שאלה, אין זה בבה\"ג אפילו ברמז, ואילו הי' דברי הבה\"ג בהנוגע לנהר מסוים עכ\"פ בדוחק גדול אולי אפשר הי' לפרש כן בהסתמך שידוע הי' הנהר לנהר קטן, אבל דברי בה\"ג הם הוראה כללית, ואי אפשר להוראה כללית להשמיט הנקודה העיקרית, כמובן.\nדא\"ג רשום בזכרוני שראיתי באיזה ספר שמעתיק פסק זה בשם בה\"ג ואיני זוכר ברגע זו שם הספר, כן מצאתי בס' מקוה טהרה שרשום שבספר גדולי טהרה מדבר בענין זה, ואינו תחת ידי.\nבמ\"ש בשיחה הנ\"ל<sup data-n=\"1796\">2</sup> בענין עד א' נאמן באיסורין או בטומאה, כנראה שיש טעות בזה ברשימה<sup data-n=\"1797\">3</sup>, כי המדובר הי' שבאם נדה הוא ענין של טומאה הרי אי אפשר הי'",[["1794","1","נדפס קטע זה בלקו\"ש ח\"ד ע' 1119 הערה 34. המו\"ל."],["1795","*","וכמדומה שכ\"פ גם המגי' בבה\"ג דפוס ורשא."],["1796","2","נדפס קטע זה בלקו\"ש ח\"ג ע' 986. המו\"ל."],["1797","3","כשי\"ל בשעתו ב\"הנחה בלתי מוגה\". המו\"ל."]]],[1301490301,"ללמוד משם דין דעד א' נאמן באיסורין, דאיסור מטומאה לא גמרינן, ועיין בזה אתוון דאורייתא למהר\"י ענגל כלל כ\"א, וביד מלאכי דעניני איסור מטומאה לא גמרינן. . .\n<span data-k=\"q\">(ממכתב י\"א אדר, תשט\"ז)</span>\n<hr>\n... במ\"ש<sup data-n=\"1798\">*</sup> בקשר עם הסברת דברי הכסף משנה בלשון הרמב\"ם ספ\"ו מהל' אבה\"ט שטהרת הטבילה היא דוקא בצאתו מן המקוה, — ות\"ח על העתיקו דברי הגאון מרגצוב בזה מתוספתא. — וכן מקום אתי להעיר, אשר עצם הסברא האמורה שהטהרה היא דוקא ביציאתו מן המקוה — חידוש גדול הוא וגם תמוה הוא ולולי שהכסף משנה אמרה, יש להעיר ע\"ז ומכמה צדדים וכמו שהאריך בזה גם בספר שם משמעון מהדו\"ק להר\"ש פאלאק (סטמור תרצ\"ב) חיו\"ד סי\"ח. . .\n<span data-k=\"q\">(ממכתב ה' מ\"ח, תשי\"ז)</span>\n<hr>\nבמש\"כ ע\"ד סתימת נקב שן לאיזה חדשים — בהנוגע לחציצה — יש להעיר משו\"ת הצ\"צ חיו\"ד סק\"ס. ומס' שצוינו בדרכי תשובה לסקצ\"ח סכ\"ד וטהרת ישראל שם. ובטח לא נעלם זה מעיני כת\"ר.\nבשערי ציון (מכ\"ע, ירושלים תרפ\"ה(?)) סי' נ\"ד רוצה להשוות ב' דעות בדין דאינו מקפיד אינו חוצץ (דרמב\"ם ורש\"י) מפני שאינו רוצה להעבירו, מפני ביטול, ולשיטה הא' הרי גם בסתימה זמנית אין רצונה להעבירה כ\"א אדרבה להחליפה בקבועה יותר (ז.א. שיהי' בשרה — שע\"ז אנו דנין בחציצה ולא על דבר החוצץ) — מכוסה בקביעות יותר, ושאני ידות הכלים שהכניסן שלא כדרכה ששם צ\"ל חיבור ואינו — ע\"כ תוכ\"ד (ואין הזמ\"ג לעיין בס' הנ\"ל אם שקו\"ט בסברה זו). אבל עפ\"ז א) גם סתימה ליום ויומים צ\"ל אינה חוצצת. והוא דלא ככמה אחרונים. ב) בסתימה זמנית הרי אדרבה מקפידה להסירה (אלא שלא תומ\"י), וע\"כ נזקקין בזה לענין החיבור וביטול.\nדרך אגב: הערת כת\"ר מירוש' יומא פ\"ד ה\"ד דהקביעות ע\"י מסמר מבטל חציצת הנרתק, אף דלא הוי אלא ליומי' — יוהכ\"פ, לא נ\"ל, כי שם זהו קביעות תמידי שהרי זהו מחתה המיוחדת רק ליוהכ\"פ.\n<span data-k=\"q\">(ממכתב ער\"ח תמוז, תשי\"ח)</span>\n<hr>",[["1798","*","ראה גם לקו\"ש ח\"ל ע' 22 הערה 64. המו\"ל."]]],[1301490302,"... בנוגע לטבילתו במקוה (בקשר לאוזן) משימים באוזן מוך שרוי במים. ובכו\"כ מקרים מתירים זה הרופאים אפילו לכתחילה.\n<span data-k=\"q\">(ממכתב שנת תשכ\"ה)</span>\n<hr>\n... וואָס איר שרייבט, אַז אין דעם ענין פון באַוועגען צו אָפּהיטען טהרת המשפּחה, קען מען ניט קריגען ווער עס זאָל דאָס וועלען אָננעמען, איז חס ושלום צו זאָגען דאָס אויף אידען, און ווי עס זעהט אויס האָט איר ניט באַגריפען ריכטיג וואָס איך האָב אייך געשריבען, מיינענדיק אַז דאָס איז אַ טובה נאָר פאַר יענעם צו וועמען איר רעט, אָבער אין אייער פאַל און אין דער באַציהונג פון אייערע קינדער צו אייך, איז דאָס איינע פון די סגולות, אַז דורכן איינווירקען טהרת המשפּחה אויף אַנדערע, וועט קומען אַ בעסערונג אין דער באַציהונג פון אייערע קינדער צו אייך. און דעריבער דאַרפמען טאָן אין דעם, ווי מען טוט אַ זאַך וואָס רירט אָן זיך אַליין. און איך האָף אַז עס פאָדערט זיך ניט מערער ערקלערונג אין דעם.\nבברכה צו גוטע בשורות ומנוחת הנפש.\n<span data-k=\"q\">(ממכתב ב' אייר, תשי\"ז)</span>\n<hr>\nעס איז ערהאלטען געווארן אייער בריף פון. . און אויך דער פריערדיקער, און ווען איך וועל זיין אויף דעם ציון הק' פון מיין שווער כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה זי\"ע, וועל איך מזכיר זיין די אלע וועגן וועלכע איר שרייבט וועגן זיי, יעדערן פון דעם וואס ער נויטיגט זיך.\nדאס וואס איר שרייבט וועגן אייער טאכטער. . תחי', האָב איך שוין געשריבן אייך עטליכע מאל, אז ווען אַ טאכטער שטייט אין שידוכים, איז די ערשטע זאך דארפן עלטערן און ספעציעל א מוטער צו ריידן מיט איר וועגן דעם ווי א אידישע הויז דארף זיך פירן, און ספעציעל בנוגע צו טהרת המשפחה (מקוה), וואס נאר דאן ווען א איד פירט זיך אין דער וועג פון תורה קען א איד זיין גליקלעך.\nאון דעריבער איז ניטא קיין שום ארט צו שעמען זיך און ניט ריידן וועגן דעם, און אויך ניט באנוגענען זיך מיט איין מאל ריידן. און ווי עס ווייזט אויס פון אייער שווייגן אין דעם, האט מען ווייניג געטאן אין דעם אדער גארניט געטאן.\nדעריבער פאר[שטיי] איך ניט וואס איז בא אייך דער וואונדער אז עס גייט ניט גלאטיק, ווען מען טוט ניט דאס וואס השם יתברך הייסט טאן."],[1301490303,"און איך האף, אז לכל הפחות איצטער וועט איר אנהויבן צו ריידן מיט אייער טאכטער וועגן דעם. און השם יתברך זאל העלפן אז אייער טאכטער תחי' זאל האבן א גוטן זיווג און איר זאלט האבן פון איר און פון אלע אייערע קינדער פיל אידישן נחת.\nבברכה.\n<span data-k=\"q\">(ממכתב ד' שבט תשי\"ד)</span>\n<hr>\n... תעשה ככל אפשריותה בעניני טהמש\"פ (חיזוק מקואות, הפצת ידיעות ע\"ד גודל והכרח שמירת דינים אלה וכיו\"ב) — מה טוב שהיא תפעול על 2 נשים (ולכה\"פ — אחת) שתשמורנה דינים אלה.\nע\"פ מש\"כ אדה\"ז באגה\"ת פ\"ג ובהתחשב בגילה — יכולה להתענות חצאי ימים \"וב' חצאי יום — כיום אחד לענין זה\".\nנתינותי' לצדקה — ברבות פעמים.\nאזכירה עה\"צ. בדיקת המזוזות. לצדקה לפני הדה\"נ.\n<span data-k=\"q\">(ממכתב שנת תשכ\"ה)</span>\n<hr>\n... וצריך הי' אשר. . מהדר בקיום דיני מקוה וטהרת המשפחה, היינו לטבול במקוה של מי גשמים או מעיין, ולא במימי העיר הנמדדים ונמשכים דרך כלים ומכונות שונות, שזה בפרט ימשיך תוספת בבריאות ילידי' שיחיו...\n<span data-k=\"q\">(ממכתב כ\"ז כסלו תשט\"ו)</span>\n<hr>\nבמענה על מכתבו, בו כותב אודות קרוביו אשר ר\"ל מתו להם בנים.\nהנה ימסור להם שיזהרו לדקדק ולהדר בחוקי ודיני טהרת המשפחה, וכן יבדקו את התפילין של הבעל, והמזוזות בדירתם, והנשים יפרישו איזה פרוטות לצדקה קודם הדלקת הנרות בכל ערב שבת וערב יום טוב, וישתדלו במצות הכנסת אורחים, והשם יראה ללבב וישלח ברכתו אשר מכאן ולהבא יבשרו אך טוב בכל האמור. . .\n<span data-k=\"q\">(ממכתב י\"ח ניסן, תשט\"ז)</span>\n<hr>"],[1301490304,"<h3>אחרי</h3>\n... בכללות הענין דאימוץ ילדים<sup data-n=\"1799\">*</sup>, פלא שלא מצאתי עד עתה מי שישים לב להבא להלן. ואף שכבר נדפסו כמה שו\"ת ומפורטות בכמה דינים המשתלשלים מענין האמוץ, אין מעורר על עצם הענין וכו'.\nוהחששות שנתעוררו אצלי, שהרי האמוץ בימינו אלה הוא לא כבדורות שלפנינו, בקיום המצוה דלגדל יתום בתוך ביתו וכו', אשר כל הסביבה כולל גם המגודל ידעו שאין זה ההורים שלו. ועתה הוא להיפך — עושים ככל האפשרי להעלים פרט זה, ולא עוד אלא שע\"פ לחץ רופאים, האומרים שהם מומחים לעניני נפש, מחליטים שאסור לגלות זה להילד (כי עלול לפגוע במנוחת נפשו וכו'), — שמזה תוצאה, שתהי' הנהגתם עם המאומץ כאילו הי' זה ילידם ממש, שבמילא ישנם כל הענינים דיחוד, חבוק ונישוק וכו' וכו' בכל יום. ובודאי אי אפשר להזהר מזה באם אפילו המאמצים יראי שמים באמת.\nואפילו באם מגלים להמאומץ כשיגדל שאין זה הוריו, צע\"ג האפשר לשנות אז הנהגה שהיתה מכמה שנים מקודם. והרי בהאמור — איסור דרבנן ודאי ישנו, ולדעת הרמב\"ם גם איסור דאורייתא. והרי גם בנוגע לאיסור דרבנן — שאני כשהוא דבר ההולך ונשנה ונשלש וכו' (נוסף על המובא ומבואר בספרי נגלה בזה — יעוין ג\"כ אגרת התשובה לרבנו הזקן פרק ז'). ולכאורה ע\"פ האמור צע\"ג בכל ענין האמוץ. וטעם דהיתירא בכגון זה דמוטב שיהיו שוגגין וכו' — לכאורה ברור, אשר כו\"כ ימנעו מאמוץ באם ידעו את הנ\"ל. ועיין ג\"כ שו\"ע או\"ח סי' תר\"ח ובשו\"ע רבנו הזקן שם כמה גדרים במוטב שיהיו וכו' — שע\"פ זה אין ההיתר דמוטב וכו' ברור בנדון דידן. ובודאי לדכוותי' דכת\"ר — האריכות אך למותר.\n<span data-k=\"q\">(ממכתב כ\"א שבט, תשכ\"ד)</span>\n<hr>\n... הפס\"ד מהצ\"צ נמצא בס' שערי דעה בסי' סא. נזכר שם הצ\"צ גם בסי' סב (חאו\"ח), צא.\nלומר דהמקור לדברי הרמב\"ם (הל' אי\"ב רפט\"ו) דבן הנדה פגום הוא ממס' כלה, וכ\"מ בבי' הגר\"א לשו\"ע אה\"ע ס\"ד סי\"ג — צע\"ג לדידי — דאדרבה משם ראי'",[["1799","*","ראה גם לקו\"ש חי\"ב ע' 193. חי\"ז ע' 471. המו\"ל."]]],[1301490305,"לסתור, כיון שקויים דוקא כדברי רע\"ק שהוא ממזר ובן הנדה, ואמרו שגדול הי' רע\"ק כי הכחיש דברי החולקים ע\"ז. . .\n<span data-k=\"q\">(ממכתב כ\"ט אדר, תשכ\"א)</span>\n<hr>\n... מאשר הנני קבלת מכתבו (נוסף על רשימת החד\"ת של כת\"ר — שקדמו) — והרי ידוע שאין עניני לפס\"ד וכו' ובפרט בענין שכבר דשו בו רבים. ואתו רב הסליחה.\nנ. ב.\nע\"פ מרז\"ל בפטפטייא דאורייתא: כדעת הרמב\"ם (סהמ\"צ מל\"ת שמז) דואל אשת עמיתך גו' אזהרה לאיש בלבד, כ\"כ גם בסמ\"ג ל\"ת צז (וכנראה בס' יראים בסרי\"ד ג\"כ צ\"ל: הזהיר צורנו על הנואף — ולא \"הניאוף\" — כבדפוסים). ובחינוך מצוה לה \"וכפל זה הלאו\" ובמנ\"ח שם \"מתרין בו מלאו זה דכאן או מלאו דואל\". — עפ\"ז חסר הביאור שהיינו דוקא בנוגע לאיש.\nמדברי הרמב\"ן (אחרי יח, כ): ואפשר שאמר כו' טעם האיסור צע\"ג אם יש ללמוד מזה בנוגע להלכה, שהרי: א) מסיים שאין טעם זה נוגע להלכה (לעונש). ב) חוזר בו וכותב: והנכון בעיני כי בעבור כו' (ולא כתב: ועוד יש לומר או כיו\"ב). ג) חותם שם: ורבותינו דרשו — שכוונתו לרבותינו בהלכה שבתורה.\n<span data-k=\"q\">(ממכתב שנת תשכ\"ה)</span>\n<hr>"],[1301490306,"<h3>קדושים</h3>\n... להערתו אודות החשיבות המיוחדת של מדת אהבת ישראל, שהרי להבדיל בין ישראל לעמים גם אצל אומות העולם אנגלי אוהב את האנגלים וכו' — החילוק, חילוק עקרי, מובן שלשון הכתוב ואהבת לרעך כמוך, שכמו שאהבת האדם לעצמו אינה תלוי' בזה שרואה מעלות עצמו — בשכל או מדות שבלב או במחשבה דיבור ומעשה, ואדרבה על כל פשעים תכסה אהבת עצמו — כן הציווי בנוגע לאהבת רעהו, שתהי' גם כן אהבה עצמית בלתי תלוי' בדבר ובמעלה וכולי.\nעל פי זה מובנת התמי' איך אפשר שתהי' דרגת אהבת זולתו \"כמוך\", ועל זה בא ביאור רבנו הזקן בספר התניא פרק לב, שמתחיל בביאורו ממדרגת אהבת הזולת שבקל יותר להשיגה \"כי מי יודע גדולתן ומעלתן\" כולי, אבל סו\"ס הרי זו ג\"כ אהבה תלוי' במעלה, לכן מוסיף ביאור \"שכולן מתאימות ואב אחד לכולנה\" כולי \"אחים ממש\". עיי\"ש."],[1301490307,"הדגשה מיוחדת עפ\"י תורת החסידות בכל האמור מבוארת בספר המצוות לאדמו\"ר הצמח צדק, מצות אהבת ישראל פרק ב. עיי\"ש.\nומגלגלין ענין לימים מתאימים, שהרי נמצאים אנו בין המצרים דחורבן בית שני שקרה מפני שנאת חינם. ופשוט שזה שנצטוינו לעשות זכר לחורבן, ביחוד בימים אלו, כוונתו בשביל התיקון, שהרי החורבן הוא כנוסח התפלה ומפני חטאינו גלינו מארצנו כו', ואי אפשר לביטול המסובב כי אם על ידי ביטול הסיבה, וכל גרעון וחלישות בסיבה מביאה גרעון וחלישות בהמסובב, אפילו אם הוא — כמבואר בתורת החסידות — לעת עתה רק בעולמות העליונים. וכיון שעיקר החטא, כהודעת חכמינו ז\"ל, הי' בשנאת חינם, הרי תיקונו באהבת חינם היינו בלתי תלוי' בדבר. ויהי רצון שבקרוב ממש נזכה לקץ גלותנו ולגאולה האמתית והשלימה על ידי משיח צדקנו, ויהפכו ימים אלו לששון ולשמחה.\n<span data-k=\"q\">(ממכתב ה' מנ\"א, תשכ\"ד) </span>\n<hr>\n... ובמ\"ש אודות יום ההולדת השלישי של בנם. . שליט\"א שהוא בר\"ח שבט והקס\"ד לעשות התספורת בל\"ג בעומר, כבר כתבתי דעתי<sup data-n=\"1800\">*</sup> ולכמה מאנ\"ש שבאם אין טעם חזק, וכמו מנהג קבוע ומיוסד ביותר נראה לי שלא לדחות התספורת, ובפרט לכמה חדשים ואפילו לכמה שבועות, ונמוקי עמי אשר כיון שכנראה מלשון כ\"ק מו\"ח אדמו\"ר בהנוגע לחג התספורת ה\"ז ענין של חינוך ביר\"ש, ז. א. המשכת קדושה על נפש הילד [י\"ל שמיוסד הנ\"ל על דרז\"ל הידועה (תנחומא פ' קדושים) וראה ג\"כ הלכות ת\"ת לרבנו הזקן בתחלתו שזה מרומז בתורה שבכתב, ובשנה הרביעית יהי' וגו' קדש], וכשעושים מעשה בזה מתחזק הענין ונמשך בעולם המעשה כמבואר בכ\"מ, הרי למה ידחו המשכת הקדושה הלזו לכמה חדשים או לשבועות והרי כל תוספת קדושה בחינוך מוסיפה בכל עניניו דהילד ואפילו הגשמים. . .\n<span data-k=\"q\">(ממכתב כ\"ו כסלו, תשי\"ז)</span>\n<hr>\n... לשאלתו מתי לעשות התספורת של בנם. . שליט\"א אף שברור לדעתי שאין להקדים קודם מלאת שלש שנים, בהנוגע לאחר בג' ימים כנדון דידי' שיום",[["1800","*","ראה לקו\"ש ח\"ז ע' 350. המו\"ל."]]],[1301490308,"הולדת י\"ג ניסן, שבאם יאריכו ג' ימים ממילא יודחה ויעשו זה על הציון דרשב\"י — יתייעץ בזה עם רבני אנ\"ש אשר באה\"ק ת\"ו. . .\n<span data-k=\"q\">(ממכתב ב' טבת, תשכ\"א)</span>\n<hr>\n... בשאלתו אודות התספורת של בנם שליט\"א שכיון שחל בימי החורף יש חשש שהשינוי הפתאומי מריבוי שער לתספורת מדוייקת עלולה לגרום הצטננות ח\"ו וכו' שלכן קס\"ד לאחר איזה זמן.\nוהנה לדעתי לא נכון הדבר, כי מלשון הידוע של כ\"ק מו\"ח אדמו\"ר בהנוגע לתספורת דג' שנים משמע שיש בזה המשכת קדושה תוספת קדושה בנשמת הילד ע\"י הנחת הפיאות וכו' ולמה יאחרו המשכה זו, אבל לאידך גיסא אין כל הכרח לתספורת מדוייקת ויכול להניח שערות גדולות לפ\"ע ובלבד שיהי' ניכר הענין דהנחת הפיאות והשי\"ת יצליחו ואת זוגתו שיחיו לגדלו לתורה ולחופה ולמעשים טובים מתוך בריאות הנכונה והרחבת הדעת.\n<span data-k=\"q\">(ממכתב כ\"ז טבת, תשי\"ז)</span>\n<hr>\nבמענה למכתבו ממוצש\"ק בראשית, ובהקדמה שמובן וגם פשוט שאין כאן מקום לבקשת סליחה וכיו\"ב, שהרי בדברי תורה המכתב מדבר, ובפרט בענינים הנוגעים לפועל, והרי צודק גם בסיום מכתבו, שזהו ענין הנוגע לרבים, כיון שנראה לרבים.\nובתוכן הקושיא או ההערה, הנה ההנהגה שכותב, ז.א. שלא לנגוע כלל בפיאות הראש, לא ראיתי' בתוככי חב\"ד, ואדרבא.\nואפשר לומר בזה כמה טעמים, ואולי גם הטעם שרומז גם במכתבו, שלא לערב הארות של שני תיקונים מהי\"ג תיקונים דדיקנא קדישא, ובכל אופן הרי מפורש שהאריז\"ל הי' חותכן ומקצרן במספרים (שעהמ\"צ וטעמ\"צ פ' קדושים).\nוע\"פ האמור הרי חלה על זה הוראת חז\"ל הוראה ברורה, במסכת דמינה אזלינן (סוכה לב, ב):\nרב אחא ברי' דרבא מהדר אתרי וחד הואיל ונפיק מפומי' דרב כהנא. עיי\"ש ברש\"י. ואת\"ל הרי כ\"ש וק\"ו בנדון דידן, שבזה לא רק דבור הרב אלא מעשה רב.\nבכבוד ובברכה.\nע\"פ הנ\"ל מבואר — שהקושיא ורבה היא אדרבה על אלו שאין נוגעין כלל —"],[1301490309,"היפך ממעשה רב דהאריז\"ל החי. ועיין ג\"כ דרכי תשובה ליו\"ד סקפ\"א שדינים הן וכו'. ובדרכי חיים ושלום סתת\"פ שלא לכוף הפאות אחורי אזנו (איברא מה שציין שם המלקט לז\"ח וכו' — וצ\"ע דכפשוטו — בז\"ח וכו' המדובר בשערות הגדלות אחורי האוזן). . .\n<span data-k=\"q\">(ממכתב כ\"ו תשרי, תשכ\"א)</span>\n<hr>\nבמענה למכתבו מיום השלישי, בו כותב אודות ענין הלבושים.\nולפלא הספק שלו בזה, בה בשעה שמביא גם במכתבו מאמרי חז\"ל וגם פסקי דינים המחייבים את הענין, וראה ג\"כ שו\"ת אדמו\"ר הצמח צדק חלק יו\"ד סי' צ\"א (והשמטה להנ\"ל בסוף שער המילואים שם), מיוסד על הכתוב (צפני' א, ח).\nולהערה שלו מהכתוב בלקו\"ד<sup data-n=\"1801\">*</sup> בפירוש מאמר חז\"ל שלא שינו את לבושם, דשייך זה לזקן ופיאות — פשוט שהנ\"ל הוא נוסף על האמור, דאין מאמר זה יוצא מידי פשוטו, לבושים ממש, לבושים חיצונים. . .\n<span data-k=\"q\">(ממכתב כ\"א מנ\"א, תשכ\"א)</span>\n<hr>\n... במ\"ש מהו הטעם לגידול הזקן, מבואר בארוכה ע\"פ נגלה בשו\"ת הצ\"צ יו\"ד סי' צ\"ג, וע\"פ פנימיות התורה בפירוש המלות להצ\"צ על הפסוק והוא רחום יכפר עון, נדפס בדרך מצותיך חלק שני ובמילואים לתהלים עם פירוש הצ\"צ עמוד תרכ\"ו, יעו\"ש דבריו כי נעמו, ועד כמה נוגע הדבר ביחוד לבחורים.\n<span data-k=\"q\">(ממכתב כ\"ה טבת, תשט\"ז)</span>\n<hr>\nלאחרי שתיקתו הארוכה נתקבל מכתבו מיום הראשון, ובמה שכותב אודות הזקן, מובן שדבריו מופרכים, כיון שנשיאנו הק' אומרים שי\"ג תקו\"ד הם צנור להשפעה לאדם ולבני ביתו והשפעה ברחמים וברחמים גדולים (יעוין בזה בפירוש המלות לכ\"ק אדמו\"ר הצמח צדק על הפסוק והוא רחום, נדפס ג\"כ במילואים לתהלים יהל אור). . .",[["1801","*","ח\"ג תו, א. המו\"ל."]]],[1301490310,"בברכה להכרת מצבו האמיתי, היינו שהזן ומפרנס לכל יספיק לו כדי פרנסתו ופרנסת כל ב\"ב שיחיו ובאופן הכשר ובאופן חסידותי וביחוד ע\"י י\"ג תקו\"ד האמורים ובמילא גם הוא עצמו יתפלא וגם יצר לו על זה, וואָס מען פּאַטערט ניערווין און געזונט על דאגות מבלי יסוד, ומובן שאין זה סתירה כלל למ\"ש בכל אשר תעשה דוקא, אלא שצ\"ל כדיוק לשון רז\"ל, יגיע כפיך כי תאכל, היינו רק יגיעת כפים גם במובן הרוחני, היינו כח המעשה והשתדלות אבל לא יגיע ראשך, היינו דאגות וטרדות הראש בזה, ואין להאריך בדבר הפשוט ומבואר בכ\"מ. . .\n<span data-k=\"q\">(ממכתב אדר\"ח אייר, תשט\"ז)</span>\n<hr>\nבמענה למכתבה מר\"ח תמוז, בו כותבת בקשר עם חתונה במשפחה, והכלה מבקשת שלפחות עד לחתונה יוריד האב את זקנו ובאם לאו וכו'.\nואף שבכלל לא זו הדרך לענות לאחד בענינים הנוגעים לשני ובפרט שברוב הפעמים אי אפשר לאחר לדעת המצב לכל פרטיו ועאכו\"כ לדעת מה שבלב השני, בכל זה לגודל התמהון באתי במענה, והתמהון הוא בשנים:\nא) אשר אדם מבוגר, שהרי כבר כלה היא, יחסה להאב ובפרסום תלוי במילוי דרישה מעין האמורה, ואדגיש עד היכן הגיעו הדברים שמפרסמת את הדרישה וכו'.\nב) שהמדובר במשפחת חב\"ד, שבודאי ידוע להם (או עכ\"פ צריך להיות ידוע) שלדעת נשיאי חב\"ד ענין גידול הזקן, הוא דבר שבהלכה, ועוד וגם זה חשוב, שסגולה מיוחדה בזה להמשכת ברכת השם בריבוי כמבואר בארוכה בכתבי אדמו\"ר הצמח צדק, והרי בכל יום ובכל מקרה זקוק האדם לברכת יוצר האדם בורא העולם ומנהיגו, ועאכו\"כ באופן עיקרי זקוקים לברכה בזמן הנחת היסוד לבנין עדי עד כחתונה ונשואין, ודוקא בקשר לחופה ונשואין באים בדרישה ובתביעה ובאופן אולטימטי, שיעשו ההיפך מהאמור, ח\"ו!\nעוד נקודה עלי להוסיף בעצם הדבר אפילו באם הי' המדובר באינם יהודים להבדיל שמתפשטת האפנה בשנים האחרונות לגדל זקן ומתקופה לתקופה מתרבים הנוהגים כן, ו(על דרך סגנון מכתבה) מביטים עליהם כבני אדם מן הישוב.\nאיני יודע מדת השפעתה שלה על הנ\"ל אבל הרי אמרו רז\"ל קבל את האמת ממי שאמרו, ויהי רצון שתצליח להסביר להנ\"ל את המוזר שבכל הענין ואת אי הגיוני שבו נוסף על הנקודה מצד ההלכותי כאן ובפרט שאבי' נהג בגידול הזקן זה מזמן.\nמובן שהאמור לעיל אינו שייך לסריקת הזקן במסרק המתאים וכפי שיבארם רב בשכונתם."],[1301490311,"ע\"פ כתבה אודות משפחתה ומוצאה, תקותי שבסיסמת משפחות חב\"ד פעילה היא בהפצת היהדות המסורתית בסביבתה ובכל מקום שידה מגעת והובטחנו דברים היוצאים מן הלב נכנסים אל לב השומע ופועלים פעולתם.\nבברכה לבשו\"ט בכל האמור.\n<span data-k=\"q\">(ממכתב ב' תמוז תשכ\"ה)</span>\n<hr>\n... ולשאלתו בענין תספורת<sup data-n=\"1802\">*</sup> וכו', — הנה כיון שלא שמעתי בזה הוראה מפורשת, יש צדדים לכאן ולכאן, ולכן יברר מנהג אנ\"ש בזה, אצל רבני אנ\"ש היודעים הנהגה בפועל מחסידים הזקנים, והרי מעשה רב. . .\n<span data-k=\"q\">(ממכתב ה' אלול, תש\"כ)</span>\n<hr>",[["1802","*","בשפה העליונה שמעכב האכילה. המו\"ל."]]],[1301490312,"<h3>אמור</h3>\n... ובמה שהעיר כת\"ר בבכורות מא, א — עפמש\"כ ברגמ\"ה שם הראי' ממה דחרס משמע חרוץ (דאותיות ס' צ' מתחלפין).\nועפ\"ז: א) מובן אמרו בש\"ס: כיון דאמר מר גרב זה החרס (דלכאורה מאי אולמי' דחרס מגרב). ב) עכצ\"ל דנגע הוא כו' — בא לראי' דמקום כאן לחילוף, כיון דבכל הנגעים צ\"ל עמוק מן הצל (אף שלסימן טומאה מספיק אם רק מראהו עמוק, ולא ממשו). כן עיין בזה תורה תמימה לתזריע יג, ג.\n<span data-k=\"q\">(ממכתב ימי הסליחות, תשי\"ט)</span>\n<hr>"],[1301490313,"<h3>ל\"ג בעומר</h3>\nב\"ה<sup data-n=\"1803\">*</sup>, יום שלישי, שהוכפל בו כי טוב<sup data-n=\"1804\">1</sup>,\nערב ראש חודש<sup data-n=\"1805\">2</sup> אייר<sup data-n=\"1806\">3</sup> ה'תשמ\"ז.\nברוקלין, נ.י.\nאל כל ילדי ישראל\nהשם עליהם יחיו\nשלום וברכה!\nודאי ידוע לכם כי כל דבר חשוב שצריכים לעשותו דורש שיתכוננו<sup data-n=\"1807\">5</sup> לכך בעוד מועד, כדי שהדבר ייעשה כראוי<sup data-n=\"1808\">6</sup>.\nאנו עומדים בערב חודש אייר, החודש שבו ישנו יום חשוב ביותר, לג בעומר<sup data-n=\"1809\">7</sup><sup data-n=\"1810\">4</sup>, היום השמונה עשרה (ח\"י) באייר<sup data-n=\"1811\">8</sup>, שבו גם הונהגו מנהגים מיוחדים לילדים<sup data-n=\"1812\">9</sup>,",[["1803","*","תרגום מאידיש. וכן מכתב שלאח\"ז. המו\"ל."],["1804","1","<b>יום. . שהוכפל בו כי טוב</b>: פרש\"י בראשית א, ז (מב\"ר פ\"ד, ו). ובאוה\"ת (בראשית לג, ב. משפטים ע' א'קנז. ועוד) מקשר זה עם טוב לשמים וטוב לבריות (קידושין מ, א)."],["1805","2","<b>ערב ראש חודש</b>: שנקרא \"יום כפור קטן\" — ראה פר\"ח לאו\"ח סתי\"ז (מהרמ\"ק). נ\"כ השו\"ע שם. של\"ה קכ, ב. קעט, א. ועוד. סידור יעב\"ץ. ועוד. אוה\"ת בא ע' רנג."],["1806","3","<b>חודש אייר</b>: ראה לקו\"ש ח\"א ע' 263 ואילך. ועוד. ולהעיר מכתבי האריז\"ל (סידור האריז\"ל כוונת ר\"ח. משנת חסידים מס' אייר וסיון בתחילתה), אשר צירוף שם הוי' דחודש אייר הוא בראשי התיבות \"יתהלל המתהלל השכל וידוע\" (ירמי' ט, כג). — נתבאר בהתוועדות ש\"פ שמיני, מבה\"ח וער\"ח אייר ה'תשמ\"ה. ור\"ת שלו אברהם יצחק יעקב רחל (מאו\"א א, פד. בית שמואל לאה\"ע סקכ\"ו סק\"כ). — נתבאר בלקו\"ש ח\"ז ע' 300 ואילך. והוא ג\"כ ר\"ת \"אני הוי' רופאך\" (בשלח טו, כו. חידושי חת\"ס לשבת קמז, ב. שער יששכר מאמר חודש אייר ס\"ג (פח, א­ב)). — נתבאר בהתוועדות ש\"פ קדושים, מבה\"ח אייר ה'תשד\"מ. ש\"פ שמיני, מבה\"ח אייר שנה זו<sup data-n=\"e41\">*</sup>."],["1807","5","<b>כל דבר חשוב. . דורש שיתכוננו</b>: ראה ביצה ב, ב בפרש\"י ד\"ה והכינו, וד\"ה ואין. וראה אנציקלופדי' תלמודית ערך הכנה. וש\"נ."],["1808","6","<b>כראוי</b>: ראה כתובות סז, רע\"א."],["1809","7","<b>לג בעומר</b>: יום הילולא דרשב\"י. עניניו וטעמיו מפורשים בפוסקים ע\"ד הנגלה (טושו\"ע — ודאדה\"ז — או\"ח סתצ\"ג), וכן ע\"ד הסוד (שער הכוונות ענין ספה\"ע דרוש י\"ב. פע\"ח שער ספה\"ע (שכ\"ב) פ\"ז. ועוד), וע\"ד החסידות (סידור — עם דא\"ח — שער הל\"ג בעומר, המשך והחרים תרל\"א ס\"ע נד ואילך, דרושים שבהערה דלהלן ד\"ה \"שמחתו\", ועוד)."],["1810","4","<b>אייר. . לג בעומר</b>: ראה לקוטי לוי\"צ אגרות ע' תד."],["1811","8","<b>לג בעומר. . (ח\"י) באייר</b>: ראה לקו\"ש חכ\"ב ע' 141."],["1812","9","<b>מנהגים מיוחדים לילדים</b>: ראה שער הכוונות ופע\"ח ופע\"ח שם. בני יששכר מאמרי חודש אייר מאמר ג ס\"ד­ה. ספר \"בין פסח לשבועות\" (להרר\"צ שי' כהן. אה\"ק, תשד\"מ) פי\"ח סל\"ג­ד. פי\"ט ס\"ח­ט. וש\"נ. וראה שיחת ל\"ג בעומר ה'תשי\"א.\nולהעיר מ\"היום יום\" לג בעומר: אצל אדמו\"ר האמצעי הי' לג בעומר מיו\"ט המצויינים. . מען האָט דאַמאָלט געזען אַ סך מופתים. דאָס רוב מופתים איז געווען בנוגע קינדער כו'. וראה שיחת ל\"ג בעומר ה'תש\"מ. וראה עוד ע\"ד הנהגת רבותינו נשיאינו בל\"ג בעומר — לקו\"ד ח\"ג תקיט, א ואילך. שם תקכג, א. ח\"ד תרג, א ואילך. סה\"ש ה'תש\"ד ע' 119."],["e41","*","נדפס לעיל ע' 72 ואילך. המו\"ל."]]],[1301490314,"וגם להשפיע על אחרים שגם הם יעשו כן, בהתאם לציוויו של הקב\"ה \"ואהבת לרעך כמוך<sup data-n=\"1813\">11</sup>\",\nלכן מן הראוי שכל אחד ואחת מכם יתכונן לכך, על ידי כך שתתחילו ללמוד מן ההוראות האמורות והמעשים הטובים,\nוביום ל\"ג בעומר, היום של \"שמחתו\"<sup data-n=\"1814\">12</sup>, כפי שכינה רבי שמעון בן יוחאי את היום הזה, תקיימו כינוס לכבודו ותעשו כל האמור כולכם יחד<sup data-n=\"1815\">13</sup>, וכן תערכו תהלוכה במקום מגוריכם, כדי לפרסם עוד יותר את הקשר שלכם עם התורה באמצעות רבי שמעון בן יוחאי, שאצלו היתה \"תורתו-אומנתו<sup data-n=\"1816\">14</sup>\" (התורה היתה התעסקותו העיקרית),\nותבקשו את הוריכם ומחנכיכם שיחיו לעזור לכם בכל זה, כפי ציווי התורה שעומדים לקרוא ערב לג בעומר בכל בתי הכנסת שבכל מקום: \"אמור גו' ואמרת\"<sup data-n=\"1817\">15</sup>, כפי שרבותינו זכרונם לברכה מפרשים: \"להזהיר גדולים על הקטנים\"<sup data-n=\"1818\">16</sup>.\nוגדולה זכותו של רבי שמעון<sup data-n=\"1819\">17</sup> בן יוחאי — להצליח לכל אחד מכם בלמוד התורה ובקיום המצוות, וכל זה בשמחה<sup data-n=\"1820\">18</sup>, כולל כל האמור לעיל,\nולזכות בקרוב ממש לראות \"עושה נפלאות אתה אלוקים\"<sup data-n=\"1821\">19</sup> — אראנו נפלאות<sup data-n=\"1822\">20</sup>",[["1813","11","<b>ואהבת לרעך כמוך</b>: קדושים יט, יח. ובתו\"כ (הובא בפרש\"י) עה\"פ; ירושלמי נדרים פ\"ט ה\"ד: ר' עקיבא (רבו של רשב\"י) אומר זה כלל גדול בתורה [ולהעיר שרשב\"י אמר לתלמידיו \"בניי, שנו מדותי שמדותי תרומות מתרומות מדותיו של ר' עקיבא\" (גיטין סז, א. וראה סה\"ש ה'ש\"ת ע' 107)]. וראה ד\"ה להבין ענין ל\"ג בעומר בס' מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא ואילך."],["1814","12","<b>\"שמחתו\"</b>: ראה שער הכוונות ופע\"ח שם. מ\"ח מס' אייר וסיון פ\"ו מ\"ו. ושם מ\"ז: שמחה גדולה. וראה ד\"ה להבין ענין הילולא דרשב\"י בסה\"מ תקס\"ד (ע' קא ואילך, ועם הגהות — באוה\"ת ענינים ע' ריח ואילך); במאמרי אדהאמ\"צ ויקרא ח\"ב (ע' תרסו ואילך), ובסה\"מ תרנ\"ד (ע' רסא ואילך), ועוד — בטעם שעושין שמחה ביום ההילולא דרשב\"י אף שנקבע תענית של מיתת צדיקים. וראה לקו\"ש ח\"ז ע' 343 בהערה. וש\"נ."],["1815","13","<b>כולכם יחד</b>: להעיר מתו\"כ (הובא בפרש\"י) עה\"פ בחוקותי כו, ח. קונטרס החלצו, תרנ\"ט פ\"י, וראה גם שם פ\"ז (סה\"מ תרנ\"ט ע' סא. שם ע' נח­נט)."],["1816","14","<b>תורתו­אומנתו</b>: שבת יא, א. טושו\"ע (ודאדה\"ז) או\"ח סו\"ס קו. הל' ת\"ת לאדה\"ז פ\"ד ס\"ד­ה. וראה ירושלמי ברכות פ\"א סוף ה\"ב. שבת פ\"א סוף ה\"ב."],["1817","15","<b>\"אמור גו' ואמרת\"</b>: ר\"פ אמור."],["1818","16","<b>\"להזהיר גדולים על הקטנים\"</b>: תו\"כ (הובא בפרש\"י) עה\"פ. יבמות קיד, סע\"א. וש\"נ. וראה לקו\"א להה\"מ (הוצאת קה\"ת) סכ\"ג (ח, א). או\"ת ר\"פ אמור (מב, א. בהוצאת קה\"ת ה'תש\"מ ואילך — סקי\"ט). ובצוואת הריב\"ש (הוצאת קה\"ת) בתחילתו: פי' זהיר מלשון והמשכילים יזהירו, ר\"ל הנשמה תזהיר ותאיר כו'. ועד\"ז בסה\"מ תרפ\"ח ע' קנד ואילך. אגרות­קודש לכ\"ק אדמו\"ר מוהריי\"צ נ\"ע ח\"ג ע' קכט ואילך. וראה לקו\"ש ח\"ז ע' 2­151."],["1819","17","<b>זכותו של רבי שמעון</b>: להעיר ממאמר רשב\"י (סוכה מה, ב): יכול אני לפטור את כל העולם כולו כו'."],["1820","18","<b>בשמחה</b>: ראה זח\"ג נו, א. רמב\"ם סוף הל' לולב. ד\"ה עבדו את ה' בשמחה תרצ\"ט (סה\"מ תרצ\"ט ס\"ע 94 ואילך)."],["1821","19","<b>\"עושה נפלאות אתה אלוקים\"</b>: תהלים פו, יו\"ד."],["1822","20","<b>אראנו נפלאות</b>: מיכה ז, טו. וראה ד\"ה כימי צאתך די\"א ניסן ה'תשמ\"ב (סה\"מ מלוקט ח\"ב ע' לז). וש\"נ."]]],[1301490315,"בגאולה האמיתית והשלימה על ידי משיח צדקנו.\nבברכת ראש חודש\nולהצלחה רבה\nמקום החתימה\n<hr>\nב\"ה, יום שלישי, שהוכפל בו כי טוב,\nערב ראש חודש אייר, ה'תשמ\"ז.\nברוקלין, נ.י.\nאל כל ההורים היהודיים\nואל כל המחנכים והמחנכות היהודיים\nהשם עליהם יחיו\nשלום וברכה!\nבהתבסס על ציווי התורה \"אין מזרזין אלא למזורזין\"<sup data-n=\"1823\">1</sup>, וכפי שידועה מעלת הזריזות<sup data-n=\"1824\">2</sup> ונחיצותה, בכל עניני היהדות,\nובמיוחד בביצוע הציווי התלת-פעמי של התורה<sup data-n=\"1825\">3</sup> \"להזהיר גדולים על הקטנים\" — היסוד של החינוך האמיתי,\nכולל גם התוכן של המכתב המצורף \"אל כל ילדי ישראל\" שליט\"א\nהמכתב יחד עם בקשה נפשית לסייע, לעודד ולזרז בכל עניני המכתב ובמיוחד בקיום הכינוס ועריכת התהלוכה,\nובוודאי יוסיף הדבר עוד יותר בברכת הקב\"ה — לרוות מכל אחד מן הילדים נחת-תורה אמיתי, חדור בפנימיות התורה כפי המבואר בזוהר<sup data-n=\"1826\">4</sup> \"חיבורא דילך\" של רבי שמעון בן יוחאי בעל השמחה של לג בעומר.\nויהי רצון שכל זה יחיש עוד יותר את ההבטחה בזוהר: \"בהאי חיבורא דילך דאיהו ספר הזוהר כו' יפקון בי' מן גלותא ברחמים\", במהרה בימינו ממש.\nבכבוד ובברכת\nהצלחה רבה בכל זה\nובברכת חודש טוב\nמקום החתימה\n<hr>",[["1823","1","<b>\"אין מזרזין אלא למזורזין\"</b>: ספרי נשא בתחילתו. במדב\"ר פ\"ז, ו. וראה מכות כג, א. וראה מכתב ער\"ח טבת תש\"ג<sup data-n=\"e42\">*</sup>."],["1824","2","<b>מעלת הזריזות</b>: ראה אגה\"ק סכ\"א."],["1825","3","<b>הציווי התלת­פעמי של התורה</b>: ראה יבמות קיד, סע\"א ואילך. וראה מכ' ח' אייר תשג\"ה, ג' וי\"א אייר תש\"ד<sup data-n=\"e43\">**</sup>. לקו\"ש ח\"ז ע' 147 ואילך."],["1826","4","<b>בזוהר</b>: ח\"ג קכד, ב (ברע\"מ). הובא ונתבאר באגה\"ק סכ\"ו."],["e42","*","נדפס באגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"א (קה\"ת, תשמ\"ז) ע' סח. המו\"ל."],["e43","**","נדפסו באגרות­קודש שם ע' קיט­כ. ע' רפג ואילך. המו\"ל."]]],[1301490316,"ב\"ה, יום א' פ' בחוקותי<sup data-n=\"1827\">1</sup>,\nתפארת שבהוד,\nתשמ\"ט. ברוקלין, נ.י.\nאל כל בני ובנות ישראל\nבכל מקום שהם\nה' עליהם יחיו\nשלום וברכה!\nבעמדנו בתקופה דשבע שבתות תמימות<sup data-n=\"1828\">2</sup>, ובה עצמה בהשבת דל\"ג בעומר<sup data-n=\"1829\">3</sup>, ובתוך ותחלת שלשת הימים<sup data-n=\"1830\">4</sup> דיום סגולה זה,\nאשר בודאי כל אחד ואחת<sup data-n=\"1831\">17</sup> מתעורר לתוספת בתומ\"צ במיוחד בקשר ליום זה\nובפרט שבשנה זו הקביעות שלו היא ביום שלישי שהוכפל בו כי טוב<sup data-n=\"1832\">5</sup>, טוב לשמים וטוב לבריות<sup data-n=\"1833\">6</sup>\nהנני לעורר ע\"ד הצעת רבים והחלטתם לעשות כן במעשה בפועל, והמעשה הוא העיקר<sup data-n=\"1834\">7</sup>,\nלהוסיף בתורה עבודה וגמ\"ח — עליהם העולם עומד<sup data-n=\"1835\">8</sup>\nוהרי רשב\"י<sup data-n=\"1836\">9</sup> עליו נאמר וצדיק יסוד עולם<sup data-n=\"1837\">10</sup>",[["1827","1","<b>פ' בחוקותי</b>: ראה או\"ת להה\"מ (הוצאת קה\"ת) ר\"פ בחוקותי. כש\"ט (הוצאת קה\"ת) סו\"ס רז (כז, א)."],["1828","2","<b>דשבע שבתות תמימות</b>: אמור כג, טו."],["1829","3","<b>דל\"ג בעומר</b>: יום הילולא דרשב\"י. עניניו וטעמיו מפורשים בפוסקים ע\"ד הנגלה (טושו\"ע — ודאדה\"ז — או\"ח סתצ\"ג), וכן ע\"ד הסוד (שער הכוונות ענין ספה\"ע דרוש י\"ב. פע\"ח שער ספה\"ע (שכ\"ב) פ\"ז. ועוד), וע\"ד החסידות (סידור — עם דא\"ח — שער הל\"ג בעומר, המשך והחרים תרל\"א ס\"ע נד ואילך, דרושים שבהערה דלהלן ד\"ה \"וכדרישת רשב\"י\", ועוד)."],["1830","4","<b>ובתוך. . שלשת הימים</b>: ראה פסחים קו, סע\"א. גיטין עז, א. וראה רמב\"ם הל' שבת פכ\"ט ה\"ד. הל' גירושין פ\"ט הכ\"ג. שו\"ע אה\"ע סקמ\"ג ס\"ו. ובשו\"ע אדה\"ז או\"ח הל' שבת סרצ\"ט ס\"ח: שג' ימים הראשונים של השבוע נקראים ימים שאחר השבת. ועיין ג\"כ שו\"ע אדה\"ז שם סרפ\"ה ס\"ה. ולהעיר גם מהדין (רמב\"ם הל' שבת פ\"ט ה\"ח. ובכ\"מ) שכל פחות משלשה כלבוד דמי."],["1831","17","<b>בתוך כל אחד ואחת</b>: ע\"ד מארז\"ל עה\"פ (תרומה כה, ח) ועשו לי מקדש ושכנתי בתוכם — בתוך כאו\"א — ראה לקו\"ש חכ\"ו ע' 414. וש\"נ."],["1832","5","<b>ביום שלישי שהוכפל בו כי טוב</b>: פרש\"י בראשית א, ז (מב\"ר פ\"ד, ו)."],["1833","6","<b>טוב לשמים וטוב לבריות</b>: ראה קידושין מ, א. ובאוה\"ת (בראשית לג, ב. משפטים ע' א'קנז. ועוד) ובמכתב כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע (נדפס בסה\"מ ה'תש\"ט ע' 19 (השני) ואילך. אגרות­קודש שלו ח\"א ע' קלה ואילך) מקשר זה עם יום שלישי שהוכפל בו כי טוב."],["1834","7","<b>והמעשה הוא העיקר</b>: אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["1835","8","<b>תורה עבודה וגמ\"ח — עליהם העולם עומד</b>: אבות פ\"א מ\"ב. וראה לקו\"ת שלח מט, ב. ד\"ה על שלשה דברים ה'ש\"ת (סה\"מ ה'ש\"ת ע' 160 ואילך)."],["1836","9","<b>רשב\"י</b>: ראה ד\"ה להבין ענין רשב\"י ה'תשמ\"ה — סה\"מ מלוקט ח\"ב ע' שא ואילך. וש\"נ."],["1837","10","<b>רשב\"י עליו נאמר וצדיק יסוד עולם</b>: משלי י, כה. זהר ח\"א (בהשמטות) רנה, סע\"א. ז\"ח ר\"פ וירא."]]],[1301490317,"נתינה לצדקה במספר ח\"י — והרי ל\"ג בעומר הוא ח\"י באייר<sup data-n=\"1838\">11</sup> (ר\"ת\nאברהם יצחק יעקב רחל<sup data-n=\"1839\">12</sup> — שכוללת כל ד' האמהות)\nבעבודה — מזמור ל\"ג בתהלים, ספר תפילות<sup data-n=\"1840\">13</sup> דוד בן ישי בתור נעים זמירות כל בני ישראל<sup data-n=\"1841\">14</sup>\nבתורה — בפרשת השבוע, ובפרט בחלקו המיוחד ליום זה<sup data-n=\"1842\">15</sup>, יום השלישי:\nואכלתם גו' ונתתי משכני בתוככם (בתוך כל אחד ואחת) גו' ואולך אתכם<sup data-n=\"1843\">18</sup> קוממיות<sup data-n=\"1844\">16</sup>.\nויקויים היעוד תבוא לפניך תפילתי הטה אזנך לרינתי<sup data-n=\"1845\">19</sup>\nאשר השם, שכמאמר רשב\"י<sup data-n=\"1846\">20</sup> — הוא תמיד עם כאו\"א בכ\"מ שהוא נמצא\nיקיים תומ\"י היעודים: מצאתי דוד עבדי<sup data-n=\"1847\">21</sup>, ונתתי משכני בתוככם זה ביהמ\"ק<sup data-n=\"1848\">22</sup> השלישי, מקדש אד' כוננו ידיך<sup data-n=\"1849\">23</sup>\nוהודיעה תורתנו, תורת חיים, הוראה<sup data-n=\"1850\">24</sup> בחיי כל יום ויום: כדאי הוא רשב\"י לסמוך עליו בשעת הדחק<sup data-n=\"1851\">25</sup> — הגלות<sup data-n=\"1852\">26</sup>, ומיד הן נגאלין<sup data-n=\"1853\">27</sup>.",[["1838","11","<b>ל\"ג בעומר הוא ח\"י באייר</b>: ראה לקו\"ש חכ\"ב שיחה לל\"ג בעומר ס\"ה (ע' 141)."],["1839","12","<b>אייר (ר\"ת אברהם יצחק יעקב רחל</b>: מאורי אור מערכת א' אות פד. ב\"ש לאה\"ע סקכ\"ו ס\"כ. מגלה עמוקות אופן קכא."],["1840","13","<b>בעבודה. . תפילות</b>: שהתפלה במקום קרבנות תיקנוה (ברכות כו, א­ב. זח\"ב כ, ב), ונקראת עבודה (תענית ב, א. רמב\"ם הל' תפלה בתחלתן. סהמ\"צ מ\"ע ה. רבינו יונה באבות שם)."],["1841","14","<b>נעים זמירות כל בני ישראל</b>: ראה שמואל­ב כג, א: נעים זמירות ישראל. וראה שהש\"ר פ\"ד, (בתחילתה) — שאמר ה\"זמירות (בשם כל) ישראל\"."],["1842","15","<b>ובפרט בחלקו המיוחד ליום זה</b>: ראה \"היום יום\" יט טבת, מסה\"ש ה'תש\"ב ע' 27. וראה \"היום יום\" ב חשון (מסה\"ש שם ס\"ע 29 ואילך): מע באַדאַרף לעבן מיט דער צייט. . מיט דער פרשת השבוע און פרשת היום פון דער סדרה פון דער וואָך."],["1843","18","<b>ואולך אתכם קוממיות</b>: ראה תו\"כ עה\"פ: ר\"ש אומר כו'. וראה לקו\"ש ח\"ז ע' 344 הערה ד\"ה זה."],["1844","16","<b>ואכלתם גו' ונתתי משכני בתוככם. . גו' ואולך אתכם קוממיות</b>: פרשתנו (בחוקותי) כו, י­יא. שם, יג."],["1845","19","<b>תבוא. . לרינתי</b>: תהלים פח, ג. וראה קונטרס משיחות שבת הגדול, ערב י\"א ניסן שנה זו ס\"ט (סה\"ש תשמ\"ט ח\"א ע' 393 ואילך). וש\"נ."],["1846","20","<b>שכמאמר רשב\"י</b>: מגילה כט, א. ירושלמי תענית פ\"א ה\"א (קרוב לסופה)."],["1847","21","<b>מצאתי דוד עבדי</b>: תהלים פט, כא. וראה סנהדרין צז, סע\"א."],["1848","22","<b>ונתתי משכני בתוככם זה ביהמ\"ק</b>: תו\"כ הובא בפרש\"י עה\"פ."],["1849","23","<b>מקדש אד' כוננו ידיך</b>: בשלח טו, יז ובפרש\"י. וראה פרש\"י ותוס' סוכה מא, סע\"א. תוד\"ה אין — שבועות טו, ריש ע\"ב. ועוד."],["1850","24","<b>תורתנו. . הוראה</b>: ראה זח\"ג נג, ב. רד\"ק לתהלים יט, ח. גו\"א ר\"פ בראשית."],["1851","25","<b>כדאי הוא רשב\"י לסמוך עליו בשעת הדחק</b>: ברכות ט, א. וש\"נ."],["1852","26","<b>בשעת הדחק — הגלות</b>: ע\"ד הרמז, הובא ג\"כ בשער יששכר סוף המאמר לל\"ג בעומר."],["1853","27","<b>ומיד הן נגאלין</b>: ראה רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1301490318,"בכבוד ובברכה, וכדרישת רשב\"י — להשתתף בשמחתו רבה<sup data-n=\"1854\">29</sup> דל\"ג בעומר<sup data-n=\"1855\">28</sup> — דבחד קטירא<sup data-n=\"1856\">30</sup> אתקטרנא בי' בקוב\"ה בי' אחידא בי' להיטא בי' אתדבקת — ובאופן דנר להאיר — השפעה בזה בכל סביבתו, אנשים נשים וטף\nמקום החתימה\nנ. ב. מובן ופשוט שגם לאחר ל\"ג בעומר יש לעשות ולהשלים כל הנ\"ל, כלימוד פסח שני<sup data-n=\"1857\">31</sup> דמיני' אזלינן: ניטאָ קיין פאַרפאַלן<sup data-n=\"1858\">32</sup>, ובכפליים לתושי'<sup data-n=\"1859\">33</sup>.",[["1854","29","<b>בשמחתו רבה</b>: ראה משנת חסידים שם מ\"ז: שמחה גדולה. וראה זח\"ג (אדרא זוטא) רפז, ב. שם רצא, סע\"א: קם ר\"ש ויתיב וחייך וחדי כו' והוי חדי כו' קוב\"ה וכל הני זכאי קשוט דהכא כו' חדאן בהאי הילולא דילי."],["1855","28","<b>וכדרישת רשב\"י — להשתתף בשמחתו רבה דל\"ג בעומר</b>: ראה פע\"ח שער ספה\"ע (שכ\"ב) פ\"ז (וראה עט\"ז לשו\"ע או\"ח סתצ\"ג). משנת חסידים מס' אייר וסיון פ\"א מ\"ו. ובשו\"ע אדה\"ז או\"ח סתצ\"ג ס\"ה: נוהגין קצת להרבות בשמחה ביום זה. וראה רמ\"א שם ס\"ב. וראה אגרות­קודש אדמו\"ר הזקן ריש ע' קיז: ואי לזאת שישו ושמחו בה' בכל לב ונפש ולעשות יום משתה ושמחה בח\"י אייר הבע\"ל לטובה יומא דהלולא דרשב\"י כו'.\nוראה ד\"ה להבין ענין הילולא דרשב\"י בסה\"מ תקס\"ד (ע' קא ואילך, ועם הגהות — באוה\"ת ענינים ע' ריח ואילך); מאמרי אדהאמ\"צ ויקרא ח\"ב (ע' תרסו ואילך); סה\"מ תרנ\"ד (ע' רסא ואילך), ועוד — בטעם שעושין שמחה ביום ההילולא דרשב\"י אף שנקבע תענית על מיתת צדיקים. וראה לקו\"ש ח\"ז ע' 343 בהערה. וש\"נ."],["1856","30","<b>דבחד קטירא כו'</b>: ראה זהר שם רפח, א. רצב, א. וראה לקוטי לוי\"צ לזח\"ג שם (רצב, א) — ע' תסב ואילך. ד\"ה פתח ר\"ש דש\"פ אמור, י\"ט אייר ה'תשל\"ד (סה\"מ מלוקט ח\"ג ע' קנא)."],["1857","31","<b>ל\"ג בעומר. . פסח שני</b>: ראה לקוטי לוי\"צ אגרות ע' תד."],["1858","32","<b>כלימוד פסח שני. . ניטאָ קיין פאַרפאַלן</b>: \"היום יום\" יד אייר, פסח שני (משיחת פסח שני ה'תש\"א ס\"ה — סה\"ש ה'תש\"א ע' 115)."],["1859","33","<b>ובכפליים לתושי'</b>: לשון הכתוב — איוב יא, ו. וראה שמו\"ר רפמ\"ו."]]],[1301490319,"<h3>בהר</h3>\nבתודה קבלתי מכתבו מכ\"א סיון, ואחרי זה נתקבלו גם שני ספריו הלכות שמיטת קרקעות וס' קרבה שנת השבע.\nות\"ח על כתבו המפורט ושימת לבבו לשלוח לי הנ\"ל.\nאף שאין הזמן גרמא לעיין בהענינים אודותם כותב ככל הדרוש, ובפרט לתווך למש\"כ בס' לאור ההלכה וש\"נ — הנה לכאורה צ\"ע מפני מה בהנוגע לאילנות לא נזכר גם ענין מכירת הקרקע לזמן<sup data-n=\"1860\">*</sup>, כיון שמהמלאכות הנעשות באופן שמתאר כת\"ר זקוקים לסניף ההיתר, ולדעת כמה גדולים המכירה לזמן מועלת בזה, ועי\"ז יצילו גם אלו שלמרות ההוראות יעשו גם ממלאכות שלא התירו, ושבעוה\"ר נמצאים הם בכ\"מ, כי מלאכה גוררת מלאכה. . .\n<span data-k=\"q\">(ממכתב כ\"ה תמוז, תשי\"ז)</span>\n<hr>\nמיט גרויס פאַרוואונדערונג און נאָך גרעסערן צער האָב איך געלייענט אייער בריוו, וועלכן איר הויבט אָן מיט אַ לויב צום אויבערשטן וואָס איר רעכנט (ח\"ו) פאָרן אין ארץ ישראל מיט אַ שיף וואָס אירע בעלי-בתים זיינען אידן, און דער קאַפּיטאַן און מאַטראָסן און גאַנצע מאַנשאַפט און באַדינונג זיינען אַלע אידן אָדער 99 פון זיי זיינען אידן; און איר זעצט פאָר אייער שרייבן, אַז דער זכות פון די הייליקע אבות אבותינו זאָל מצליח זיין די נסיעה!\nאיך וואָלט גערעכנט, אַז ס'איז איבעריק צו דערקלערן די סיבה פון מיין גרויסן צער, אָבער דער אינהאַלט פון אייער בריוו ברענגט מיר צום שרייבן וועגן דעם ווייניקסטנס געציילטע שורות, כאָטש וויפל מ'וואָלט וועגן דעם ניט געשריבן וואָלט געווען ווייניק אין פאַרגלייך מיט דער האַרבקייט פון דער זאַך. אין קורצן:\nאַ נסיעה אויף אַזאַ מין סאָרט שיף — איז יעדער פאָרער, שוין אָפּגערעדט פון דער מאַנשאַפט וואָס איז באַשעפטיקט אויף דער שיף, א) מחלל שבת ב) בפרהסיא, ג) נעמט אַן אָנטייל אין חילול השם בפרהסיא (אויך פאַר אַלע גויים) וואָס ווייסן פון דאָס אויבנדערמאָנטע, ד) דאָס ווערט געטאָן אין נאָמען פון גאַנצן אידישן פאָלק,",[["1860","*","מובן שאין כוונתי אלא שגם ימכרו לזמן (למרות החוששים ללא תחנם וכידוע דעת החולקים עליהם) אבל לא שיתירו עוד מלאכות — כיון שלא בא זה אלא לסניף."]]],[1301490320,"וועמענס ביישטייערונגען באַ פאַרשידענע געלעגנהייטן האָט בייגעטראָגן צו דער אָפּערירונג און פונקציאָנירן פון דער שיף אום שבת.\nס'איז נאָך צוצוגעבן, אַז ס'איז אַ זעלטענע מעגלעכקייט צו מחלל שבת זיין בפרהסיא יעדן רגע פון דעם מעת-לעת פון שבת-קודש, אפילו ווען מען שלאָפט! וואָרום די שיף פאָרט דאָך אויך ווען מען שלאָפט. [דאַקעגן, זייענדיק אויף דער יבשה, וואָס פאַראַ סאָרט לעבן איינער פירט, איז ער אָבער ווייניקסטנס שלאָפנדיק ניט עובר אויף חילול שבת בפרהסיא].\nדאָס אויבנגעשריבענע איז אין פולער קראַפט וואוהין די שיף זאָל ניט פאָרן און ווען זי זאָל אַרויספאָרן, אויב נאָר זי פאָרט אין מעת-לעת פון שבת. אין דעם פאַל קומט נאָך צו דאָס וואָס מ'וויל פאָרן אין אַ לאַנד וואָס אַפילו גויים רופן אָן \"דאָס הייליקע לאַנד\", ניט דערפאַר וואָס די יונייטעד ניישאָנס האַלט אַזוי, נאָר דערפאַר וואָס אַזוי איז געשריבן אין אונזער הייליקער תורה, וועלכע האָט פאַרבונדן דעם קיום פון ארץ ישראל ספּעציעל מיט אָפּהיטן שבת, ווי אָנגעוויזן אין פיל סדרות, צווישן זיי — בהשגחה פּרטית — אויך אין דער סדרה וואָס מ'גייט לייענען דעם שבת-קודש.\nדאָס אויבנגעשריבענע איז שוין אויך אַ מאַקסימום אומגליק ר\"ל, אָבער די נסיעה וועגן וועלכע איר שרייבט קומט דאָ נאָך צו אַן אומגליק אויף אַן אומגליק, וואָס אין צוגאָב צו די צוויי אָדער דריי שבתים וואָס ווי אויבנגעשריבן זיינען פאַרבונדן מיט חילול שבת בפרהסיא ח\"ו, קומט אין דעם פאַל נאָך צו דער חילול פון ביידע טעג שבועות בפרהסיא, דער יום-טוב ווען עס איז געגעבן געוואָרן די עשרות הדברות, געגעבן געוואָרן מיטן גאַנצן שטורם, ווי עס ווערט דערציילט אין מדרשים, וואָס איינער פון די עשרת הדברות איז שמור את יום השבת לקדשו. מערניט וואָס מ'לעבט אין אַ צייט ווען מעגעוואוינט זיך צו צו אַלערליי אומגלויבלעכע זאַכן קען אויך פאָרקומען אַ געשעניש ווי אויבענגעשריבן, באין פּוצה פּה ומצפצף.\nזעלבסטפאַרשטענדלעך ווייס איך, אַז עס זיינען דאָ אַזוינע וואָס האָבן גענומען אויף זיך די אחריות — ניט וויסנדיק ווי אַזוי אַ שיף ווערט אָנגעפירט, און צו דער זעלבער צייט האַלטנדיק זיך פאַר גרויסע עקספּערטן אין דעם — און האָבן מתיר געווען דעם חילול שבת בפרהסיא וואָס ווערט אָנגעפירט אין נאָמען פון כלל ישראל. און וועדליג ווי מ'דערציילט איז צו גלויבן אַז שבת זאָל אויף דער שיף שטיין אַ איד אין אַ טלית און דאַוונען צום אויבערשטן מקדש השבת, וויסנדיק אַז בשעת מעשה ווערט די מאַשינעריי אָנגעצונדן און אָנגעפירט דורך אידן, טעלעגראַמעס ווערן געשריבן און קאָמוניקאַציעס געמאַכט, געקאָכט און געוואַשן אאַ\"וו, אַלץ דורך אידן, ספּעציעל פאַר אידן, און יעדערער פון די פּאַסאַזשירן באַנוצט זיך דערמיט, ווי אויך מיט עלעקטריציטעט, וואַסער, און אַלע באַדינונגען וואָס ווערן אָפּגעטאָן מיט חילול שבת.\nאָבער ס'איז אויך זעלבסטפאַרשטענדלעך, אַז תורתנו הקדושה ווערט דערמיט"],[1301490321,"ניט געענדערט, וואָרום אונזער הייליקע תורה איז אַן אייביקע תורה וואָס דער אויבערשטער האָט געגעבן צום אידישן פאָלק, און מענטשן קענען זי ניט ענדערן.\nאַזוי ווי חכמינו זכרונם לברכה האָבן אָנגעזאָגט, אַז אַ איד טאָר קיינמאָל זיך ניט מייאש זיין, וויל איך נאָך איצט ניט אויפגעבן די האָפנונג אַז איר און צוזאַמען מיט אייך נאָך פיל פיל אידן וועלן ניט טאָן דעם חילול שבת בפרהסיא און דעם חילול יום-טוב בפרהסיא, און איר וועט מבטל זיין אייער דערמאָנטע נסיעה. און גרויס איז דער זכות פון שבת צו ברענגען אייך אריכות ימים ושנים טובות, און זעלבסטפאַרשטענדלעך די עיקר'דיקע זאַך — צו האָבן אמתע אידישע תורה-נחת פון אייערע קינדער און קינדסקינדער שיחיו.\nבברכה צו גוטע בשורות אין דאָס געשריבענע אויבן.\nאויב מצד דעם וואָס מען איז מבטל די נסיעה אַזוי קורץ פאַרן אָפּפאָרן איז דאָס פאַרבונדן מיט אַ געלט-פאַרלוסט, איז פאַרשטייט זיך אַז נעמענדיק אין אַכט דעם גרויסן איסור בפרהסיא, וועל איך גערן אומקערן אייך די פולע סומע, מיט אַ הערצלעכן דאַנק פאַר דער געלעגנהייט מציל צו זיין אַ אידישע נשמה פון אַזאַ אומגליק ר\"ל, אין צוגאָב וואָס עס איז דאָך מעגלעך אַז עס וועלן זיך געפינען נאָך עטלעכע, וועלכע וועלן ניט האָבן דעם אויסרייד אַז אויב מרת. . . פאָרט איז אַ זיכערע זאַך אַז מ'מעג, און אויך אָפּהאַלטן זיך דערפון. און ס'איז דאָך באַוואוסט, אַז מציל זיין אפילו איין אידן איז גלייך צו מציל זיין אַ גאַנצע וועלט.\nצו אייער בריוו האָט איר צוגעלעגט אַ טשעק אויף צדקה אין צוזאַמענהאַנג מיט דער נסיעה. דאָס איז דאָס ערשטע מאָל אין מיין לעבן — און איך האָף אַז איך וועל עס מער ניט דאַרפן טאָן — וואָס איך מוז אומקערן אַזאַ טשעק. אָבער עס זיך זעלבסטפאַרשטענדלעך, אַז איך טאָר ניט האָבן קיין שייכות צו אַן ענין וואָס איז פאַרבונדן מיט חילול שבת בפרהסיא, און בפרט אַז מ'וויל אַז די צדקה זאָל צוהעלפן אין דעם חילול שבת ר\"ל. דערפאַר ווערט דער טשעק דאָ אומגעקערט. איך וויל האָפן אַז איר וועט אָננעמען מיינע ווערטער, אין איינקלאַנג מיט היינטיגער סדרה — את שבתותי תשמורו גו' אני ה'.\n<span data-k=\"q\">(ממכתב כ\"ה אייר, תשכ\"ד)</span>\n<hr>"],[1301490322,"<h3>בחוקותי</h3>\n... לכתבו אודות קיום המצות: קיום המצות זהו (גם) הדרך לקבלת ברכות השם בכל וכנאמר: אם בחוקותי תלכו ואת מצותי תשמרו גו' ואם לא תשמעו לי גו' (ראה פרשה בחוקותי בארוכה),\nאלא שהשם הוא ארך אפים ומחכה בהעונש ר\"ל, אבל מיהו \"החכם\" שיעבור עברה ח\"ו מפני שהעונש ר\"ל — יבוא רק לאחרי זמן?!. . .\n<span data-k=\"q\">(ממכתב ט\"ו כסלו תשמ\"ז) </span>\n<hr>"],[1301490323,"<h3>פרקי אבות — פ\"ו</h3>\n... שואל לפירוש הענין דהלומד מרבו אפילו אות אחת, מהו ענין לימוד זה.\nוהנה בכמה מקומות בש\"ס מצינו שאלות ומענות כהנ\"ל, ולדוגמא, שבת ע\"ז סוף ע\"א וריש ע\"ב, כן י\"ל שהוא ע\"ד השאלה, בשבת ק\"ד ע\"א, כן בקדושין ל' סוף ע\"א, בעי רב יוסף וא\"ו וכו', ב\"מ פ\"ז ע\"א בסופו — קטנית או וקטנית וכמה כהנה. . .\n<span data-k=\"q\">(ממכתב כ\"ג כסלו, תשכ\"א)</span>"],[1301490324,"<h3>שיחת ש\"פ בחוקותי, כ\"ב אייר, תשמ\"ו</h3>\nא. מהענינים העיקריים בימי ספירת העומר הוא — אהבת ישראל:\nא) הסיבה להנהגה המיוחדת לימי ספה\"ע היא — האבילות על תלמידי ר\"ע \"שלא נהגו כבוד זה לזה\"<sup data-n=\"1861\">1</sup>, כלומר, חסרון בענין דאהבת ישראל, ולכן, ב­ימים אלו יש צורך להוסיף ולהרבות עוד יותר באהבת ישראל, ובפרט על יסוד הוראת רבי עקיבא שהציווי \"ו­אהבת לרעך כמוך\"<sup data-n=\"1862\">2</sup> הוא \"כלל גדול ב­תורה\"<sup data-n=\"1863\">3</sup>.\nב) ימי ספה\"ע הם הכנה למתן­תורה<sup data-n=\"1864\">4</sup>. ולכן, כשם שההכנה למ\"ת בפעם הרא­שונה היתה עי\"ז ש\"ויחן שם ישראל\"<sup data-n=\"1865\">5</sup>, \"ויחן\" לשון יחיד, \"כאיש אחד בלב אחד\"<sup data-n=\"1866\">6</sup>, כדאיתא במדרש<sup data-n=\"1867\">7</sup> \"אמר הקב\"ה הואיל ושנאו ישראל את המחלוקת ואהבו את השלום ונעשו חני' אחת, הרי השעה שאתן להם את תורתי\" — הרי מובן, שגם ההכנה ל\"זמן מתן תורתנו\" בכל שנה ושנה היא ע\"י ההוספה באהבת ישראל ואחדות ישראל, \"כאיש אחד בלב אחד\".\nג) ויש להוסיף בזה — ע\"ד הרמז<sup data-n=\"1868\">8</sup> — שהענין ד\"שבע שבתות תמימות תהיינה\"<sup data-n=\"1869\">9</sup> מורה על השלימות (\"תמימות\") דכל ז' הסוגים שבנשמות ישראל, כידוע<sup data-n=\"1870\">10</sup> ש­\"כללות נש\"י נקרא מנורה ויש בה ז' נרות שהם ז' מדרגות בעבודת ה'\", ז' מדות, שכל א' כלולה מז' (\"שבע שב­תות\"), כלומר, שמציאותו של כל א' מ­ישראל נוגעת לשלימות המציאות ד­כללות עם ישראל (כשם שכל יום מימי הספירה נוגע לשלימות ספה\"ע<sup data-n=\"1871\">11</sup>), ובצי­רוף כולם יחד — אהבת ישראל ואחדות ישראל — אזי נעשה הענין ד\"שבע שבתות תמימות תהיינה\", שלימות מציאו­תם של כל וכלל ישראל — \"תמימות\", ובכל תוקף המציאות — \"תהיינה\", \"בהווייתה תהא\"<sup data-n=\"1872\">12</sup>, אשר, זוהי ההכנה המתאימה לקבלת התורה.\nב. ענין הנ\"ל מודגש ביותר בשבת זו — השבת שלאחרי ל\"ג בעומר (העילוי והשלימות — \"ויכולו\"<sup data-n=\"1873\">13</sup> — גם דכל עניני ל\"ג בעומר), ובפרשת השבוע — פ' בחוקותי:",[["1861","1","יבמות סב, ב. שו\"ע אדה\"ז או\"ח הל' פסח רסתצ\"ג."],["1862","2","קדושים יט, יח."],["1863","3","תו\"כ ופרש\"י עה\"פ."],["1864","4","ראה מו\"נ ח\"ג פמ\"ג. חינוך מצוה שו. מדרש (\"הגדה\") הובא בעיטור (סוף הלכות מצה ומרור), ונעתק בשו\"ת הרשב\"א (ח\"א סרפ\"ד). ר\"ן סוף פסחים. ועוד."],["1865","5","יתרו יט, ב."],["1866","6","פרש\"י עה\"פ. וראה מכילתא שם."],["1867","7","ויק\"ר פ\"ט, ט. דא\"ז פ' השלום. וראה גם תנחומא באבער יתרו ט."],["1868","8","להעיר אשר בקשת רבש\"ע כו' שלאחרי כל ספירה היא בבירור וזיכוך המדות בפרטיות, מתחיל מחסד שבחסד. וראה לקמן בפנים. — ועיין פע\"ח שער ספה\"ע. סידור האריז\"ל. ועוד."],["1869","9","אמור כג, טו."],["1870","10","לקו\"ת ר\"פ בהעלותך. ועוד."],["1871","11","ראה שו\"ע אדה\"ז שם סתפ\"ט סכ\"ג. וראה לקו\"ש ח\"א ע' 270 ואילך. ועוד."],["1872","12","סוכה מ, ב. קידושין נח, א. פרש\"י עה\"ת בהר כה, יב. ועוד."],["1873","13","בראשית ב, א. וראה לקו\"ת בהר מא, א. ובכ\"מ."]]],[1301490325,"בנוגע לטעם הא', אודות תלמידי ר\"ע — הרי ל\"ג בעומר הוא היום שבו \"פסקו מלמות\"<sup data-n=\"1874\">14</sup>, כלומר, מל\"ג בעומר ואילך התחילה תקופה חדשה אצל תלמידי ר\"ע — הנהגה של אהבת ישראל בתכלית השלימות.\nועוד ענין בזה:\nל\"ג בעומר הוא יום ההילולא של רשב\"י — תלמידו של ר\"ע (מהתלמידים ש\"העמידו תורה\" לאחרי ל\"ג בעומר)<sup data-n=\"1875\">15</sup>, אשר, מדותיו \"תרומות מתרומות מדותיו של ר\"ע\"<sup data-n=\"1876\">16</sup>, כולל ובמיוחד — מדת אהבת ישראל של ר\"ע (\"כלל גדול בתורה\") ש­היתה אצלו בהדגשה יתירה<sup data-n=\"1877\">17</sup>, כפי ש­מצינו שבצאתו מן המערה (לאחרי שנת­עלה בתורה בתכלית העילוי<sup data-n=\"1878\">18</sup>) התעסק לכל לראש באהבת ישראל — \"אמר איכא מילתא דבעי לתקוני כו'\"<sup data-n=\"1879\">19</sup>, היינו, שהשתדל בטובתן של כהנים שלא יצטערו בטורח הדרך<sup data-n=\"1880\">20</sup>.\nולא עוד, אלא שהשתדל ודאג לטוב­תם של אלו שהיו במצב ירוד כו' — \"יכול אני לפטור את כל העולם כולו מן הדין\"<sup data-n=\"1881\">21</sup>.\nולהעיר גם מסיפור הזהר<sup data-n=\"1882\">22</sup> \"זמנא חדא הוה צריכא עלמא למטרא, אתו ל­קמי' דר\"ש. . פתח ואמר שיר<sup data-n=\"1883\">23</sup> המעלות הנה מה טוב ומה נעים שבת אחים גם יחד\", ועי\"ז ירדו גשמים — אשר, נוסף על המבואר בדרושי חסידות<sup data-n=\"1884\">24</sup> הקשר והשייכות דירידת גשמים לפסוק זה, יש לומר (בדרך אפשר, כיון שעי\"ז יתוסף באהבת ישראל עוד יותר), שבכך רמז רשב\"י שהענין ד\"שבת אחים גם יחד\", אהבת ישראל ואחדות ישראל<sup data-n=\"1885\">25</sup>, הוא ה­",[["1874","14","מאירי יבמות שם בשם הגאונים. שו\"ע אדה\"ז שם סתצ\"ג ס\"ה."],["1875","15","יבמות שם."],["1876","16","גיטין סז, א."],["1877","17","ראה גם המלוקט (מכו\"כ מקומות בזהר וכו') בס' כחו דרשב\"י (להריא\"ז מרגליות) מערכת ב' פי\"ד­פט\"ז."],["1878","18","ראה שבת לג, סע\"ב: \"אשריך שראיתני בכך (במצב שלאחרי צער המערה), שאילמלא ראיתני בכך לא מצאת בי כך, דמעיקרא כי הוה מקשי רשב\"י קושיא, הוה מפרק לי' ר' פנחס בן יאיר תריסר פירוקי, לסוף, כי הוה מקשי רפב\"י קושיא, הוה מפרק לי' רשב\"י כ\"ד פירוקי\" — עילוי שלא­בערך לגמרי, ממקשה קושיות למתרץ תירו­צים, ע\"ד ובדוגמת הלימוד דפנימיות התורה ש\"לית תמן לא קושיא כו'\" (זח\"ג קכד, ב — ברע\"מ. הובא ונת' באגה\"ק רסכ\"ו), ובזה גופא — כ\"ד פירוקי על קושיות של רפב\"י שהי' משיב י\"ב פירוקי על קושיות דרשב\"י!"],["1879","19","שבת שם."],["1880","20","ויש לומר — ע\"ד הרמז: \"כהנים\" — קאי על כאו\"א מישראל, \"ואתם תהיו לי ממלכת כהנים\" (יתרו יט, ו), ו\"דרך\" — קאי על הדרך דעבודת ה', שבה צריך להיות ענין ההליכה — בב' אופני ההליכה מלמעלמ\"ט ומלמטלמ\"ע (תורה ותפלה), כמ\"ש בפרשת השבוע (כו, יב) \"והתהלכתי בתוככם\", ב' אופני הליכה (לקו\"ת ראה כו, א. אמ\"ב שער הק\"ש פפ\"ז ואילך. ובכ\"מ). ועבודתו של רשב\"י לתקן את הדרך — הוראת ותיקון הדרך לכאו\"א מישראל בעבודתו לקונו."],["1881","21","סוכה מה, ב. וראה ירושלמי ברכות פ\"ט ה\"ב. ב\"ר פל\"ה, ב. ועוד."],["1882","22","ח\"ג נט, ריש ע\"ב."],["1883","23","תהלים קלג, א."],["1884","24","מאמרי אדה\"ז אתהלך לאזניא (ע' רי ואילך). אוה\"ת אחרי (כרך א) ע' רנד ואילך. סה\"מ תרכ\"ז ע' רסז ואילך. ועוד."],["1885","25","ראה גם המשך דברי הרשב\"י בזהר: \"הנה מה טוב ומה נעים וגו', אלין אינון חברייא בשעתא דאינון יתבין כחדא ולא מתפרשן דא מן דא וכו'\". וראה מק\"מ בשם הרמ\"ז לזח\"ג קעט, ב, בביאור הטעם שנקראו \"חברייא\", משום האהבה והאחדות ביניהם. וראה ס' כחו דרשב\"י שם רפי\"ד."]]],[1301490326,"\"דרך\" וה\"כלי\" להמשכת כל הברכות, החל מהברכה דגשמים, ובלשון הכתוב דפרשתנו<sup data-n=\"1886\">26</sup>: \"ונתתי גשמיכם בעתם\", הכוללת את כל הברכות — כפירוש ה­רמב\"ן ש\"הקדים דבר הגשמים כי בבואם בעתם. . יהי' זה סיבת בריאות לגופים והפירות כולם ירבו ויתברכו בהן, כאשר יאמר ונתנה הארץ יבולה ועץ ה­שדה יתן פריו. . היא גדולה שב­ברכות\", וכתורת הבעש\"ט<sup data-n=\"1887\">27</sup> ש\"גשמיכם\" הוא מלשון גשמיות, היינו, המשכת ה­ברכה (גם) בכל הענינים הגשמיים,\nהיינו, שה\"כלי\" לכל הברכות הוא — \"שבת אחים גם יחד\", אהבת ישראל ואחדות ישראל<sup data-n=\"1888\">28</sup>.\nובנוגע לטעם הב', אודות ההכנה ל­מ\"ת בימי ספה\"ע — הרי עיקר העבודה דספה\"ע הוא בירור המדות דנה\"ב (ז' מדות הכלולים מז', מ\"ט יום) שעי\"ז ואז יוכל להיות הגילוי דמתן­תורה<sup data-n=\"1889\">29</sup>, ומכיון שעיקר המדות הם ה' מדות הראשונות, נמצא, שבל\"ג בעומר, שהוא בחי' הוד שבהוד, מסתיים עיקר בנין גופא דז\"א<sup data-n=\"1890\">30</sup>, ולכן, מודגשת יותר ההכנה למ\"ת — \"כאיש אחד בלב אחד\".\nובנוגע לטעם הג' — להעיר מ­מארז\"ל<sup data-n=\"1891\">31</sup> \"א\"ר שמעון בן יוחאי מניין אתה אומר אילו היו ישראל חסרים אפילו אדם א' לא היתה השכינה נגלית עליהן, דכתיב<sup data-n=\"1892\">32</sup> כי ביום השלישי ירד ה' לעיני כל העם\", היינו, שרשב\"י מדגיש שהענין דמ\"ת תלוי במציאותו דכל או\"א מישראל.\nונוסף לזה, מודגשת ההכנה למ\"ת בשבת זו גם מצד פרשת השבוע, פ' בחו­קותי — שהרי \"עזרא תיקן להם לישראל שיהיו קורין קללות<sup data-n=\"1893\">33</sup> שבתורת כהנים קודם עצרת\"<sup data-n=\"1894\">34</sup> (ומה שקורין פ' במדבר לפני עצרת, הרי זה \"כדי שלא להסמיך הקללות שבבחוקותי לעצרת\"<sup data-n=\"1895\">35</sup>), שמזה מובן שבשבת פ' בחוקותי מודגשת יותר ההכנה למ\"ת, \"כאיש אחד בלב אחד\".\nועפ\"ז מובן שבימים אלו — הימים שלאחרי ל\"ג בעומר, וככל שהולכים ו­מתקרבים יותר ל\"זמן מתן תורתנו\" — יש",[["1886","26","כו, ד."],["1887","27","ראה כש\"ט סרנ\"ו (לה, א). וראה גם \"היום יום\" — כ\"ח תשרי."],["1888","28","ועד\"ז בנוגע לכל הברכות המנויות בפרשה עד לברכה העיקרית והפנימית — גאולה האמיתית והשלימה [כמרומז בברכה ד\"ונתתי שלום בארץ\" (כו, ו), שהרי השלימות ד\"פדה בשלום נפשי\" תהי' בגאולה העתידה (ראה ד\"ה פדה בשלום לאדהאמ\"צ (שערי תשובה ח\"א) פי\"א), ועד לסיום הברכות: יציאה מהגלות באופן ד\"ואולך אתכם קוממיות\" (שם, יג)] — שכל זה נפעל ע\"י אהבת ישראל ואחדות ישראל (כדלקמן ס\"ג)."],["1889","29","ראה לקו\"ת אמור לה, ב ואילך. במדבר י, א ואילך. סידור שער חג השבועות. ובכ\"מ."],["1890","30","סידור שער הל\"ג בעומר (דש, א)."],["1891","31","דב\"ר פ\"ז, ח. ועוד."],["1892","32","יתרו יט, יא."],["1893","33","להעיר מלקו\"ת פרשתנו (מח, סע\"א ואילך): \"לפי האמת אינם רק ברכות\", ואדרבה — ברכות נעלות יותר, להיותן מבחי' סתים כו', \"ברכות אלו הם ע\"ד מ\"ש בגמ' פ\"ק דמ\"ק ד\"ט ע\"ב הנך כולהו ברכתא נינהו\" — דברי רשב\"י לר\"א בנו. והיינו, שע\"י אהבת ישראל ואחדות ישראל (מעיקרי עניניו של רשב\"י) ממשיכים לא רק כל הברכות הגלויות (כנ\"ל בפנים), אלא עוד זאת, שגם הענינים שהיו בעבר בגילוי היפך הברכה — נהפכים לברכה גם בגילוי, ואדרבה — ברכה נעלית יותר."],["1894","34","מגילה לא, סע\"ב. רמב\"ם הל' תפלה פי\"ג ה\"ב."],["1895","35","תוס' מגילה שם."]]],[1301490327,"צורך להוסיף ביתר שאת וביתר עוז בכל הענינים דאהבת ישראל ואחדות ישראל.\nג. ועוד ענין הכי עיקרי בזה — ב­נוגע לדורנו זה, דרא דעקבתא דמשיחא, סוף זמן הגלות, ובהקדמה:\nמעניניו העיקריים של רשב\"י (בעל ההילולא דל\"ג בעומר, ששלימותו בשבת זו) הוא — ספר הזהר, \"חיבורא דילך\", אשר, \"בהאי חיבורא דילך דאיהו ספר הזהר. . יפקון בי' מן גלותא ברחמים\"<sup data-n=\"1896\">36</sup>, היינו, שענינו של רשב\"י לפעול את גאולתם של כאו\"א מישראל וכלל ישר­אל, ביחד עם גאולת השכינה, כדברי רשב\"י<sup data-n=\"1897\">37</sup>: \"בכל מקום שגלו (ישראל) שכינה עמהן. . ואף כשהן עתידים ל­הגאל שכינה עמהן\".\nוהנה, מכיון שסיבת הגלות היא היפך הענין דאהבת ישראל (חנם)<sup data-n=\"1898\">38</sup>, הרי מובן, שיש צורך לבטל את סיבת הגלות, ע\"י ההוספה באהבת ישראל עד לאהבת חנם, ובהבטל הסיבה, בטל בדרך ממילא גם המסובב — הגלות.\nויש להוסיף, שכאשר הנהגתם של ישראל בפועל היא באופן ד\"ואהבת לרעך כמוך\", אזי בודאי מתגלה בפועל גם האהבה ד\"רעך\" — \"רעך ורע אביך אל תעזוב, זה הקב\"ה\"<sup data-n=\"1899\">39</sup> — לכאו\"א מ­ישראל,\nכדברי רשב\"י<sup data-n=\"1897\">37</sup> \"כמה חביבין ישראל לפני הקב\"ה\"<sup data-n=\"1901\">40</sup>, וכדאיתא בזהר<sup data-n=\"1902\">41</sup> — \"חיבורא דילך\" — (מאמר הזהר שאומ­רים ב\"תיקון ליל שבועות\") \"חדי ר\"ש ואמר. . אנן בחביבותא תליא מילתא. . אהבתי<sup data-n=\"1903\">42</sup> אתכם אמר ה'\" —\nוכאשר אהבתו של הקב\"ה לישראל היא בהתגלות — הרי בודאי ובודאי ש­מוציאם מהגלות (\"ושב ה' אלקיך את שבותך\"<sup data-n=\"1904\">43</sup>) תיכף ומיד, \"לא עיכבן אפילו כהרף עין\"<sup data-n=\"1905\">44</sup>,\nוכהרמז שע\"י ההמשכה וההתגלות ד\"אלופו של עולם\" (אל\"ף) ב\"גולה\", אזי נעשה מ\"גולה\" — \"גאולה\"<sup data-n=\"1906\">45</sup>.\nד. והנה, הענין דאהבת ישראל ואח­דות ישראל מתגלה ומתבטא — לכל לראש — כאשר רבים מישראל מתאס­פים יחד במקום אחד, \"כאיש אחד בלב אחד\"<sup data-n=\"1907\">46</sup>, ולא עוד, אלא שתכליתה ו­",[["1896","36","זח\"ג קכד, ב — ברע\"מ. הובא ונתבאר באגה\"ק רסכ\"ו."],["1897","37","מגילה כט, א."],["1898","38","יומא ט, ב. וראה גיטין נה, סע\"א ואילך."],["1899","39","פרש\"י שבת לא, א (ד\"ה דעלך). וראה שמו\"ר רפכ\"ז. זח\"ב נה, ריש ע\"ב. ועוד."],["1897","37","מגילה כט, א."],["1901","40","אפילו בזמן הגלות — \"בכל מקום שגלו שכינה עמהן\". ולהעיר מזהר סוף פרשתנו: \"ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא געלתים לכלתם (פרשתנו כו, מד). . מלה חדתא ד­אמר רבי אלעזר. . לכלתם כתיב, חסר וי\"ו (מלשון כלה). . בגינה (בגלל ה\"כלה\"). . לבר נש דרחים אתתא והות דיירא בשוקא דבורסקי כו'\", וסיום הענין: \"בן יכבד אב כגון ר' אלעזר. . השתא אסגי שבחא דר\"ש כו'\" (וראה לקוטי לוי\"צ פרשתנו ס\"ע שלו ואילך)."],["1902","41","ח\"ג קכח, א. וראה לקוטי לוי\"צ הערות לזהר שם (ס\"ע שנה ואילך)."],["1903","42","מלאכי א, ב."],["1904","43","נצבים ל, ג."],["1905","44","מכילתא ופרש\"י בא יב, מא. מכילתא שם, מב."],["1906","45","ראה ויק\"ר ספל\"ב. לקו\"ת בהעלותך לה, ג. ובכ\"מ."],["1907","46","להעיר מדיוק הלשון \"כאיש אחד (ואח\"כ) בלב אחד\" — שלכל לראש צריך להיות אסיפת כולם במקום אחד, \"כאיש אחד\", גם כאשר נראה, לכאורה, שאין זו אלא פעולה חיצונית במעשה בפועל בלבד — שהרי \"המעשה הוא העיקר\";\nוביחד עם זה, בודאי שסוכ\"ס יבוא הדבר גם ברגש פנימי בלב — \"בלב אחד\", כהכלל הידוע שאחרי הפעולות נמשכים הלבבות (ראה חינוך מצוה טז), ובפרט \"רוב המעשה\" (אבות פ\"ג מט\"ו. פיה\"מ להרמב\"ם שם. וראה אגה\"ק סכ\"א)."]]],[1301490328,"מטרתה של האסיפה היא — כדי ש\"איש את רעהו יעזורו\"<sup data-n=\"1908\">47</sup> להתעורר ולהתחזק בכל הפעולות הטובות, ובמיוחד — בהכלל גדול דאהבת ישראל ואחדות ישראל.\nובפרט כאשר מקשרים אסיפה זו עם סעודה כפשוטה, כולל ובמיוחד אמירת \"לחיים\" על היין<sup data-n=\"1909\">48</sup> — דבר המוסיף עוד יותר בתנועת הקירוב, \"גדולה לגימה שמקרבת\"<sup data-n=\"1910\">49</sup>.\nוכידוע<sup data-n=\"1911\">50</sup> פתגם אדמו\"ר הזקן אודות גודל מעלתה של התוועדות — \"פתקא אשר משמי שמיא נחיתא כו'\" — כמשל האב הרואה את \"התנהגותם הטובה של בניו באהבה באחוה בשלום ובריעות, איש את רצון רעהו ימלא, וכל אחד דואג לטובת חבירו כלטובת עצמו כו', אזי האב נתמלא עונג ונח\"ר מהנהגת בניו, ומפליא לעשות לקיים משאלותיהם כו'\" (כאמור לעיל (ס\"ב) שע\"י \"שבת אחים גם יחד\" נמשכים כל עניני ברכה).\nה. אמנם, מכיון שבימי הספירה ישנם הגבלות בנוגע לעריכת סעודה של שמחה, ובזה גופא ישנם חילוקי מנהגים בנוגע לזמן שלאחרי ל\"ג בעומר כו'<sup data-n=\"1912\">51</sup> — יש לבחור בזמן המתאים לכל הדעות, כדי שכאו\"א מישראל, מכל החוגים כו', איש איש ע\"פ שיטת ומנהג אבותיו, יוכל להשתתף בהתוועדות זו.\nולכן, הרי הזמן המתאים לכך הוא — יום השבת, אשר, לכל הדעות אין כל חשש ופקפוק בדבר, שהרי יום השבת אין \"עצב עמה\"<sup data-n=\"1913\">52</sup>, ואדרבה — \"ביום שמחתכם אלו השבתות\"<sup data-n=\"1914\">53</sup>.\nוהדגשה יתירה בשבת הבעל\"ט — שבת מברכים חודש סיון, \"חודש ה­שלישי\", ובקביעות שנה זו — ערב ר\"ח סיון, ופרשת השבוע — פ' במדבר:\nא) שבת מברכים (בציבור<sup data-n=\"1915\">54</sup> ואסיפה) \"חודש השלישי\": \"חודש השלישי\" — מורה על ענין השלום והאחדות, כידוע<sup data-n=\"1916\">55</sup> שהמעלה המיוחדת דמספר שלוש היא — חיבור והתכללות ב' ענינים שיכול להיות ניגוד ביניהם. וזהו גם הקשר עם כללות הענין דמ\"ת — \"אוריאן תליתאי כו' בירחא תליתאי\"<sup data-n=\"1917\">56</sup> — שהרי \"כל",[["1908","47","ישעי' מא, ו."],["1909","48","להעיר מהקשר ד\"יין\" לדוד מלכא משיחא — \"כסא דדוד לעלמא דאתי מאתן ועשרין וחד לוגא מחזיק, שנאמר (תהלים כג, ה) כוסי רוי', רוי' בגימטריא הכי הוי\" (יומא עו, א) — כידוע (לקו\"ת שה\"ש ב, ד. אמרי בינה שער הק\"ש פנ\"ד ואילך. ובכ\"מ) ש\"יין\" רומז לפנימיות התורה, \"נכנס יין יצא סוד\" (עירובין סה, סע\"א. זח\"ג לט, א. ועוד), ענינו וחידושו של דוד מלכא משיחא (נתבאר בארוכה בשיחות אחש\"פ שנה זו)."],["1910","49","ראה סנהדרין קג, סע\"ב ואילך."],["1911","50","קובץ מכתבים לתהלים (אוהל יוסף יצחק — הוצאת קה\"ת — ע' 199). אג\"ק אדמו\"ר מוהריי\"צ ח\"ג ע' תיג. ועוד."],["1912","51","שו\"ע אדה\"ז שם סתצ\"ג ס\"ה­ז."],["1913","52","משלי י, כב. ירושלמי ברכות פ\"ב סה\"ז. הובא בתוד\"ה מאן דאמר — מו\"ק כג, ב."],["1914","53","ספרי בהעלותך י, י."],["1915","54","שלכן קבעו ברכה זו בשבת דוקא (שבלי הלקט סק\"ע)."],["1916","55","ראה לקו\"ש חכ\"א ע' 111 ואילך. וש\"נ."],["1917","56","שבת פח, א. וראה פי' ר\"נ גאון שם."]]],[1301490329,"התורה ניתנה לעשות שלום בעולם\"<sup data-n=\"1918\">57</sup>. ולכן, בשבת מברכים חודש השלישי — שממנו נמשכת ברכה לכל ימי \"חודש השלישי\" — מודגש ביותר ענין השלום והאחדות.\nב) ערב ר\"ח ד\"חודש השלישי\": הענין דר\"ח — התחלתו בערב ר\"ח (יום השבת) לאחרי חצות, שלכן, אין אומרים \"צד­קתך צדק\" במנחת שבת<sup data-n=\"1919\">58</sup>, ולא עוד, אלא מכיון שלפעמים יכולים להתפלל \"ער­בית של מוצאי שבת בשבת\"<sup data-n=\"1920\">59</sup>, שאז מתפללים ביום השבת תפלת ר\"ח — \"יעלה ויבוא כו' זכרוננו כו' וזכרון כל עמך בית ישראל\". ונמצא, שביום השבת הבא, ערב ר\"ח סיון, ישנו כבר הענין ד­ר\"ח סיון, שאז הי' ענין האחדות (כהכנה למ\"ת) בפועל ממש — \"בחודש השלישי גו' ביום הזה (ר\"ח<sup data-n=\"1921\">60</sup>) באו. . ויחן<sup data-n=\"1922\">61</sup> שם ישראל\"<sup data-n=\"1923\">62</sup>, \"כאיש אחד בלב אחד\".\nג) פרשת השבוע, פ' במדבר: התוכן דפ' במדבר (\"לעולם קורין פרשת במד­בר סיני קודם עצרת\"<sup data-n=\"1924\">63</sup>) הוא — מנין בנ\"י, היינו, השלימות דכל בנ\"י באופן של אחדות ישראל — שהרי ה\"מנין\" הוא באופן שכל ישראל שבמנין שוים, הגדול שבגדולים אינו נחשב יותר מא', והקטן שבקטנים אינו נחשב פחות מאחד<sup data-n=\"1925\">64</sup>,\nוהמנין סיבתו אהבת ישראל (של הקב\"ה — סיבת אהבת ישראל זל\"ז — \"אוהב מה שהאהוב אוהב\"<sup data-n=\"1926\">65</sup>) — \"מתוך חיבתן לפניו מונה אותם כו'\"<sup data-n=\"1927\">66</sup>.\nומזה מובן שיום השבת הבעל\"ט, ש\"ק פ' במדבר, מברכים החודש וער\"ח סיון, הוא הזמן הכי מתאים להדגשת אחדותם של ישראל.\nו. לאור כל האמור לעיל — באה ההצעה והבקשה דלקמן, בקשה נפשית:\nביום השבת הבעל\"ט, ש\"ק פ' במדבר, מבה\"ח וער\"ח סיון, בעלות המנחה<sup data-n=\"1928\">67</sup> (שאז מתחיל כבר ענין האחדות דר\"ח סיון (כנ\"ל ס\"ה)) — יתאספו בכל מקום ומקום רבים מישראל, אנשים ונשים וטף, \"בנערינו ובזקנינו גו' בבנינו ובבנותי­נו\"<sup data-n=\"1929\">68</sup>, \"שבת אחים גם יחד\", להתוועדות רעים, עד לסעודה כפשוטה<sup data-n=\"1930\">69</sup> (\"גדולה",[["1918","57","רמב\"ם הל' חנוכה בסופן. וראה לקו\"ש ח\"ח ע' 349 ואילך. וש\"נ."],["1919","58","שו\"ע אדה\"ז או\"ח הל' שבת סו\"ס רצב."],["1920","59","רמב\"ם הל' תפלה פ\"ג ה\"ז. שו\"ע אדה\"ז שם סרצ\"ג ס\"ב."],["1921","60","שבת פו, ב. פרש\"י עה\"פ."],["1922","61","ל' יחיד — תיכף ל\"באו\" ל' רבים."],["1923","62","יתרו יט, א­ב."],["1924","63","טושו\"ע חאו\"ח סתכ\"ח ס\"ד. רמב\"ם שם פי\"ג ה\"ב. — ולא הודגש שהטעם הוא רק כדי להפסיק בין קללות שבתו\"כ (כבתוס' מגילה שם), מכיון שגם התוכן דפ' במדבר גופא (מנין בנ\"י) שייך ל\"עצרת\", ובלשון הלבוש שם: \"ולעולם קורין פ' במדבר שיש בה מניינן של ישראל קודם שבועות\", ועד\"ז בחדא\"ג מהרש\"א מגילה שם: \"פרשת במדבר קודם עצרת כו' כדי שישובו ישראל למספרם הנזכר בפרשת במדבר\" (ראה לקו\"ש חי\"ח ע' 18. וש\"נ)."],["1925","64","ראה לקו\"ש ח\"ד ע' 1021 ואילך, שההכנה דמנין בנ\"י (פ' במדבר) לחגה\"ש היא דוגמת ההכנה דמנין הימים בספה\"ע. וראה לעיל סוס\"א ש\"שבע שבתות תמימות\" רומז לז' הסוגים שבישראל."],["1926","65","\"התמים\" ח\"ד ע' מה. אג\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' תכה."],["1927","66","פרש\"י ר\"פ במדבר."],["1928","67","להעיר מהשייכות דתפלת מנחה לגאולה — שבעלות המנחה נענה אליהו הנביא (ברכות ו, ב), מבשר הגאולה. ועאכו\"כ מנחת שבת, \"עת רצון\" — שלימות התענוג דשבת (\"רעוא דרעוין\") — מעין ודוגמת \"יום שכולו שבת ומנוחה לחיי העולמים\" (המשך תרס\"ו ע' תקמב)."],["1929","68","ל' הכתוב — בא י, ט."],["1930","69","להעיר שבסעודת שבת כשלעצמה מודגשת אחדותם של ישראל — שגם עם­הארץ, אשר, בימי החול פירותיו \"דמאי\", אימת שבת עליו ואינו משקר, ולכן, יכולים הכל לאכול משולחנו וסעודתו (ירו­שלמי דמאי רפ\"ד. רמב\"ם הל' מעשר רפי\"ב)."]]],[1301490330,"לגימה שמקרבת\") — אנשים לחוד ונשים לחוד (כמובן וגם פשוט),\nשבה ידברו דברי­תורה בכלל, וב­מיוחד — בעניני אהבת ישראל ואחדות ישראל<sup data-n=\"1931\">70</sup>,\n— החל מהמפורש בתשב\"כ: \"ואהבת לרעך כמוך\", וכן בתושבע\"פ: \"רבי עקיבא אומר זה כלל גדול בתורה\", ויתירה מזה: \"זו היא כל התורה כולה ו­אידך פירושא הוא\"<sup data-n=\"1932\">71</sup>, וכן פרטי הדברים בספר \"משנה תורה\" להרמב\"ם<sup data-n=\"1933\">72</sup>, ספר \"הלכות הלכות\"<sup data-n=\"1934\">73</sup>, הלכה למעשה, עד ל­ביאור רבינו הזקן בספר התניא<sup data-n=\"1935\">74</sup> בגודל מעלת והפלאת הענין דאהבת ישראל, ועד\"ז בספריהם של כו\"כ מגדולי ישראל שנתקבלו בכל תפוצות ישראל —\nכולל — ההדגשה שבדבר, שההוספה באהבת ישראל ואחדות ישראל מבטלת את סיבת הגלות, ובדרך ממילא מתבטל גם (המסובב) הגלות.\n[ולהעיר: בנוגע לתוכן הדברים או­דות אהבת ישראל ואחדות ישראל — הרי \"אין כל השכלים והדעות שוות, ואין שכל אדם זה מתפעל ומתעורר ממה שמתפעל שכל חבירו\"<sup data-n=\"1936\">75</sup>, יש כאלו ש­יתפעלו יותר מביאור בנגלה דתורה, וישנם כאלו שיתפעלו יותר מביאור בפנימיות התורה, ולכן, יש למצוא את הביאורים והאותיות המתאימים לכל מקום וחוג לפי ענינו; אמנם, לכל לראש יש להדגיש את תוכן ונקודת הענין, באופן השייך לכאו\"א מישראל, גם למי שרוצה ללמוד \"כל התורה כולה (של אהבת ישראל) על רגל אחת\" — כדברי הלל<sup data-n=\"1937\">76</sup> (כמענה לנכרי שאמר לו \"גיירני על מנת שתלמדני כל התורה כולה כשאני עומד על רגל אחת\"): \"דעלך<sup data-n=\"1932\">71</sup> סני לחברך לא תעביד (\"ואהבת לרעך כמוך\") זו היא כל התורה כולה, ואידך פירושא הוא\"!].\nועוד ועיקר — ש\"איש את רעהו יעזורו\", לעודד איש את רעהו (ואשה את רעותה) להוסיף ביתר שאת וביתר עוז בכל עניני אהבת ישראל ואחדות ישראל.\nובמקומות אלו, אשר, מסיבות שונות קשה לעשות כל זה ביום השבת — יעשו זאת בימי החול, בר\"ח סיון וכיו\"ב (באופן המותר כו').\nז. בודאי יפרסמו את הדברים בכל מקום ומקום,",[["1931","70","שהרי אע\"פ שבכל עניני התורה מודגש ענין האחדות — \"תורה אחת\" שניתנה מ\"ה' אחד\" ל\"גוי אחד בארץ\" — מ\"מ, מודגש הדבר ביותר בענינים שתוכנם הו\"ע האחדות, ע\"ד \"כל העוסק בתורת כו' כאילו הקריב כו'\" (מנחות בסופה). ולהעיר גם מסיפור הזהר (לעיל ס\"ב) שהפעולה דירידת גשמים (הכולל כל הברכות) היתה ע\"י אמירת תורה על הפסוק \"שבת אחים גם יחד\" דוקא — פסוק שתוכנו הו\"ע היחוד והאחדות."],["1932","71","שבת לא, א."],["1933","72","הל' דעות פ\"ו ה\"ג. וראה הל' אבל רפי\"ד."],["1934","73","ל' הרמב\"ם בהקדמתו לספר הי\"ד."],["1935","74","פרק לב. וראה סהמ\"צ להצ\"צ מצות אהבת ישראל. וראה קונטרס אהבת ישראל. וש\"נ."],["1936","75","לשון אדה\"ז בהקדמתו לספר התניא."],["1937","76","להעיר ש\"הלכה כב\"ה (ועאכו\"כ הלל עצמו). . מפני שנוחין ועלובין היו, ושונין דבריהן ודברי ב\"ש, ולא עוד אלא שמקדימין דברי ב\"ש לדבריהן\" (עירובין יג, ב) — תכלית השלימות ד\"נהגו כבוד זה לזה\" (גם בנוגע לדברי תורה, תורת אמת)."],["1932","71","שבת לא, א."]]],[1301490331,"[ומובן, שבנידון זה אין הכרח לומר את הדברים \"בשם אומרם\", כי אם, ב­סגנון שיביא תועלת יתירה בקיום הדברים בפועל ממש<sup data-n=\"1939\">77</sup>, ובפרט שאין זה דבר­חידוש, אלא דברים המפורשים בתושב\"כ ובתושבע\"פ, ובמילא, כל מי שיתבונן בדבר — יבוא בעצמו למסקנא האמורה, ויעשה זאת סו\"ס מפני שכך מצווהו שכלו הוא],\nויעסקו בזה ברוב מרץ חיות והת­להבות כו' (ופשיטא — לא באופן ד­\"מצות אנשים מלומדה\"<sup data-n=\"1940\">78</sup>), בהתחשב עם העובדא שזהו ענין נפשי בנוגע דבר מיוחד ובלתי­רגיל כו' (ולכן, גם הדיבור עתה בענין זה הוא בזמן שלא ע\"ד הרגיל — לא בסיומה של ההתוועדות, כרגיל בכגון­דא, אלא בהתחלת וראש ההתוועדות), מפני צורך השעה כו'.\nח. ובנוגע לפועל:\nכדי שהפעולות בענין זה תהיינה בסדר מסודר ובהצלחה רבה — יש צורך להתחיל מבעוד מועד, החל מפירסום הענין בכל מקום ומקום, ועד לארגון פרטי הדברים בפועל ממש בכל מקום ומקום.\nולכן, מעוררים על כך ביום השבת, \"מפקחין על צרכי ציבור בשבת\"<sup data-n=\"1941\">79</sup> — כדי שינצלו את כל ימי השבוע (החל ממוצאי שבת) לעסוק בהכנות הדרושות לכך, באופן ד\"כל יומא ויומא עביד עבידתי'\"<sup data-n=\"1942\">80</sup>,\nכלומר, הגישה הכללית צריכה להיות בדרכי נועם ובדרכי שלום (\"דרכי שבת\"), ובזה גופא — כל יום ויום לפי אופן עבודתו המיוחד, \"דרכי נועם\" מצד מדת החסד (יום ראשון), \"דרכי נועם\" מצד מדת הגבורה (יום שני), וכיו\"ב בכל ששת ימי השבוע,\nעד ליום השבת עצמו, ובפרט בזמן \"דרעוא דרעוין\" שבו — שאז יתאחדו כל המתאספים והמתוועדים די בכל אתר ואתר, \"לאחדים כאחד\"<sup data-n=\"1943\">81</sup>,\nשכן, אע\"פ ש\"זמן כניסת שבת. . הוא בכל מדינה ומדינה לפי זמן הימים והלילות שבה\", ובמילא, ההתוועדויות שיתקיימו בכל מקום ומקום בזמן דמנחת שבת לא יהיו למטה בכדור הארץ באותה שעה ממש — הרי מכיון ש\"עת רצון שלמעלה\" (תוצאה מאחדותם של ישראל) \"הוא למעלה מגדר המקום והזמן\"<sup data-n=\"1944\">82</sup>, נמצא, שכל המתוועדים בכל המקומות יתאחדו לאחדים כאחד ממש.\nט. ועוד נקודה בנוגע להכנות ה­מעשיות — בקשר להוצאה הכספית:\nפעולות אלו, ככל הפעולות, כרוכות בהוצאה כספית. וידוע השאלה [כפי שרגילים להשתמש — ע\"ד הצחות — בלשון חז\"ל<sup data-n=\"1945\">83</sup>] \"כסף מנלן\".. .\nהנה, לכל לראש ישנו המענה ד­",[["1939","77","ראה לקו\"ש ח\"ב ע' 623 הע' 2."],["1940","78","ישעי' כט, יג. וראה תניא פל\"ט. תו\"א ר\"פ וארא. לקו\"ת אחרי כו, ד. ובכ\"מ."],["1941","79","ראה רמב\"ם הל' שבת פכ\"ד ה\"ה. שו\"ע אדה\"ז שם סש\"ו סי\"ב."],["1942","80","זח\"א רה, סע\"א. ח\"ג צד, ריש ע\"ב."],["1943","81","לקו\"ת ר\"פ נצבים. וראה לקו\"ש ח\"ד ע' 1141 ואילך."],["1944","82","שו\"ע אדה\"ז או\"ח הל' השכמת הבוקר ס\"א ס\"ח. וראה תורת חיים (לאדהאמ\"צ) שמות שמט, ב ואילך."],["1945","83","ריש מס' קידושין. — ולהעיר שע\"ד הרמז ה\"ז בנוגע להקב\"ה שאין שייך בו כל תואר ולא מדה וכו' כלל, ולכן התמי' \"כסף מנלן\". — ולהעיר (ע\"ד הנגלה) מרמב\"ם הל' אישות פ\"ג ה\"כ ונו\"כ, ומהחולקים על הרמב\"ם בזה."]]],[1301490332,"\"תורת­אמת\" שהענין ד\"כסף\" נלמד מפסוק בתורה, כלומר, שישנה נתינת­כח דתורה בכל הקשור לצורך ד\"כסף\" זה<sup data-n=\"1946\">84</sup>, ובמילא, בודאי ימצא מספיק כסף עבור פעולות אלו בכל מקום ומקום — במקום זה עצמו,\nומעלה יתירה בזה — כידוע<sup data-n=\"1947\">85</sup> שכל עניני קדושה אינם באופן של \"חנם\" (\"אשר נאכל במצרים חנם\"<sup data-n=\"1948\">86</sup>), שכן, ה­נתינה מממונו מורה שהענין נוגע לו כו', עד שמשתתף בדבר גם בממונו, ובמילא, עוסק בזה ביתר חיות כו'.\nאמנם, אם ישנו מקום שיכול להיות איזה גרעון, ח\"ו, בפעולות אלו בגלל ההוצאה הכספית שבדבר — אזי, לאחרי גמר הפעולה (והחשבון), יודיעו למקום מרכזי מהו הסכום שנדרש לארגון ה­התוועדות והמסיבה כו', ומכל המקומות המרכזיים יודיעו לכאן, ובלי­נדר, ישלחו מכאן עבור ההוצאות שבדבר, מתוך שמחה וטוב לבב.\nי. ויה\"ר שקבלת ההחלטה טובה (עוד לפני שיתחילו לעסוק בדבר בפועל ממש) תפעל תיכף ומיד את ה\"שכר\" ה­שייך לפעולה של אהבת ישראל ואחדות ישראל<sup data-n=\"1949\">87</sup> — ביטול הגלות,\nובפשטות — שתיכף ומיד ממש זוכים לגאולה האמיתית והשלימה ע\"י משיח צדקנו,\nובפרט — שנמצאים עתה בסיומו של השבת, בסמיכות למוצאי ש\"ק, \"סעודתא דדוד מלכא משיחא\"<sup data-n=\"1950\">88</sup>,\nואז, בבוא יום השבת הבעל\"ט — תתקיים \"התוועדות גדולה\" דכל בנ\"י ממש, \"קהל גדול ישובו הנה\"<sup data-n=\"1951\">89</sup>,\nו\"הקיצו ורננו שוכני עפר\"<sup data-n=\"1952\">90</sup>, ו\"משה ואהרן עמהם\"<sup data-n=\"1953\">91</sup>, ורשב\"י עמהם, וכל צדיקי ונשיאי ישראל, עד לכ\"ק מו\"ח אדמו\"ר נשיא דורנו — שהרי צדיקים (ועד ל\"ועמך כולם צדיקים\"<sup data-n=\"1954\">92</sup>) קמים לתחי' מיד<sup data-n=\"1955\">93</sup>,\nו\"ראש המדברים\" בהתוועדות זו יהי' — משיח צדקנו, שילמד תורה לכל העם (כולל האבות ומשה רבינו כו')<sup data-n=\"1956\">94</sup> — \"תורה חדשה מאתי תצא\"<sup data-n=\"1957\">95</sup>, פנימיות התורה, ובאופן של ראי'<sup data-n=\"1958\">96</sup>,",[["1946","84","להעיר מסיפור חז\"ל (שמו\"ר פנ\"ב, ג. ועוד) אודות פעולת רשב\"י — \"בקעה בקעה מלאי דינרי זהב, התחילה מושכת דינרי זהב\". ובלשון הכתוב ריש פרשתנו: \"אם בחוקותי תלכו (שתהיו עמלים בתורה — פרש\"י) ואת מצוותי גו' ונתתי גשמיכם בעתם\" — כל הברכות ויעודים גשמיים שבפרשה (כנ\"ל ס\"ב), ואין זה ענין דמשמש ע\"מ לקבל \"שכר\", כי אם, לצורך העבודה עצמה — כדברי הרמב\"ם (הל' תשובה רפ\"ט): \"הבטיחנו בתורה שאם נעשה אותה כו' ישפיע לנו כל הטובות המחזיקות את ידינו לעשות התורה, כגון שובע ושלום וריבוי כסף וזהב, כדי. . (ש)נשב פנויין ללמוד בחכמה ולעשות המצוה\"."],["1947","85","ראה זח\"ג קכח, א. וראה לקו\"ש ח\"ה ע' 81. וש\"נ."],["1948","86","בהעלותך יא, ה. וראה ספרי ופרש\"י עה\"פ."],["1949","87","ראה תענית ח, ב. שו\"ע או\"ח הל' תענית סו\"ס תקעא."],["1950","88","סידור האריז\"ל כוונת הבדלה ומו\"ש. פרע\"ח שער השבת ספכ\"ד."],["1951","89","ירמי' לא, ז."],["1952","90","ישעי' כו, יט."],["1953","91","ראה יומא ה, ב. תוד\"ה אחד — פסחים קיד, סע\"ב."],["1954","92","ישעי' ס, כא. וראה סנהדרין רפי\"א. רמב\"ם הל' תשובה פ\"ג ה\"ה."],["1955","93","ראה זח\"א קמ, א."],["1956","94","רמב\"ם שם ספ\"ט. לקו\"ת צו יז, א. ובכ\"מ."],["1957","95","ויק\"ר פי\"ג, ג."],["1958","96","לקו\"ת שם. שער האמונה פ\"ס. ועוד. ומעין זה — בלימוד הזהר, \"חיבורא דילך\", שהלשון הרגיל הוא (לא כבגמרא שרגיל (משא\"כ במקומות מתי­מספר ממש) — \"תא שמע\", אלא) \"תא חזי\", תרגום של ראי'. ולהעיר גם מהשייכות המיוחדת לשבת זו — כ\"ב אייר — השבת הראשונה לירידת המן (שהתחיל בט\"ז באייר, יום א' בשבת (פרש\"י בשלח טז, א — משבת פז, ב)), עלי' נאמר (בשלח שם, כט) \"ראו כי ה' נתן לכם השבת\", היינו, שענין ה\"שבת\" שבתורה, פנימיות התורה (שלכן, רבי יהודה קרי לרשב\"י — מארי דזהר — בשם \"שבת\" (זח\"ג קמד, ב)), הוא באופן של ראי' דוקא. ולהעיר, שהתחלת הלקו\"ת הוא בד\"ה ראו כי ה' נתן לכם השבת — וי\"ל רמז עכ\"פ, כי בלימוד פנימיות התורה כפי שנתגלתה בתורת החסידות מודגש ביותר הלימוד באופן של ראי', תכלית ההתאמתות."]]],[1301490333,"ואז יהי' גם מנין בנ\"י — התוכן דפ' במדבר — בתכלית השלימות, \"מנין ה­עשירי\"<sup data-n=\"1959\">97</sup>, ע\"י משיח צדקנו, \"גואל ראשון הוא גואל אחרון\"<sup data-n=\"1960\">98</sup>,\nבעגלא דידן ממש.\n<span data-k=\"q\">משיחת ש\"פ בחוקותי, כ\"ב אייר ה'תשמ\"ו</span>",[["1959","97","ראה תנחומא תשא ט. במדב\"ר פ\"ב, יא. וש\"נ. זח\"א רסב, א."],["1960","98","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. וראה לקו\"ש חי\"א ע' 8 ואילך. וש\"נ."]]],[1301430060,"<h3>שיחה א</h3>\nא. בפסוק<sup data-n=\"1\">1</sup> \"אך את מטה לוי לא תפקוד ואת ראשם לא תשא בתוך בני ישראל\" (שנאמר בהמשך למנין \"בני ישראל\"), מעתיק רש\"י את התיבות \"אך את מטה לוי לא תפקוד\", ומפרש: כדאי הוא לגיון של מלך להיות נמנה לבדו. ד\"א צפה הקב\"ה שעתידה לעמוד גזירה על כל הנמנין מבן עשרים שנה ומעלה שימותו במדבר<sup data-n=\"2\">2</sup> אמר אל יהיו אלו בכלל לפי שהם שלי שלא טעו בעגל.\nמפשטות לשון רש\"י נראה, שאין כוונתו לשלול הפירוש ד\"אך את מטה לוי לא תפקוד\" היינו שמטה לוי לא נמנה <i>כלל</i>, ומפרש שגם מטה לוי נמנה (וכמפורש <i>לקמן</i> בפרשה<sup data-n=\"3\">3</sup>) אלא שהוא נמנה \"<i>לבדו</i>\"<sup data-n=\"4\">4</sup> — כי א\"כ הו\"ל לרש\"י<sup data-n=\"5\">5</sup> להדגיש <i>החידוש</i>, שמטה לוי נמנה לבדו (שהרי עדיין לא נזכר בקרא שמטה לוי נמנה)<sup data-n=\"6\">6</sup>, ואח\"כ להוסיף הטעמים מדוע נמנה לבדו;\nכ\"א שרש\"י בא לבאר מדוע נמנה מטה לוי לבדו — ואומר ע\"ז שני טעמים: א) להיותו \"לגיון של מלך\". ב) כדי ש­\"אל יהיו אלו בכלל\" ה\"גזירה על כל הנמנין מבן עשרים שנה ומעלה שימותו במדבר\".\nויש לומר, שלא הוצרך רש\"י לשלול הפירוש הנ\"ל (שמטה לוי לא נמנה כלל) — כי לאחרי שכבר פירש בתחלת ה­פרשה \"מתוך חיבתן לפניו מונה אותן כל שעה. . כשבא להשרות שכינתו עליהן מנאן\", מובן בפשטות<sup data-n=\"7\">7</sup> (ואין כל ספק) שמטה לוי נמנה, ואדרבא<sup data-n=\"8\">8</sup>.\nאלא שרש\"י בא ליישב הקושי בה­כתוב: מכיון שבפסוקים שלפנ\"ז (בסיפור פרטי מנין בנ\"י) מפורש שלא נמנו בני לוי<sup data-n=\"9\">9</sup>, הרי מוכח שבציווי \"שאו את ראש",[["1","1","פרשתנו א, מט."],["2","2","שלח יד, כט. וראה לקמן סעיף ו."],["3","3","ג, טו ואילך."],["4","4","נוסף על שלא נמנה כלל במנין דיוצאי צבא, שבפשטות הוא מנין מיוחד."],["5","5","וגם: עפ\"ז כל התירוץ של רש\"י מיוסד על הדיוק שבסיפא דקרא — \"(לא תשא) בתוך בני ישראל\" (וכלשון המדרש (במדב\"ר פ\"א, יא­יב. פ\"ג, ז) \"בתוך בנ\"י אין אתה מונה אותן אבל לעצמן מנה אותן\") — והו\"ל לרש\"י להעתיק תיבות אלו בפירושו."],["6","6","וכן הו\"ל לרש\"י להביא הכתוב דלקמן (ג, טו) \"פקוד את בני לוי גו'\"."],["7","7","ולהעיר מבמדב\"ר כאן (פ\"א שם. וכן פ\"ב, יט)."],["8","8","ואינו דומה להא שלא נכללו הלויים במנין בנ\"י אחרי העגל (עיין רש\"י תשא ל, טז) — כי שם הטעם בפשטות מפני שלא טעו בעגל ולא שייך בהם \"לידע מנין הנותרים\" (רש\"י ריש פרשתנו. וכן רש\"י תשא שם); משא\"כ המנין דפרשתנו \"כשבא להשרות שכינתו עליהן. . הוקם המשכן\", ששייך גם ללויים<sup data-n=\"e1\">*</sup> (ואדרבה, יותר מבנ\"י, שהרי הם נבחרו לעבודת המשכן)."],["9","9","ראה רמב\"ן פרשתנו (א, מז): מתחלה ראה משה כו' שלא למנות הלוים. . לכל המטות הנמנים יהיו נשיאיהם ובעבור שלא מנה מבני לוי נשיא לא מנה אותם. וראה במדב\"ר פ\"א, יא."],["e1","*","ודוחק גודל לתרץ ע\"פ פרש\"י (ר\"פ פקודי. שמיני ט, כג) שהשראת השכינה במשכן היא עדות שהקב\"ה ויתר להם על מעשה העגל, והרי הלויים לא טעו בעגל — כי פשוט, שהענין ד\"להשרות שכינתו עליהן\" יש בו ענין של חביבות (גם לולא הענין דכפרת חטא העגל) השייך גם ללויים (ואדרבה, כבפנים)."]]],[1301430061,"כל עדת בנ\"י גו'\"<sup data-n=\"10\">10</sup> לא נכלל שבט לוי — וא\"כ מהו טעם הציווי \"אך את מטה לוי לא תפקוד גו' בתוך בנ\"י\", שמזה משמע שמחדש שלא למנותו ביחד עם שאר ישראל<sup data-n=\"11\">11</sup>? וע\"ז מביא רש\"י שני טעמים, כנ\"ל.\nב. אבל עדיין צריך להבין:\nא) פירושו של רש\"י (ביאור הטעמים לזה שמטה לוי נמנה לבדו) שייך גם להתיבות שבסיפא דקרא — \"(אך גו' לא תפקוד גו') בתוך בני ישראל\"; ומדוע לא העתיק רש\"י גם תיבות אלו, לא ב­פירושו ולא בהד\"ה (ולא רמזן אפילו ב\"וגו'\")?\nב) השאלה הנ\"ל (מהו החידוש שלא למנות מטה לוי בתוך בנ\"י) מתעוררת כבר לעיל, בפסוק<sup data-n=\"12\">12</sup> \"והלוים למטה אבותם לא התפקדו בתוכם\" (שגם מזה מוכח שיש חידוש שלא לפקוד את הלוים \"בתוכם\")<sup data-n=\"13\">13</sup> — ומ\"מ לא פרש\"י שם מאומה<sup data-n=\"14\">14</sup>; וא\"כ אינו מובן: מהו הקושי המיוחד בקרא דילן, שדוקא בו הוזקק רש\"י לבאר מדוע נמנו הלויים לבדם<sup data-n=\"15\">15</sup>?\nג) מה קשה בטעם הראשון דרש\"י, שמשו\"ז לא מסתפק בו והביא טעם שני<sup data-n=\"16\">16</sup>?\nובפרט שלכאורה הוא רחוק מדרך הפשט — הן מצד כללות תוכנו (שהטעם שנמנו לבדם הוא כדי להצילם מהגזירה ש\"צפה הקב\"ה שעתידה לעמוד\"), שקרוב יותר ל\"אגדה\" מלפשוטו של מקרא<sup data-n=\"17\">17</sup>;",[["10","10","פרשתנו א, ב."],["11","11","ולכאורה למאי נפק\"מ (כ\"כ) השלילה (\"לא תפקוד גו'\"), והול\"ל רק החיוב (דלקמן בפרשה) \"פקוד את בני לוי גו'\"."],["12","12","א, מז."],["13","13","ולהעיר שבבמדב\"ר (פ\"א, יא ופ\"ב שם) מתחיל בפסוק \"והלוים למטה אבותם וגו'\"."],["14","14","וי\"ל — כי אין דרכו של רש\"י לכתוב (סתם) טעמי המצות וההלכות, כ\"א רק כשנוגע להבנת פשוטו של מקרא (ראה ס' כללי רש\"י (קה\"ת, תש\"מ) פ\"ג (בהוצאת תנש\"א — פ\"ב). וש\"נ)."],["15","15","אלא שבזה י\"ל שרש\"י כותב פירושו כאן שהוא בלשון ציווי \"אך את מטה לוי לא תפקוד גו'\", משא\"כ בפסוק שלפנ\"ז שהוא רק בלשון סיפור, ש\"הלוים גו' לא התפקדו בתוכם\". וראה במדב\"ר פ\"א שם. רמב\"ן ועוד עה\"פ."],["16","16","ברע\"ב (ושפ\"ח) כאן, \"דלפי פי' הראשון לא שייך מלת אך שהוא לשון מעוט לכך פי' ד\"א שממעט אותם למות במדבר עם שאר ישראל כו'\". וצ\"ע אם ע\"פ פשש\"מ מוכרח שבכל מקום שנאמר \"אך\" הכוונה למיעוט נוסף בהענין (כבנדו\"ד, ש­תיבת \"אך\" מלמדנו, שנוסף לזה שנתמעטו הלויים ממנין בנ\"י, נתמעטו גם מגזירת המרגלים). וראה מלבי\"ם כאן. ואכ\"מ.\nבמשכיל לדוד כ' דלפי' הא' קשה \"מאי שנא דשינה בהם מספר מפקדם שישראל מנאם מבן כ' שנה והללו מבן חודש\". אבל לכאורה לא נחית רש\"י כאן לתרץ השינוי ב\"מספר מפקדם\" — שלא נזכר כלל ברש\"י כאן. והרי הטעם שמנין בני לוי הוא \"מבן חודש גו'\" מפורש בפרש\"י לקמן (ג, טו) \"משיצא מכלל נפלים. . למוד הוא אותו שבט להיות נמנה מן הבטן\" (וראה לקמן סוף ס\"ד, שגם לפירוש הב' ברש\"י כאן לא נחית לבאר טעם השינוי ב\"מספר מפקדם\")."],["17","17","וגם ק\"ק שמנין בנ\"י שבא \"מתוך חיבתן לפניו\" יהי' קשור עם עונש וגזירה על בנ\"י (אבל ראה לקמן סעיף ו).\n[בלשון רש\"י שברמב\"ן (ריש פרשתנו) \"שאו את ראש. . כמו שאומרים לקוסטינר ארים רישי' דדין\" (והוא מבמדב\"ר פ\"א, יא). וכ\"ה בדפוס שני דפרש\"י וא' מכת\"י רש\"י שתח\"י<sup data-n=\"e2\">*</sup> (והובא גם ברא\"ם ר\"פ תשא). אבל ליתא בדפוס א', שאר כת\"י רש\"י ש­תח\"י ובדפוסי רש\"י הנפוצים. וגם צ\"ע לכאורה איך זה מתאים עם פרש\"י בריש הפרשה ד\"מתוך חיבתן. . מונה אותן כו'\". ואכ\"מ]."],["e2","*","ובשניהם נעתק גם המשך לשון הבמדב\"ר \"ובשבט לוי לא נאמר כו' שצפה הקב\"ה שעתיד לגזור גזירה כו'\" (תוכן טעם השני שבפרש\"י כאן. ובדפוס שני כאן הובא רק טעם הראשון (\"כדאי כו'\") ונשמט טעם השני)."]]],[1301430062,"והן מצד המשך הכתובים כאן: ב­פסוק שלאח\"ז<sup data-n=\"18\">18</sup> נאמר \"ואתה הפקד את הלוים על משכן העדות וגו'\", דהיינו ה­מינוי ושררה<sup data-n=\"19\">19</sup> של מטה לוי על המשכן. וא\"כ, בשלמא לפי' הא' של רש\"י, שמטה לוי נמנה לבדו להיותו \"לגיון של מלך\", מובן המשך הדברים<sup data-n=\"20\">20</sup>, כי הציווי \"ואתה הפקד את הלוים על משכן גו'\" הוא הטעם ל\"אך את מטה לוי לא תפקוד גו' בתוך בני ישראל\" (להיותם \"לגיון של מלך\" הממונים על משכן העדות); אבל לפי' השני אין כאן המשך, לכאורה, בין \"ואתה הפקד את הלוים גו'\" ל\"אך את מטה לוי לא תפקוד וגו'\"?\n[ולפירוש זה (הב'), הו\"ל לכתוב כאן (לא \"ואתה הפקד את הלוים גו'\", אלא) הפסוק שבהמשך הפרשה<sup data-n=\"21\">21</sup> \"ואני הנה לקחתי את הלוים מתוך בנ\"י גו' והיו לי הלוים\"<sup data-n=\"22\">22</sup> — בהתאם להטעם שניצלו (הלויים) מן הגזירה \"לפי שהם שלי שלא טעו בעגל\"<sup data-n=\"23\">23</sup> (וכפרש\"י<sup data-n=\"21\">21</sup> דלקיחת ה­לויים היתה \"כשחטאו בעגל. . והלויים שלא עבדו ע\"א נבחרו\")<sup data-n=\"25\">24</sup>].\nג. ויש לומר הביאור בזה:\nבכתוב כאן יש, לכאורה, כפל לשון — \"(אך את מטה לוי) לא תפקוד ואת ראשם לא תשא\". דלכאורה הול\"ל \"אך את מטה לוי לא תפקוד בתוך בני ישר­אל\", או \"אך את ראש בני לוי לא תשא בתוך בנ\"י\" (וכיו\"ב).\nומפשטות הלשון משמע, ש\"לא תפ­קוד\" ו\"לא תשא\" הם שני פרטים שונים בענין המנין.\nוהחילוק ביניהם — בפשטות<sup data-n=\"26\">25</sup>: \"תפ­קוד\" פירושו פעולת המנין, נשיאת ראש (\"ראשם. . תשא\") פירושה (לפרש\"י<sup data-n=\"27\">26</sup>) קבלת \"סכום מנינם\", היינו ידיעת הסך­הכל \"כמה הם\".\nוהנה ע\"פ פי' רש\"י, יש בכלל הבדל עיקרי בין אופן מנין בני ישראל למנין הלויים: במנין בנ\"י פי' רש\"י<sup data-n=\"28\">27</sup> שהי' \"על ידי שקלים בקע לגלגולת\" [וזהו בהתאם לפירושו בר\"פ תשא ד\"כשתחפוץ לקבל",[["18","18","א, נ."],["19","19","רש\"י שם."],["20","20","ראה גם במדב\"ר פ\"א, יב. משכיל לדוד ועוד כאן."],["21","21","ג, יב."],["22","22","וראה במדב\"ר שם ופי' מהרז\"ו שם ד\"ה והיו לי הלוים."],["23","23","ראה לקמן סעיף ו ובהערה 40."],["21","21","ג, יב."],["25","24","ודוחק גדול לתרץ שזהו מפני ש\"ואתה הפקד את הלוים\" תוכנו — תחילת לקיחת הלויים לשרת כו' (שזהו מה ש\"הם שלי\") — שהרי סו\"ס מתאים יותר שיכתב כאן הפסוק שבו מפורש \"והיו לי הלוים\" (עם הטעם דלקיחת הלויים, שנבחרו תחת כל בכור בעת חטא העגל), ומתוסף בהדוחק ע\"י שמפסיק ביניהם בפ' שלימה (דגלים)."],["26","25","ראה גם ספורנו כאן. ועוד."],["27","26","ר\"פ תשא.\nבפרש\"י וישב (מ, יג. ועד\"ז שם, כ) ד\"ישא פרעה את ראשך — ל' חשבון כשיפקוד כו' ימנה אותך עמהם\". אבל לכאורה מסתבר לומר, דמש\"נ \"שאו את ראש\" (וכיו\"ב) במנין בנ\"י, פירושו ע\"ד הכתוב \"כי תשא את ראש בנ\"י\" (שבר\"פ תשא). וכת\"א פרשתנו (א, ב. א, מט). ובכל אופן, בנדו\"ד שנאמרו ב' לשונות (\"תפקוד. . תשא\") מסתבר שהם ב' ענינים.\nולהעיר מגו\"א ר\"פ תשא, דכוונת רש\"י בפ' וישב היא ג\"כ כפירושו בר\"פ תשא (לשון קבלת סכום המנין). ע\"ש."],["28","27","פרשתנו א, ב ד\"ה לגולגלותם. וראה גם רש\"י תשא ל, טו.\nמשא\"כ \"הרבה מן המפרשים חלקו עליו ואמרו שמספר זה הי' בלא שקלים\" (כלי יקר פרשתנו שם. וראה מדרש לקח טוב, רלב\"ג ועוד שם. אברבנאל ר\"פ תשא. חזקוני שם ל, טז. ועוד)."]]],[1301430063,"סכום מנינם. . אל תמנם לגלגולת אלא יתנו כל אחד מחצית השקל ותמנה את השקלים ותדע מנינם\"], משא\"כ מנין הלויים הי' \"על פי ה'\"<sup data-n=\"29\">28</sup>, וכפרש\"י \"הלך משה ועמד על פתח האהל והשכינה מקדמת לפניו ובת קול יוצאת מן האהל ואומרת כך וכך תינוקות יש באהל\" (ועי\"ז ידע משה \"מנין יונקיהם\" — שהרי מנין הלוים הי' \"מבן חודש ומעלה\"<sup data-n=\"30\">29</sup>).\nוזהו פירוש לשון הכתוב \"אך את מטה לוי לא תפקוד ואת ראשם לא תשא בתוך בנ\"י\" — כלומר, שלא זו בלבד ש­כמות מנינם של הלויים (\"ראשם. . תשא\") לא הי' \"בתוך בני ישראל\" (היינו שאין לכלול \"סכום מנינם\" של הלויים בתוך סכום מנינם של בנ\"י<sup data-n=\"31\">30</sup>), אלא שגם אופן פעולת המנין (\"תפקוד\") של בני לוי הי' שונה לגמרי מאופן פקודת בנ\"י, כנ\"ל<sup data-n=\"32\">31</sup>.\nד. והנה ע\"פ יסוד זה (שיש כאן ב' ענינים — פקידה ונשיאת ראש; מעשה המנין וסיכום חשבון המנין) יש לחקור בפירוש הכתוב \"אך את מטה לוי לא תפקוד\" — די\"ל בשני אופנים:\nא) בפשטות — שסיום הכתוב \"בתוך בני ישראל\" מוסב גם על התחלת הכתוב \"אך את מטה לוי לא תפקוד\", וכוונת ה­כתוב היא, שלא תפקוד את הלויים \"בתוך (באותו אופן המנין של) בני ישר­אל\", כי מנינם הי' באופן שונה.\nב) מכיון שמנין הלויים הי' ע\"י בת­קול שהודיעה למשה \"כך וכך תינוקות יש באהל\" — הרי אין זה בגדר \"תפ­קוד\"<sup data-n=\"33\">32</sup>, שענינו הוא א) פקידת האדם ב) שמונים א' א' \"לגולגלותם\". ועפי\"ז ה­כתוב מתחלק לשנים — (א) \"אך את מטה לוי לא תפקוד\" — סוף ענין, ששבט לוי לא ניתן לפקוד כלל<sup data-n=\"34\">33</sup>; (ב) \"ואת ראשם לא תשא בתוך בני ישראל\" — שידיעת \"סכום מנינם\" אינה \"בתוך בני ישראל\", אלא בפני עצמם.\nוזהו החילוק בין שני הפירושים ברש\"י:\nלפירוש הא' — \"כדאי הוא לגיון של מלך להיות נמנה לבדו\" — גם רישא דקרא (\"אך את מטה לוי לא תפקוד\") בא להדגיש החיוב, שאת מטה לוי צריכים למנות לבדו (לא \"בתוך בני ישראל\"), היינו שגם הלויים נפקדו, אלא שנמנו בפ\"ע באופן שונה.\nמשא\"כ לפירוש השני — \"צפה הקב\"ה כו' גזירה על כל הנמנין כו' אל יהיו אלו בכלל\" — לא בא הכתוב (ברישא דקרא) להדגיש חיבתן של בני לוי במנינם המיוחד, אלא אדרבה — מצד חיבתן לא נפקדו (כלל), כדי שלא תחול עליהם ה\"גזירה (ש)על כל הנמנין כו'\".\n[כלומר: לפרש\"י כאן צ\"ל, דמה שלא חלה גזירת המרגלים על הלויים, אינו (רק) משום שנמנו \"מבן חודש גו'\" ובמילא לא נכללו במנין ד\"מבן עשרים",[["29","28","לקמן ג, טז."],["30","29","שם, טו."],["31","30","ראה השקו\"ט במפרשי רש\"י (רא\"ם, גו\"א ועוד) שלכאורה בלאה\"כ אא\"פ לכוללם יחד, שהרי מנין הלויים הוא מבן חודש. ואכ\"מ."],["32","31","ראה גם כלי יקר כאן."],["33","32","כי אף שבכללות גם מנין באופן זה אפשר לקרוא (בשם המושאל עכ\"פ) \"תפקוד\" — וכמפורש לקמן (ג, טו­טז) \"פקוד את בני לוי גו' ויפקוד אותם משה גו'\" — מ\"מ, כשמדייקים בלשונות (וכבהכתוב כאן, שמפרט \"לא תפקוד. . לא תשא\") אין מנין כזה באופן ד\"תפקוד\". ועצ\"ע."],["34","33","ראה גם כלי יקר כאן (אלא שהוא מפרש, ש\"אתה (משה) לא תפקוד בני לוי לבדך\", כ\"א \"ב­צירוף השכינה\")."]]],[1301430064,"גו'\"<sup data-n=\"35\">34</sup> (דאם זוהי כוונת רש\"י, הו\"ל לפרש זה בהדיא, כי עדיין לא למדנו שהלויים נמנו \"מבן חודש גו'\") — אלא (גם) מפני שלא נפקדו (כלל), כדלקמן סעיף ו].\nולפירוש זה, מש\"נ \"אך את מטה לוי לא תפקוד\" פירושו, פשוטו כמשמעו — שלא יפקוד את הלויים, כדי להצילם מגזירת המרגלים<sup data-n=\"36\">*34</sup>.\nה. עפ\"ז מתורצות כל הקושיות דלעיל (סעיף ב) — כי כל כוונת רש\"י היא לתרץ אריכות הלשון שבכתוב זה (כנ\"ל), ולכן:\nא) אין זה שייך לפסוק \"והלוים גו' לא התפקדו בתוכם\".\nב) פשוט מה שלא הביא רש\"י סיום הכתוב \"בתוך בני ישראל\" — א) מכיון שלא נחית כאן לתרץ מדוע נמנה שבט לוי לבדו מדיוקא דקרא \"בתוך בני ישראל\" (הא לעצמן נמנו), אלא להסביר אריכות הלשון, כנ\"ל; ב) אין מקום ל­הביא סיומא דקרא, מאחר שכוונתו לומר שיש לפרש (כפירוש הב') שרישא דקרא (\"אך את. . לא תפקוד\") הוא ענין בפ\"ע, והסיום \"בתוך בני ישראל\" אינו מוסב ל\"לא תפקוד\" שבתחילת הכתוב.\nג) לא הסתפק רש\"י בפירוש הא', כי הלשון \"אך את מטה לוי לא תפקוד\" בפשטות יותר לפירוש השני, שלפיו פירושו כפשוטו ממש, ש\"את מטה לוי לא תפקוד\" כלל.\nו. אלא שעדיין צריך ביאור במה ש­נת\"ל, שלפי הפירוש השני לא חלה גזי­רת המרגלים על הלויים (לא מפני שלא נכללו בכלל בני \"עשרים שנה ומעלה\", אלא) מפני שלא נפקדו — דלכאורה, הרי סוף­סוף נמנו הלויים \"על פי ה'\", ומהי שייכות גזירת המרגלים לאופן המנין (אם ע\"י שקלים או \"על פי ה'\")?\nוי\"ל, שזה מובן ע\"פ פרש\"י דלעיל:\nבר\"פ תשא נאמר \"כי תשא את ראש בנ\"י לפקודיהם ונתנו גו' בפקוד אותם ולא יהי' בהם נגף בפקוד אותם\", ופרש\"י \"ולא יהי' בהם נגף — שהמנין שולט בו עין הרע והדבר בא עליהם\" (ולכן צ\"ל המנין ע\"י שקלים \"ואל תמנם לגולגולת\", שזה מציל מן ה\"עין הרע\"). ונמצא, שה­מנין (\"בפקוד אותם\") עלול לגרום שלי­טת עין הרע ודבר (אף שסיבת המנין היא — כפרש\"י — \"מתוך חיבתן לפניו\").\nומזה יובן גם לעניננו — ובהקדם:\nהטעם שהוצרכו הלוים לשמירה מיו­חדת מגזירת המרגלים, אינו מפני שהיו חייבים עונש על חטא (שהרי הלויים לא השתתפו בעצת המרגלים, כמפורש ב­פרש\"י<sup data-n=\"37\">35</sup>), אלא מפני<sup data-n=\"38\">36</sup> שנגזרה גזירה על",[["35","34","כבב\"ב קכא, ב. וראה רש\"י שלח יד, כט. — אבל להעיר מלשון רש\"י שם \"כל הנמנה לכל מספר שאתם נמנין בו כו' כל המנויים לכל אותן מספרות ימותו ואלו הן מבן כ' שנה וגו'\". דמשמע, דמ\"ש \"ואלו הן מבן כ' שנה וגו' להוציא שבטו של לוי\" הוא רק הסימן איזה מבנ\"י נכללו ב\"כל אותן מספרות\", אבל הטעם שלא נכלל שבט לוי בהגזירה הוא מפני שאין הם נמנים (בכלל) \"לכל מספר שאתם נמנין בו\". וצ\"ע."],["36","*34","וצ\"ע במנין הב' דבני לוי מבן ל' עד בן נ' (לקמן ד, א ואילך. נשא ד, כא ואילך) שבפשטות לא הי' \"ע\"פ ה'\" (כל' רש\"י פרשתנו ד, ב \"מנה מהן כו'\"). וראה רשב\"ם ב\"ב שם.\nואולי זהו הדיוק (פרשתנו שם. ר\"פ נשא) \"נשא גו'\" ולא \"פקוד\" [ורק אצל בני מררי לא נאמר \"נשא\" אלא \"תפקוד\" (נשא ד, כט­ל). ואצל בני גרשון נאמר (שם, כג) גם \"תפקדם\"]. וראה כלי יקר הנ\"ל. לקו\"ש חי\"ח ע' 46 ואילך. ואכ\"מ."],["37","35","דברים א, כג. — וכבר האריכו במפרשי רש\"י. ואכ\"מ."],["38","36","ראה עד\"ז דברי דוד וחי' ופי' מהרי\"ק על פרש\"י כאן."]]],[1301430065,"כללות עם ישראל<sup data-n=\"39\">37</sup>, שמצד הגזירה אין הבדל בין צדיק לרשע<sup data-n=\"40\">38</sup> (ע\"ד פרש\"י לעיל<sup data-n=\"41\">39</sup> \"מאחר שנתנה רשות למשחית לחבל אינו מבחין בין צדיק לרשע\"); אלא שלהיות שהלויים \"הם שלי (מפני<sup data-n=\"42\">40</sup>) שלא טעו בעגל\", הוציאם הקב\"ה מכלל הגזירה ע\"י השינוי באופן מנינם.\nומובנת השייכות בין מניעת גזירת ה­מרגלים ל\"אך את מטה לוי לא תפקוד\":\nגזירת המרגלים חלה על \"כל פקודי­כם לכל מספרכם\"<sup data-n=\"43\">41</sup> (מבלי הבדל בין צדיק לרשע) מפני שפקידה נותנת מקום לענין בלתי רצוי (וצריכים נתינת שקלים (\"כופר נפשו\") להציל מזה). ולכן, כאשר יצא הקצף לפני ה' ונגזרה גזירה על כללות עם ישראל, נכללו בזה \"כל פקו­דיכם לכל מספרכם\".\nוזהו מה שאמר הקב\"ה \"אך את מטה לוי לא תפקוד\" כדי ש\"אל יהיו אלו בכלל\", דמכיון שמנינם אינו בגדר \"תפקוד\", שוב אינם שייכים להנגף הפוגע ב\"כל פקודיכם\"<sup data-n=\"44\">42</sup>.\nז. מ\"יינה של תורה\"<sup data-n=\"45\">43</sup> שבפרש\"י זה:\nההפרש בין שני פירושי רש\"י הנ\"ל — דלפירוש הא' גם הלויים נפקדו כמו בנ\"י (אלא שנמנו באופן ותנאים שונים), משא\"כ לפירוש הב' לא נפקדו הלויים כלל, כי מנין הלויים אינו בגדר \"תפקוד\" — י\"ל שהם כנגד שתי דרגות במעלת הלויים על כל ישראל.\nויובן זה בהקדם ביאור שלשת האופנים הנ\"ל שבמנין — (א) מנין בנ\"י, (ב) מנין מטה לוי \"לבדו\", (ג) \"את מטה לוי לא תפקוד\" — בעבודת האדם:\nעבודת ה' מתחלקת לשלשת הקוים (העמודים) דתורה עבודה וגמילות חסדים<sup data-n=\"46\">44</sup>, שהם, בכלל, שלשה סוגי עבודה<sup data-n=\"47\">45</sup>: (א) קיום המצות, (ב) לימוד התורה, (ג) דביקות בה' (בתפלה)<sup data-n=\"48\">46</sup>, ששלימותה היא העבודה דמסירת נפש.\nמצות ניתנו במספר<sup data-n=\"49\">47</sup> — תרי\"ג דוקא,",[["39","37","וכדיוק לשון רש\"י \"שעתידה לעמוד גזירה\", ולא לשון עונש וכיו\"ב."],["40","38","והרי תחילת הגזירה היתה \"אכנו בדבר גו' ואעשה אותך לגוי גדול\" (שלח יד, יב) — שעכצ\"ל ששבט לוי בכלל, שהרי מפורש מי אינו בזה \"אותך\"<sup data-n=\"e3\">*</sup> — אלא שאח\"כ נחלפה ל\"במדבר הזה יפלו (בנ\"י) גו'\" (שם, כט)."],["41","39","בא יב, כב."],["42","40","היינו שהטעם שניצלו הוא מפני ש\"הם שלי\", וסיום ל' רש\"י \"שלא טעו בעגל\" הוא הדבר שגרם שיהיו שלי (כפרש\"י לקמן ג, יב — וכנ\"ל סוס\"ב). — ומתורצת עפ\"ז השקו\"ט במפרשי רש\"י מדוע נקט רש\"י \"לא טעו בעגל\" ולא שלא טעו במרגלים (החטא המדובר כאן)."],["43","41","ל' הכתוב — שלח יד, כט. וראה לעיל הערה 34."],["44","42","ולהעיר מש\"ך עה\"ת פרשתנו (ג, טו)."],["45","43","ראה \"היום יום\" כ\"ט שבט."],["46","44","אבות פ\"א מ\"ב."],["47","45","בהבא לקמן ראה בארוכה לקו\"ש חי\"ח ע' 193 ואילך."],["48","46","ראה הל' ת\"ת לאדה\"ז (פ\"ד סוס\"ה — מס' חרדים ושל\"ה) \"מצות הדביקות האמיתית ביראה ואהבה היא גדולה ממצות ת\"ת וקודמת אלי'\", ולכן \"חסידים הראשונים היו שוהין. . ט' שעות ביום\" (בתפלה — \"שהיו מקשרים דעתם כו' ודביקות אמיתית עד שהיו מגיעים להתפשטות הגשמיות\" — הל' ת\"ת שם. ועד\"ז בטושו\"ע ושו\"ע אדה\"ז (או\"ח ר\"ס צח)) — \"ולא היו חוששין לביטול תורה\"."],["49","47","ראה גם לקו\"ת פרשתנו (ו, סע\"א ואילך. ז, ג ואילך) בפירוש הכתוב (הושע ב, א — הפטורת פרשתנו) \"והי' מספר בנ\"י גו'\". וראה לקו\"ת בלק סח, א ואילך."],["e3","*","ואף שגם יהושע וכלב אינם בכלל (וא\"כ עכצ\"ל ד\"אותך\" לאו דוקא) — פשיטא שיש לחלק, דיהושע וכלב מפורש בקרא שיוצאים מן הכלל, ואטו כי רוכלא ליזיל ולחשוב (\"אותך ויהושע וכלב\"), משא\"כ בנוגע לשבט לוי (שגם משה בכללו) את\"ל דאינם בכלל הול\"ל \"ושבטך\" וכיו\"ב."]]],[1301430066,"ונצטוינו<sup data-n=\"50\">48</sup> \"לא תוסיפו. . ולא תגרעו\" [וכן בכל מצוה עצמה — יש שיעור ו­הגבלה באופן קיומה<sup data-n=\"51\">49</sup>],\nכי עיקר ענינן של מצות הוא (כ­מבואר בתניא<sup data-n=\"52\">50</sup>), להמשיך קדושה בגש­מיות<sup data-n=\"53\">51</sup> העולם (המוגבל — נאמר עליו די<sup data-n=\"54\">52</sup>), שלכן רוב מצות התורה הן מצות מעשיות, שנתלבשו בדברים גשמיים ו­עניני עוה\"ז — שהם במדידה והגבלה, גדר \"מספר\";\nהתורה (מצד עצמה) היא למעלה ממדידה, כמ\"ש<sup data-n=\"55\">53</sup> \"ארוכה מארץ מדה ורחבה מני ים\" — למעלה מגשמיות ה­עולם, ועד שהיא למעלה ממדידות והגבלות דזמן ומקום, כמרז\"ל<sup data-n=\"56\">54</sup> דכל העוסק בתורת עולה כאילו הקריב עולה (ללא הגבלות דזמן ומקום<sup data-n=\"57\">55</sup>).\nאבל לאידך, מזה גופא שנאמר \"ארו­כה מארץ מדה\" מובן, שגם התורה היא בגדר \"מדה\" (כי על דבר שאינו בגדר \"מדה\" לא שייך לומר שהוא ארוכה מ\"מדה\")<sup data-n=\"58\">56</sup> — ובפרט שהתורה היא מקור המצות וצ\"ל ערך ביניהם.\n[וע\"ד מש\"נ בהפטורת פרשתנו<sup data-n=\"59\">57</sup> \"והי' מספר בני ישראל גו' אשר לא ימד ולא יספר\", שיש בזה שני ענינים: \"והי' מספר בנ\"י\" ולאידך — אא\"פ לספור אותם, \"כי<sup data-n=\"60\">58</sup> לא יספר (מרוב<sup data-n=\"61\">59</sup>)\"];\nמסירת נפש היא למעלה לגמרי מכל ענין של מדה וגבול<sup data-n=\"62\">60</sup>. ובפשטות, התנו­עה דמסירת נפש מורה על דביקות בה' שאין לה גבול ותכלית, עד שהאדם מוכן ומוסר נפשו<sup data-n=\"63\">61</sup> עבורו ית'.\nח. שלש עבודות הנ\"ל מתאימות המה לשלשה הסוגים (הכלליים) שבבני ישראל — (א) (רוב) בני ישראל, (ב) שבט לוי, (ג) כהן גדול<sup data-n=\"47\">45</sup>.\nהנהגת (רוב) בני ישראל היא באופן ד\"הנהג בהם מנהג דרך ארץ\"<sup data-n=\"65\">62</sup>, ועיקר עבודתם היא קיום המצות ועשיית מעשים טובים (מארי עובדין טבין);\nשבט לוי ענינו (בלשון הרמב\"ם<sup data-n=\"66\">63</sup>) — ש\"הובדל לעבוד את ה' לשרתו ולהורות",[["50","48","ואתחנן ד, ב. ועד\"ז פ' ראה יג, א. וראה לקו\"ש חט\"ו ע' 138 הערה 8."],["51","49","ראה אגה\"ק ס\"י. ובכ\"מ."],["52","50","פל\"ז. ע\"ש באורך."],["53","51","ועד שע\"י כמה מהן נעשה הגשם — חפצא דקדושה."],["54","52","חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["55","53","איוב יא, ט."],["56","54","מנחות בסופה. וראה לקו\"ש חי\"ח ע' 413 בהערות. וש\"נ."],["57","55","ראה לקו\"ת פרשתנו יג, א­ב. בלק סח, ב. — ולהעיר משו\"ע אדה\"ז ס\"א (במהד\"ק — סי\"ג ואילך; במהד\"ב — שם סוס\"ט). וראה אוה\"ת שבועות ע' קנט. ואכ\"מ."],["58","56","תו\"א בשלח סא, סע\"א. אוה\"ת חנוכה (שי, א). סה\"מ תרכ\"ט ע' נד — ע\"פ עירובין כא, סע\"א."],["59","57","הושע ב, א."],["60","58","לקו\"ת בלק (סח, א. שם, ג)."],["61","59","ל' הכתוב — וישלח לב, יג."],["62","60","ראה לקו\"ת שם (ע, א­ב) דבחי' בלי מספר בנפש הו\"ע יחידה שבנפש (וכן בנמשל הוא \"יחיד. . עצמותו ית' שאין עוד מלבדו. . ואינו בגדר מספר. . לפני אחד. . מה אתה סופר\"). — אלא ששם מפרשו על ענין התורה (וראה לקמן בסוף השיחה). ובלקו\"ת פרשתנו (נסמן בהערה 47) מפרשו על עבודת התשובה."],["63","61","אף ד\"כל אשר לאיש יתן בעד נפשו\" (איוב ב, ד)."],["47","45","בהבא לקמן ראה בארוכה לקו\"ש חי\"ח ע' 193 ואילך."],["65","62","ברכות לה, ב."],["66","63","סוף הל' שמיטה ויובל (פי\"ג הי\"ב­י\"ג)."]]],[1301430067,"דרכיו הישרים ומשפטיו<sup data-n=\"67\">64</sup> הצדיקים ל­רבים שנאמר<sup data-n=\"68\">65</sup> יורו משפטיך ליעקב ותורתך לישראל לפיכך הובדלו מדרכי העולם כו' ולא שבט לוי בלבד אלא כל איש ואיש. . אשר נדבה רוחו כו' להבדל לעמוד לפני ה' לשרתו כו'\" — מארי תורה;\nאבל מזה גופא שעבודתם היא \"להו­רות. . לרבים\" מובן, שאין הם מובדלים (לגמרי) משאר ישראל העוסקים בדרכי העולם, ואדרבא — \"יורו\" להם כו', וכ­פשטות הנהגתם<sup data-n=\"69\">66</sup>, שבני לוי מסתובבים בערי בני ישראל לקבל תרומותיהם וכו' ועוסקים שם בהוראה לרבים (אלא שב­זמנים מיוחדים באים לבית המקדש ועובדים עבודת המקדש);\nלמעלה מכולם הוא הכהן גדול, ש­נצטווה<sup data-n=\"70\">67</sup> \"מן המקדש לא יצא\", ואינו יוצא מירושלים לעולם<sup data-n=\"71\">68</sup>;\nענינו של כהן גדול הוא — להיות בדביקות תמידית בהקב\"ה, למעלה ממדידה והגבלה (דביקות הנמשכת ובאה מעצם נפשו, יחידה שבנפש, המיוחדת עמו ית', \"יחידה לייחדך\"<sup data-n=\"72\">69</sup>).\nומזה החילוק בין ג' סוגים אלה גם בנוגע למנינם:\nפקידתם של בני ישראל, שעבודתם (העיקרית) היא במצות מעשיות שניתנו במספר (מדוייק), היתה באופן של מנין בדרכי הטבע, על ידי משה ואהרן עם \"נשיא כל שבט ושבט\"<sup data-n=\"73\">70</sup>, שמנו את השקלים (גשמיים) שניתנו על ידי בנ\"י;\nשבט לוי שעיקר ענינו הוא \"יורו\", תורה — שיש בה שני הענינים: היא בגדר מספר וביחד עם זה למעלה מ­מדידה ומספר הרגיל (ע\"ד \"אשר לא יספר מרוב\") — נמנה \"על פי ה'\", דמכיון שעבודתם היא בדרגא כזו שהיא בגדר \"מספר\", לכן גם הם נמנו, אבל לא במנין גשמי וטבעי, כי הם למעלה ממדידת בשר ודם (כי \"לא ימד ולא יספר\") אלא \"על פי ה'\".\nאמנם בנוגע לאהרן איתא ברש\"י<sup data-n=\"74\">71</sup> ש\"לא הי' במנין הלוים\", שפשטות הלשון מורה שלא נמנה (ונכלל) במנין הלוים<sup data-n=\"75\">72</sup> — כי עבודת אהרן כהן גדול היא ה­דביקות בה' שלמעלה מכל גדר מדידה ומספר.\nט. ע\"פ כל הנ\"ל יובן ההפרש בין שני הפירושים ברש\"י בנוגע למנין ה­לויים:\nפירוש הא' — \"כדאי הוא לגיון של מלך להיות נמנה לבדו\" — הוא בהתאם למעלתו של שבט לוי בענין התורה, שמצד מעלה זו גם הוא נמנה, אלא ש\"נמנה לבדו\" (\"על פי ה'\").\nמשא\"כ לפירוש השני ברש\"י, יש בשבט לוי (גם) מעלה זו שאינם בגדר מספר — \"לא תפקוד\". ומעלה זו באה להם על ידי \"שלא טעו בעגל\", כלומר,",[["67","64","להעיר דהסדר בקרא שמביא לראי' ויסוד \"יורו משפטיך גו' ותורתך\",\nאלא שכנראה \"דרכיו הישרים ומשפטיו ה­צדיקים\" שברמב\"ם — הם פרטים ב\"משפטיך\" דקרא. וצ\"ע."],["68","65","ברכה לג, י."],["69","66","רש\"י ויחי מט, ז."],["70","67","אמור כא, יב. וראה הנסמן בהערה הבאה."],["71","68","רמב\"ם הל' כלי המקדש פ\"ה ה\"ז. וראה גם הל' ביאת מקדש פ\"א ה\"י."],["72","69","ל' הושענות דיום ג'. וראה לעיל הערה 60."],["73","70","ל' רש\"י פרשתנו א, ד."],["74","71","פרשתנו ג, לט."],["75","72","ראה השקו\"ט במפרשי רש\"י שם. וראה לקו\"ש חי\"ג ע' 9 הערה 1."]]],[1301430068,"לא זו בלבד שלא חטאו בעגל, אלא עוד זאת, שהיו מושללים אפילו מטעות ב­מחשבה וקס\"ד בזה מחמת דביקותם בה', שאין אפשרות של פירוד כו'.\nולכן — \"שלי הם\", שהלויים נקנו לה' באופן שהתקשרות זו שלמעלה ממדידה והגבלה היא בהם בגלוי, ומצד מעלה זו ה\"ה למעלה מגדר מספר — \"לא תפקוד\".\nי. ג' האופנים באופן מנין בנ\"י הנ\"ל, שייכים ודוגמתם בהזמן שבו קורין פ' במדבר — בסוף ימי הספירה<sup data-n=\"76\">73</sup>, \"קודם עצרת\"<sup data-n=\"77\">74</sup>:\nידוע ביאור רבינו הזקן<sup data-n=\"78\">75</sup> במש\"נ<sup data-n=\"79\">76</sup> \"תספרו חמשים יום\" — אף שסופרים רק מ\"ט יום — שחמשים ימי הספירה הם כנגד חמשים שערי בינה, ולכן בפועל סופרים רק מ\"ט יום, כי שער הנו\"ן הוא למעלה מעבודת הנבראים, ואא\"פ להם לספור (ולהמשיך) שער הנו\"ן. אלא של­אחרי שהנברא מגיע לשלימות העבודה שלו (על ידי ספירת מ\"ט יום), נמשך מלמעלה שער הנו\"ן.\nאלא שבזה גופא (בהמשכת שער הנו\"ן) — שתי דרגות<sup data-n=\"80\">77</sup>:\nא) בחינה (תחתונה) בשער הנו\"ן, שיש לה יחס וקשר להעבודה והספירה דמ\"ט יום, עד שיתכן לומר ונאמר \"תספרו חמשים יום\", שהמשכת שער הנו\"ן שייכת והיא חלק דספירת בנ\"י.\nב) מדריגה (העליונה) בשער הנו\"ן, שאינה מתייחסת כלל לעבודת הנבראים, ובאה בדרך מתנה מלמעלה, וזהו הענין (העיקרי) דחג השבועות, זמן מתן תורת­נו, המשכה בדרך מתנה.\nועפ\"ז יש כאן ג' ענינים בהתאם ל­שלשת אופנים הנ\"ל ב\"מספר\": (א) ספירת מ\"ט יום — ענין המספר (שעל ידי בני אדם), (ב) המשכת שער הנו\"ן מלמעלה הבאה (לאחרי ו)על ידי ספירת המ\"ט יום — בגדר מספר, אבל \"לא יספר מרוב\", (ג) שער הנו\"ן הבא לגמרי בדרך מתנה הוא מה שאינו בגדר מספר (וספירה) כלל<sup data-n=\"81\">78</sup>.\nוזוהי פנימית ואמיתית המעלה המתגלית בבני ישראל בחג השבועות, זמן מתן תורתנו — שאז<sup data-n=\"82\">79</sup> נוסף על שניתנה התורה מחדש — מתגלה ה' לבני ישראל \"פנים בפנים\"<sup data-n=\"83\">80</sup>, דביקות בה' בתכלית (ע\"ד מ\"ת בפעם הראשונה, שעל כל דיבור ודיבור פרחה נשמתן<sup data-n=\"84\">81</sup>) — \"יחידה לייחדך\".\n<span data-k=\"q\">(משיחות ש\"פ במדבר תשכ\"ו, תש\"מ)</span>",[["76","73","ראה מאמרי אדהאמ\"צ פרשתנו (ע' כו) \"שענין מספר זה דבנ\"י משתווה עם ענין הספירה דז' שבועות. . הכל שרש וטעם א' הוא וע\"כ קורין פ' במדבר לפני חג השבועות ובסוף ימי הספירה\". ע\"ש באורך."],["77","74","רמב\"ם הל' תפלה פי\"ג ה\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד. וראה לקו\"ש ח\"ח ע' 1 ובהערות שם. חי\"ח ע' 18 ובהערות שם."],["78","75","לקו\"ת פרשתנו ד\"ה וספרתם וביאורו."],["79","76","אמור כג, טז."],["80","77","לקו\"ת שם בביאור הב'. וראה גם לקו\"ש ח\"ג שיחה לפ' אמור."],["81","78","ועיין לקו\"ת בלק סח, סע\"ב. ובלקו\"ת שה\"ש (כד, ג) מקשר זה עם הא דשבועות יום אחד — ראה תו\"א בהוספות (קיט, סע\"ד ואילך) \"שהוא בחי' יחידה שלמעלה מהתחלקות\". ע\"ש."],["82","79","ולהעיר מלקו\"ת פרשתנו ג, ב. מאמרי אדהאמ\"צ שם (ע' עה ואילך)."],["83","80","ואתחנן ה, ד."],["84","81","שבת פח, ב."]]],[1301430069,"<h3>שיחה ב</h3>\nא. אודות סמיכות \"דגל מחנה ראובן\" (שחנו \"תימנה\"<sup data-n=\"85\">1</sup>) לבני קהת (שחנו \"על ירך המשכן תימנה\"<sup data-n=\"86\">2</sup>) אמרו חז\"ל, והובא בפרש\"י עה\"ת, \"אוי לרשע ואוי לשכנו\".\nבפירושו של מאמר זה (\"אוי לרשע כו'\") בנוגע לעניננו מצינו כמה אופנים ומהם:\nבתנחומא<sup data-n=\"87\">3</sup> איתא: \"ומן הדרום בני קהת וסמוכין להם ראובן ושמעון וגד מכאן אמרו אוי לרשע ואוי לשכנו אלו שלשת השבטים שהיו שכנים לקרח ו­עדתו בדרום אבדו עמו במחלקותו ש­נאמר<sup data-n=\"88\">4</sup> ותפתח הארץ את פי' ותבלע אותם ואת בתיהם ואת כל אשר להם ואת כל האדם אשר לקרח ואת כל הרכוש\".\nבבמדבר רבה<sup data-n=\"89\">5</sup>: \"ג' של דרום, שהיו לבעלי מחלוקת סמוכין, אבדו עמהם ועליהם נאמר אוי לרשע אוי לשכנו ומי היו בעלי מחלוקת קרח בן יצהר בן קהת ולפי שהיו סמוכים להם ראובן ושמעון וגד היו כולם בעלי מחלוקת שכן הוא אומר<sup data-n=\"90\">6</sup> ויקח קרח בן יצהר וגו' וכן בני גד ובני שמעון אף הם היו בעלי מריבה\".\nובפרש\"י עה\"ת (עה\"פ<sup data-n=\"86\">2</sup> \"משפחות בני קהת יחנו גו' תימנה\") כתב: \"וסמוכין להם דגל ראובן החונים תימנה, אוי ל­רשע ואוי לשכנו, לכך לקו מהם דתן ואבירם ומאתיים וחמשים איש עם קרח ועדתו שנמשכו עמהם במחלוקתם\"<sup data-n=\"92\">7</sup>.\nומהחילוקים שביניהם: בתנחומא נאמר רק שנענשו יחד — \"אבדו עמו במחלקותו\"<sup data-n=\"93\">8</sup> (וע\"ז מביא הראי' מהפסוק \"ותפתח הארץ את פי' ותבלע אותם ואת בתיהם ואת כל אשר להם ואת כל האדם אשר לקרח ואת כל הרכוש\", שמדבר רק בהעונש); בפרש\"י מוסיף \"(לקו מהם כו') שנמשכו עמהם במחלוקתם\"<sup data-n=\"94\">9</sup>, היינו שה­\"רשע\" משך את \"שכנו\" גם למעשה העבירה (ולכן השמיט הראי' שבתנחומא מן הכתוב \"ותפתח הארץ את פי' גו'\"); ו­בבמדבר רבה מוסיף עוד יותר<sup data-n=\"95\">10</sup>, ש\"היו כולם בעלי מחלוקת. . אף הם היו בעלי מריבה\"<sup data-n=\"96\">11</sup>.",[["85","1","פרשתנו ב, י."],["86","2","שם ג, כט."],["87","3","פרשתנו יב (ותנחומא באבער יג). ועד\"ז בילקוט כאן רמז תרפו."],["88","4","קרח טז, לב."],["89","5","פרשתנו — פ\"ג, יב."],["90","6","קרח טז, א."],["86","2","שם ג, כט."],["92","7","הכרחו של רש\"י לפרש זה בפסוק זה (ג, כט) — אף שאין דרכו להעתיק דרשות רז\"ל — י\"ל, ש­הוא מפני הלשון \"משפחות בני קהת\", ולא \"משפחות קהת\" כמו שנאמר \"משפחות הגרשוני\" (ג, כג), ו­\"משפחות מררי. . יחנו\" (ג, לג), דמשמע שישנו ענין (בלתי רצוי) בהם שבגללו אינו רוצה לייחסם לקהת עצמו (וע\"ד פרש\"י ויחי מט, ו) — ראה באר בשדה על פרש\"י כאן. וראה בעוד מפרשי רש\"י (גו\"א. באר מים חיים (לאחי מהר\"ל). מלאכת ה­קודש. ועוד) פירושים אחרים בהכרחו של רש\"י, ולכאורה אינם ע\"ד הפשט. ואכ\"מ."],["93","8","וראה הערה 11."],["94","9","ובפרש\"י ר\"פ קרח ד\"ה דתן ואבירם מסיים \"נשתתפו עם קרח במחלוקתו\". ולהעיר דשם מתחיל פירושו עה\"פ \"פרשה זו יפה נדרשת במדרש רבי תנחומא\"."],["95","10","ואינו מביא הפסוק שבתנחומא שבו נאמר העונש."],["96","11","תוכן הפירוש נמצא גם בבמדב\"ר קרח (פי\"ח, ה). תנחומא שם ד (ות\"ב שם ח). יל\"ש שם רמז תשנ — ובכולם מסיים רק \"לקו (עמו) ואבדו מן העולם\". אבל לכאורה נראה, שמקור הדרשה ב­מקומות אלה הוא ממקום א' ונעתק ממנו להשאר."]]],[1301430070,"ב. גם יש להבין כמה דיוקים ושי­נויים בלשון רש\"י:\nא) \"וסמוכין להם דגל ראובן החונים תימנה\", ולא פירט שבדגל זה כלולים גם השבטים שמעון וגד, כבתנחומא וב­מדבר רבה.\n[ולכאורה, מה שדייק רש\"י בלשונו \"דגל ראובן\" — ולא \"דגל מחנה ראובן\" (כלשון הכתוב<sup data-n=\"85\">1</sup>, וכלשונו בפירושו ש­לאח\"ז המובא בסמוך — \"דגל מחנה יהודה\") — כי כוונתו רק לשבט ראובן לחוד, ולא לשבטים שהיו \"חונים עליו\"].\nוהתמי' גדולה יותר: בהמשך הענין, עה\"פ<sup data-n=\"98\">12</sup> \"משה ואהרן ובניו\", פרש\"י \"ו­סמוכין להם דגל מחנה יהודה והחונים עליו יששכר וזבולון טוב לצדיק טוב לשכנו לפי שהיו שכניו של משה שהי' עוסק בתורה נעשו גדולים בתורה\" (ו­מקורו בתנחומא ובמדבר רבה שם)<sup data-n=\"99\">13</sup> — הרי שכאן גבי \"טוב לצדיק\" הביא רש\"י גם את יששכר וזבולון, ומה טעם שינה רש\"י גבי \"אוי לרשע כו'\" וכתב רק \"דגל ראובן\" ותו לא? ולכאורה י\"ל ש­זהו לפי שלא מצינו (בפשוטו של מקרא) שגד ושמעון נמשכו עמו במחלוקת, וצריך להבין הטעם דחילוק זה. וכן — מהי סברת החילוק בין המדרשים ורש\"י דרק שבט ראובן נמשך במחלוקת, או שהשכינות דקרח פעלה גם על שבט שמעון ושבט גד?\nב) בתנחומא ובמדב\"ר לא פירשו מי הם משבט ראובן שנאבדו עם קרח ו­עדתו, ואילו רש\"י מפרט \"דתן ואבירם ומאתיים וחמשים איש\" (ש(רובם) הם מ­שבט ראובן<sup data-n=\"100\">14</sup>).\nג. ויש לבאר זה בהקדם, שבענין פעולת השכינות — השפעת אדם על שכינו — מצינו כמה אופנים:\nא) פעולת השכן היא בענין חיצוני לגמרי, כגון שהשכר של צדיק נמשך גם לשכינו, וכן להיפך, שהעונש שעל ה­רשע נמשך גם על שכינו<sup data-n=\"101\">15</sup>. וכפשטות לשון הגמרא (בסוף מס' סוכה<sup data-n=\"102\">16</sup>) דקנסו לכל המשמר כולו בגלל \"מרים בת בלגה שהמירה דתה\" [אע\"פ שלכאורה וכי בגללה \"קנסינן לכולה משמרה\", אלא] משום \"אוי לרשע אוי לשכינו\"<sup data-n=\"103\">17</sup>.\nב) פעולת השכן היא פעולה פנימית, כלומר, שהוא משנה את אופן הנהגתו של שכנו<sup data-n=\"104\">18</sup>, ועד שמשנה גם את מהותו<sup data-n=\"105\">19</sup>.\nג) שכינות אינה הסיבה לזה ש\"(טוב לצדיק) טוב לשכנו\" (או להיפך — \"(אוי לרשע) אוי לשכנו\"), אלא הוא סימן על מהותו של השכן (שזה שהם שכנים מורה ששניהם שייכים זל\"ז במהותם וגדרם וכיו\"ב), ופעולת השכינות היא שמגלה ומוציאה תכונה זו (של השכן) מן ההעלם והכח אל הגילוי והפועל.\nד. ויש לומר המקור לשלשה אופנים אלה, במקור הענין ד\"אוי לרשע אוי ל­שכינו\" בהלכה — בדיני נגעי בתים, וז\"ל התו\"כ<sup data-n=\"106\">20</sup>: \"וחלצו מלמד ששניהם חולצים, מיכן אמרו אוי לרשע אוי לשכנו, שניהם חולצים שניהם קוצעין שניהם מביאים את האבנים\" (ועד\"ז הוא במשנה נגעים<sup data-n=\"107\">21</sup>).\nובגדרו של דין זה ישנם ג' פירושים:\nא) \"אם כותל מפסיק בין שני בתים ונראה נגע בכותל לצד בית זה בעל ה­בית אחר צריך להטפל עמו דכתיב ו­חלצו את האבנים לשון רבים כו'\"<sup data-n=\"108\">22</sup>. שלפי פירוש זה, לא חל חיוב זה על החפצא (הכותל) של השכן, אלא זהו דין בטיפול הגברא, דשכנו של הרשע \"צריך להטפל עמו\" בחליצת האבנים ובקצוע והבאת האבנים של הרשע.\nב) הא ד\"שניהם חולצים\" היינו שה­חיוב דחליצת האבן חל גם על חלק ה­אבן של השכן (שלא נראה בו הנגע).\nובזה גופא — שני פירושים:\n(א) שיטת רש\"י (בסוף מס' סוכה<sup data-n=\"102\">16</sup>) — שהדין (שבתו\"כ) ד\"שניהן חולצין\" (מפני \"אוי לרשע ואוי לשכינו\") הוא (רק) \"באבן שבמקצוע\", וכמו שפרש\"י במ\"א<sup data-n=\"110\">23</sup> בפירוש דברי המשנה (דמס' נגעים<sup data-n=\"111\">24</sup>) \"אבן שבזוית כשהוא<sup data-n=\"112\">25</sup> חולץ חולץ את כולו\", \"אבן המנוגעת שבזוית שנראה בבית זה ובבית זה שכן דרך הזויות לתת שם אבנים גדולות המחזיקים את כל עובי הכותל ונראה משני צדדים\"<sup data-n=\"113\">26</sup> — שאבן זו יש עלי' חיוב לחלוץ את כולה (גם הצד שלא נראה בו הנגע)<sup data-n=\"114\">27</sup>.\n(ב) יש מפרשים<sup data-n=\"115\">28</sup>, שהדין ד\"חולץ את כולו\" הוא לא רק באבן שבזוית הבית (שנראית משני הצדדים), אלא בכל חלקי הכותל (שכנגד הנגע בצד השני) המפסיק בין שני הבתים, וזוהי כוונת המשנה ד\"כותל<sup data-n=\"116\">29</sup> מפסיק בין שני בתים ונראה נגע בכותל לצד בית זה\" — \"שניהם חול­צין\" (משום \"אוי לרשע אוי לשכינו\")<sup data-n=\"117\">30</sup>, שגם חבירו חייב לחלוץ האבנים שבחלק שלו (נגד הנגע)<sup data-n=\"118\">31</sup>.\nויש לומר, שג' דינים (ושיטות) אלו הם בהתאם לג' האופנים הנ\"ל בפעולת השכנות (\"אוי לרשע אוי לשכינו\"):\nלאופן הא' פעולת השכן היא פעולה חיצונית בלבד, ולכן אינו פועל על הכותל (ביתו) של השכן, אלא רק מחייב את השכן שיטפל עמו בחליצת האבנים.\nלאופן הב', \"אוי לרשע אוי לשכינו\" הוא השפעה חזקה (פנימית) יותר, ולכן צריך לחלוץ את כל האבן שבזוית הבית,",[["85","1","פרשתנו ב, י."],["98","12","שם, לח."],["99","13","ועד\"ז הוא במדרשים בפ' קרח (הנ\"ל הערה 11)."],["100","14","פרש\"י ר\"פ קרח ד\"ה ודתן ואבירם."],["101","15","ראה רש\"י לך יג, ה. שם, יד. שם יד, יב. בשלח טז, כח (מב\"ק צב, א. וראה פרש\"י שם ד\"ה בהדי). אבל ראה רש\"י וירא יט, יז. שם, יט."],["102","16","נו, ב."],["103","17","ראה זח\"ג קכב, ב. וראה ברכות נח, ריש ע\"א ועירובין יח, סע\"ב ובפרש\"י. ועוד."],["104","18","ראה זח\"א פד, סע\"א ואילך."],["105","19","וראה בארוכה ע\"ד ב' האופנים — לקו\"ש חי\"ט ע' 62 ואילך."],["106","20","מצורע יד, מ."],["107","21","פי\"ב מ\"ו."],["108","22","רע\"ב למשנה שם. ועד\"ז הוא בר\"ש שם. ק\"א לתו\"כ שם."],["102","16","נו, ב."],["110","23","חולין קכח, ב."],["111","24","פי\"ג, ב. וכ\"ה בתו\"כ מצורע יד, מה."],["112","25","כן הובא בחולין שם. ובמשנה בשינוי לשון קצת."],["113","26","ראה גם ערוך לנר סוכה שם."],["114","27","ולפ\"ז צ\"ל שהחידוש במשנה זו דפי\"ג הוא בעיקר במ\"ש \"ובזמן שהוא נותץ כו' ומניח את של חבירו נמצא חומר כו'\". ראה חסדי דוד לתוספתא נגעים פ\"ו, ח (י). וראה משנה אחרונה שבהערה הבאה."],["115","28","משנה אחרונה לנגעים פי\"ב ופי\"ג שם, ע\"פ הרע\"ב והר\"ש למשנה נגעים פי\"ג שם."],["116","29","ל' הרע\"ב בפי\"ב שם."],["117","30","וראה אבות דר\"נ רפ\"ט. ע\"ש (וראה שם כמה נוסחאות. ואכ\"מ)."],["118","31","ולכאורה כן משמע מפשטות לשון הרמב\"ם בפיהמ\"ש נגעים פי\"ב שם ומדבריו בהל' טומאת צרעת (פט\"ו ה\"ד). וכן יש לפרש בפי' רבינו הלל לתו\"כ מצורע שם, מ. וראה ביאורי הגר\"א למשנה נגעים פי\"ג שם. ואכ\"מ."]]],[1301430071,"גם החלק שלצד השכן, דהיינו שזהו כ­אילו גם אבן של השכן היא מנוגעת.\nאבל לאופן הג', צריך שכינו של ה­\"רשע\" לחלוץ האבנים שבחלק שלו, מפני שהשכינות לרשע מורה על שיי­כותו להרשע, לא מצד השפעת הרשע עליו, אלא זהו סימן שבעצם שייכים זל\"ז. ולכן בכותל זה שבו נראה הנגע בצד אחר אצל חבירו, ה\"ז מורה שגם חלק הכותל שכנגדו השייך לחבירו שייך להנגע (אף שלא נראה בו, ואינו אבן אחת עמו).\nה. ולפי זה יש לבאר גם טעם החי­לוק בין שלשת הדרשות הנ\"ל בפרשתנו — התנחומא, במדבר רבה ופרש\"י — בפירוש הענין ד\"אוי לרשע ואוי לשכי­נו\" בענין הסמיכות דדגל מחנה ראובן לבני קהת:\nהתנחומא ס\"ל כאופן הא', שפעולת השכינות (כאן) היא בעיקר לענין העונש, שהעונש שבא על הרשע נמשך גם על שכינו (ואפילו כשפועל ששכינו ישת­תף<sup data-n=\"119\">32</sup> במעשיו הרעים, ה\"ז רק מה ששכי­נו נגרר אחריו, אבל לא שנעשה עי\"ז שינוי במהותו של השכן), ולכן מביא רק ש\"אבדו עמו במחלקותו\";\nלפרש\"י פעולת השכינות אינה רק בנוגע לעונש אלא היא גם פעולה ושינוי בגוף השכן, וזהו שמוסיף רש\"י (שלא רק \"לקו מהם\", אלא) \"שנמשכו עמהם ב­מחלוקתם\"<sup data-n=\"120\">33</sup>.\n[ויש לומר, שאין כוונת רש\"י במ\"ש \"לכך לקו מהם דתן ואבירם כו' עם קרח ועדתו שנמשכו עמהם במחלוקתם\"<sup data-n=\"121\">34</sup> שהם שני ענינים — (א) שנענשו עמהם (לקו), (ב) ונמשכו עמהם במחלוקת [שלפ\"ז הול\"ל בסדר הפוך, \"שנמשכו עמהם במחלוקתם. . ולכך לקו\"<sup data-n=\"122\">35</sup>] — אלא היינו הך, ש\"לקו\" בכך \"שנמשכו עמהם במחלוקתם\"].\nועפ\"ז מבואר עוד שינוי לשון בפ­רש\"י מלשון התנחומא, שבתנחומא הל­שון \"אבדו עמו במחלקותו\", ורש\"י משנה וכותב \"שנמשכו עמהם במחלוקתם\" (לשון רבים) — דיש לומר<sup data-n=\"123\">36</sup>, שבתנחומא ההדגשה שהשכנים רק נגררו אחרי קרח, ולכן מדגיש שזוהי רק \"מחלקותו\" (של קרח), שמעשה הרע מתייחס רק להרשע ולא לשכינו; משא\"כ לפרש\"י שמצד השכינות לקרח \"נמשכו עמהם במחלוקתם\", שמרמז שהשכנים נמשכו במחלוקת, עד שנעשית גם מחלוקת השכן, מחלוקת של רבים;\nאבל שיטת הבמדב\"ר היא כאופן הג' הנ\"ל, ששכינות ה\"ז סימן על מהותם של",[["119","32","להעיר שבתנחומא קרח בענין דגל ראובן כותב בתחלת הענין \"ונשתתפו עמהם\", ומ\"מ בסיום הענין איתא (רק) \"לקו עמו ואבדו מן העולם\"."],["120","33","בלקו\"ש שבהערה 19 נתבאר (באו\"א) ב­פלוגתת רמב\"ם ורש\"י, דלרש\"י (סוכה שם) השייכות דשכינות היא רק חיצונית ואינה במהות השכן (משא\"כ להרמב\"ם, ע\"ש בארוכה). אבל להעיר דפרש\"י עה\"ת הוא (כולל) יינה של תורה, כמאמר אדה\"ז (היום יום כט שבט), ולכן י\"ל דברש\"י עה\"ת מודגשת יותר השייכות הפנימית דשכינות."],["121","34","ולא כבמדרשים דפ' קרח (הנ\"ל הערה 11) \"לקו (עמו) ואבדו מן העולם\"."],["122","35","או הול\"ל \"לפי שנמשכו כו'\" וכיו\"ב."],["123","36","אף של' רבים שבפרש\"י קאי בפשטות על עדת קרח, \"שנמשכו עמהם במחלוקתם\", י\"ל, שב­שינוי לשון רש\"י מלשון התנחומא (\"במחלקותו\", אף שגם שם נזכר לפנ\"ז קרח ועדתו<sup data-n=\"e4\">*</sup>) מרומז גם ענין הנ\"ל שבפנים."],["e4","*","אבל י\"ל כי להתנחומא העיקר בהמחלוקת הי' קרח, ולרש\"י — קרח ועדתו."]]],[1301430072,"השכנים, שבמהותם שייכים זל\"ז. וזהו שמדייק בבמדב\"ר \"היו כולם בעלי מחלוקת כו' אף הם היו בעלי מריבה\" (ולא \"שנמשכו עמהם במחלוקתם\", כב­פרש\"י), והיינו שזוהי תכונתם בעצם, והשכינות רק גלתה והוציאה תכונה זו מן ההעלם אל הפועל. ועד\"ז לפנ\"ז בצד הטוב אומר שם שה\"שבטים (דדגל מחנה יהודה) שהיו סמוכים למשה ולאהרן. . היו כולם גדולים בתורה\" (ולא (רק) \"שנעשו גדולים בתורה\", כבתנחומא ובפרש\"י) — שהשכינות גילתה<sup data-n=\"124\">37</sup> שבעצם \"היו כולם (ראויים להיות) גדולים ב­תורה\".\nויש לומר שזהו מה שמדייק ב­במדב\"ר שם (בצד הטוב) \"אשרי צדיק ואשרי שכנו\", לא \"לצדיק. . לשכנו\" כ­בתנחומא (ופרש\"י), כי לתנחומא (ופרש\"י) האושר (והטוב) שבא לשכנו הוא בא ע\"י (מצד) הצדיק והשפעתו, משא\"כ ב­במדב\"ר ה\"אשרי\" הוא על שניהם בשווה, וי\"ל שזהו מה שמדייק \"ועליהם נאמר<sup data-n=\"125\">38</sup> אשרי צדיק ואשרי שכנו\".\n[ויש להוסיף, שביאור זה בשיטת ה­במדב\"ר, ששכינות היא סימן על השיי­כות והקשר שביניהם בעצם, מתאים עם כללות תוכן דרשת הבמדב\"ר כאן, ש­מתחיל בהסגולה של המקומות (ד' הרוחות מזרח מערב צפון ודרום<sup data-n=\"126\">39</sup>) ששם חנו הדגלים<sup data-n=\"127\">40</sup>, וכלשונו \"מזרח משם האור יוצא לעולם ושם היו חונים דגל יהודה שהיו בעלי מלוכה בעלי תורה בעלי מצות לכך היו חונים שם משה ואהרן ובניו שהיו בעלי תורה בעלי מצות מכפרים על ישראל בתפלתם ובקרבנם\", וע\"ז ממשיך \"ועליהם נאמר אשר צדיק ואשרי שכנו אלו שבטים שהיו סמוכים למשה ולאהרן כו' היו כולם גדולים בתורה כו'\", והיינו שמצד מעלתם בעצם של דגל יהודה ושייכותם ל\"מזרח\", חנו דגל יהודה ברוח מסוגל דמזרח, ו\"לכך (גם) היו חונים שם משה ואהרן ובניו\"].\nו. ע\"פ הסברה זו בשיטת רש\"י מובן הטעם שרש\"י כותב רק \"דגל ראובן\" ולא הביא גם שמעון וגד:\nכיון שלשיטת רש\"י \"אוי לרשע ואוי לשכינו\" הוא מצד השפעת הרשע על הנהגת השכן ומהותו, מובן, שאינו דבר השווה בכל, ובמילא (בנדו\"ד) אין לך בו אלא חידושו, שבט ראובן שמפורש בו שנמשך במחלוקת. דכיון שהם היו עיקר הדגל, במילא מובן שהם היו \"סמוכים\" ושייכים ביותר ל(בני קהת —) קרח; משא\"כ על שמעון וגד שאינו מפורש בקרא, אין הכרח לומר<sup data-n=\"128\">41</sup> שגם בהם פעלה והשפיעה השכינות שיהיו נמשכים עמהם<sup data-n=\"129\">42</sup>; ובראובן גופא מדייק רש\"י",[["124","37","ולכן אינו בסתירה למה שמסיים גם שם \"על שהיו שכנים לתורה נעשו כולן בני תורה\", כי השכינות גילתה ענינם ותכונתם שלהם."],["125","38","שקאי לא רק על משה אהרן ובניו."],["126","39","ולשיטתי' אזיל (במדב\"ר פ\"ב, יוד) בביאור הדגלים ובמקום חנייתם לרוחות. ע\"ש באורך."],["127","40","אלא שבכללות המדרש כאן (וכן במדב\"ר שם פ\"ב) מדובר במעלת שבט ראובן ומקום חנייתו."],["128","41","ובפרט שלא מצינו בפירוש בקרא שהיו שייכים למחלוקת, כנ\"ל בפנים. וראה מפרשי הבמדב\"ר שם מה שפירשו בזה שבני שמעון וגד היו בעלי מריבה."],["129","42","ועד\"ז י\"ל גם בצד הטוב, דאף שמרובה מדה טובה כו' והשכינות פועלת גם באלו החונים עליו<sup data-n=\"e5\">*</sup> (ראה לקמן סעיף ז), מ\"מ יש מעלה ביהודה (ראש הדגל) לגבי החונים עליו, וזהו הדיוק והשינוי בהפסוקים (שהובאו ברש\"י), דבנוגע ליהודה הביא רש\"י \"יהודה מחוקקי\" דקאי על כל השבט (כדלקמן שם); ביששכר מביא רק \"ומבני יששכר יודעי בינה וגו' מאתיים ראשי סנהדראות\"<sup data-n=\"e6\">**</sup>, שהדיוק \"ומבני\", \"מאתיים\" — היינו שחלק מהשבט היו יודעי בינה, ראשי סנהדראות, ופשיטא בנוגע לזבולון שמביא \"מושכים בשבט סופר\", שנוסף ע\"ז שאינו ענין של כל השבט, רק שיש בני תורה מזבולון (שבזה שווה ליששכר), הרי גם אופן לימודם הוא רק באופן ד\"שבט סופר\", סופרים, ולא ראשי סנהדראות כב­יששכר."],["e5","*","ואולי י\"ל שהוא לפי שגם בהצדיק מדובר בג' — משה אהרן ובניו, כבהד\"ה דפרש\"י (אלא שהעיקר, כמובן, היא השכינות למשה שהי' עוסק בתורה, שמצד זה \"נעשו גדולים בתורה\"). ולהעיר שבתנחומא באבער ויל\"ש כאן מסיים \"על שהיו שכיני תורה נעשו כולם כו'\". ועד\"ז במדרשים בפ' קרח (הנ\"ל הערה 11) \"על שהיו סמוכין לתורה כו'\"."],["e6","**","ובתנחומא מביא לפנ\"ז מהכתוב \"ראשיהם מאתיים\", ומוסיף (מהכתוב) \"וכל אחיהם על פיהם\" — \"היו מסכימים הלכה על פיהם\". וראה גם תנחומא באבער ויל\"ש שם (בשינוי קצת)."]]],[1301430073,"\"לקו מהם דתן ואבירם ומאתיים וחמשים איש\", היינו שלא השפיע קרח על כל השבט אלא על מספר מועט בשבט ראובן גופא.\nומטעם זה מפרט רש\"י \"דתן ואבירם ומאתיים וחמשים איש\" ולא כתב סתם \"לכך לקו מהם עם קרח ועדתו\" — שיש לומר, שבזה שצירף \"דתן ואבירם\" לה\"מאתיים וחמשים איש\" בחדא מחתא, כוונתו להדגיש תוכן וענינה של שכינות לרשע, שפועלת ומשפיעה על מהותם של האנשים השכנים אליו, דכשם ש­פשוט ש\"דתן ואבירם\" לא רק נגררו אחרי מחלוקתו של קרח, אלא הם היו בעלי מחלוקת בטבע<sup data-n=\"130\">43</sup>, כך נפעל בה­מאתיים וחמשים איש ע\"י השכינות ל­רשע, שנעשו בעלי מחלוקת<sup data-n=\"131\">44</sup>.\nז. אלא שלכאורה משנת\"ל, שלפי התנחומא ענין השכינות הוא רק פעולה חיצונית לענין עונש לחוד, צ\"ע — שהרי מפורש בתנחומא שם לענין סמיכות דגל מחנה יהודה למקום חניית משה ואהרן: \"מכאן אמרו אשרי לצדיק ואשרי לשכי­נו אלו שלשת השבטים שהיו סמוכים למשה ואהרן נעשו גדולים בתורה, יהודה שנאמר<sup data-n=\"132\">45</sup> לא יסור. . ביששכר כתיב<sup data-n=\"133\">46</sup> ומבני יששכר יודעי בינה. . ומ­זבולון מושכים בשבט סופר<sup data-n=\"134\">47</sup> על שהיו שכיניו כולם נעשו בני תורה\", הרי שה­שכינות פעלה בהם גופא, ש\"נעשו גדו­לים בתורה. . בני תורה\"?\nויש לומר, שלדעת התנחומא יש חי­לוק בין שכן טוב לשכן רע, דשכינות לרע פעולתה רק חיצונית (בנוגע לעונש, או לכל היותר שהשכן יגרר אחריו), משא\"כ בשכן טוב — ש\"מדה טובה מרובה כו'\"<sup data-n=\"135\">48</sup> — פועלת השכינות גם על מהותו של השכן, שנשתנה לטוב, ולכן כותב התנחומא ש\"אלו שלשת השבטים שהיו סמוכים למשה ואהרן נעשו גדולים בתורה\".\nואולי יש לומר, שגם לשיטת רש\"י יש מעלה בשכינות לטוב לגבי שכינות לרע (דמרובה מדה טובה כו')<sup data-n=\"136\">49</sup>, שלכן ה­שכינות דדגל מחנה יהודה למשה ואהרן",[["130","43","ראה שמות ב, יג­יד ובפרש\"י. שם ה, כ ובפרש\"י. בשלח טז, כ ובפרש\"י."],["131","44","ראה פרש\"י קרח יז, ג."],["132","45","ויחי מט, יו\"ד."],["133","46","דה\"א יב, לב."],["134","47","שופטים ה, יד."],["135","48","סוטה יא, א. וש\"נ. רש\"י תשא לד, ז. ועוד. וכפרש\"י סוף סוכה לעניננו \"טוב לצדיק טוב לשכנו\"."],["136","49","ראה לקמן הערה 54."]]],[1301430074,"פעלה לא רק על שבט יהודה ראש המחנה — הסמוך לו (ע\"ד פעולת בני קהת על דגל ראובן לבד כנ\"ל), אלא גם על יששכר וזבולון החונים על דגל מחנה יהודה.\nויש להוסיף, שענין זה מודגש בה­שינוי בפרש\"י בהראי' בנוגע ליהודה ש­\"נעשו גדולים בתורה\" — שמביא פסוק מכתובים \"שנאמר<sup data-n=\"137\">50</sup> יהודה מחוקקי\"<sup data-n=\"138\">51</sup>, דלא כבתנחומא שמביא \"לא יסור שבט מיהודה ומחוקק מבין רגליו\"<sup data-n=\"139\">52</sup>, הנאמר (א) בחומש, ו(ב) לפני פרשתנו — כי [נוסף לכך שרש\"י מביא כתוב שבו מפורש שכן הי' בפועל, ולא הכתוב בחומש שבו רק הבטחה והברכה ש\"לא יסור\", הרי] בהפסוק בחומש לא מפורש שזהו בכל שבט יהודה, ד\"לא יסור שבט מיהודה ומחוקק מבין רגליו\" פירושו שהיו בהם \"ראשי גליות שבבבל\" ו\"נשיאי א\"י\"<sup data-n=\"140\">53</sup>, ואילו בפסוק \"יהודה מחוקקי\" ה\"ז שמו של השבט כולו, ומזה מובן שזוהי תכונתו של כל שבט יהודה. ולכן שינה רש\"י והביא כתוב זה, להדגיש, ששכינות פועלת ומשנה מהותו של השכן<sup data-n=\"141\">54</sup>.\nוי\"ל שזהו גם דיוק הלשון בפרש\"י \"טוב לצדיק טוב לשכנו\", ולא \"אשרי לצדיק ואשרי לשכינו\" (כבתנחומא), כי לשון \"אשרי\" (מלשון אושר או מלשון<sup data-n=\"142\">55</sup> שבח) יתכן<sup data-n=\"143\">56</sup> גם כאשר מקבל השפעת שכר על ידי הצדיק או שנשפע מהנהגת הצדיק, משא\"כ הלשון \"טוב\" כולל גם הפי' שינוי במהותו וגדרו שנעשה \"טוב\".\nח. ויש להוסיף בזה ע\"ד הרמז וה­דרוש:\nהשייכות דב' ענינים אלו ד\"טוב ל­צדיק טוב לשכינו\" ו\"אוי לרשע ואוי לשכינו\" שבפרשתנו, הוא לא רק מצד גדר ענין השכינות, אלא (גם) מצד תוכנם וענינם המדובר בהם: הדרך להנצל ולה­פטר מלהמשך במחלוקת<sup data-n=\"144\">57</sup> (\"אוי לרשע\"), הוא ע\"י העסק בתורה (\"טוב לצדיק כו'\"). וכן לאידך, כדי שהעסק בתורה יהי' כדבעי, ועד שהעוסקים יהיו \"גדו­",[["137","50","תהלים ס, ט. שם קח, ט."],["138","51","וכ\"ה בבמדב\"ר פי\"ח, תנחומא (ות\"ב) ויל\"ש קרח שם."],["139","52","פסוק זה הובא גם בבמדב\"ר (פ\"ג) ותנחומא באבער פרשתנו שם. וביל\"ש פרשתנו שם הובאו שני הפסוקים."],["140","53","פרש\"י ויחי שם."],["141","54","וי\"ל שלרש\"י ההוספה היא לא רק בכמות, ששכינות לטוב פועלת על כל השבט (ולא כשכינות לרע, שפועלת רק על מספר מועט), אלא גם שינוי באיכות: בשכינות לרע (\"אוי לרשע אוי לשכינו\") אף שהיא פעולה פנימית, עיקרה היא בנוגע להנהגת השכן, משא\"כ בצד הטוב ה\"ז נעשה מהותו וטבעו של השכן, ולכן פועל על כל השבט ונקבע כשמו של כל השבט.\nועפ\"ז ההוספה ברש\"י על התנחומא היא לא רק ב\"אוי לרשע אוי לשכינו\" (שלרש\"י היא פעולה פנימית, ולהתנחומא — רק פעולה חיצונית בשייכות לעונש כו'), אלא גם באופן פעולה הפנימית דשכינות לצדיק (\"טוב לצדיק טוב לשכינו\"), שאינו דומה הא דמדה טובה מרובה כו' לפי פרש\"י (לגבי שייכות פנימית ד\"אוי לרשע כו'\") למרובה מדה טובה שבתנחומא (לגבי שייכות חיצונית ד\"אוי לרשע כו'\")."],["142","55","ראה ת\"א ויצא (ל, יג) \"תושבחתא\"."],["143","56","אף שאפשר שקאי גם על אושר וטוב של עצמו, ע\"ד \"אשרי האיש\" שבריש ספר תהלים (ראה מפרשים שם). וראה ת\"א דברים (לג, כט) \"אשריך ישראל — טובך ישראל\"."],["144","57","וזוהי גם השייכות לענין הנגעים — נגעי בתים (כנ\"ל בפנים ס\"ד) — המקור שבו נאמר \"אוי לרשע אוי לשכינו\" בהלכה — כי נגעי בתים באים על לה\"ר וצרות עין (ראה ערכין טז, א. תו\"כ מצורע יד, לה. תוספתא נגעים פ\"ו, ו. רמב\"ם סוף הל' טומאת צרעת. פרש\"י סוף סוכה הנ\"ל. מפרשי המשנה נגעים פי\"ב מ\"ה) — הפירוד ומחלוקת שבין אדם לחבירו."]]],[1301430075,"לים בתורה\", והיינו שיתאחדו עם ה­תורה, הוא דוקא כאשר מתרחקים מ­מחלוקת עד קצה האחרון.\nוי\"ל שזוהי ג\"כ מטעמי השייכות דפ' במדבר לחג השבועות, ד\"לעולם קורין פרשת במדבר סיני קודם עצרת\"<sup data-n=\"145\">58</sup>, דכמו שבפ' זו מבוארים ב' ענינים הנ\"ל, עד\"ז הוא בהענין דמ\"ת:\nמבואר בחז\"ל בנוגע למ\"ת \"כל התו­רה ניתנה לעשות שלום בעולם\"<sup data-n=\"146\">59</sup>, והיינו לפעול שלום ואחדות במקום שאפשר להיות מחלוקת ופירוד; ולאידך, הסיבה לנתינת התורה היא כמ\"ש<sup data-n=\"147\">60</sup> \"ויחן שם ישראל נגד ההר\" (שהי' בר\"ח סיון), ו­ארז\"ל<sup data-n=\"148\">61</sup> דכאן \"השוו לב אחד\", ועי\"ז נעשו ישראל ראויים לקבלת התורה, וכמפורש בחז\"ל<sup data-n=\"149\">62</sup> \"בזמן שבאו לסיני חנו חני' אחת ויחן כו' אמר הקב\"ה הואיל ושנאו ישראל את המחלוקת ואהבו את השלום ונעשו חני' אחת, הרי השעה ש­אתן להם את תורתי\".\nושניהם ביחד, ביטול המחלוקת ו­הגדלות בתורה, באים ע\"י שכינות ל­צדיק, \"טוב לצדיק טוב לשכינו\",\nכי עסק התורה של צדיק הוא באופן של שלום ואחדות<sup data-n=\"150\">63</sup>, ובפרט לימוד ה­תורה לשמה, תורה כמו שהיא קשורה ומחוברת עם נותן התורה<sup data-n=\"151\">64</sup>, ולכן ע\"י השכינות לצדיק ולימוד תורתו, ה\"ז פועל שלום ואחדות בכאו\"א,\nועד שזוכים לשלום האמיתי שיהי' בביאת משיח<sup data-n=\"152\">65</sup>, שילמד תורה את כל העם כולו<sup data-n=\"153\">66</sup> באופן של אחדות, \"ובאותו הזמן לא יהי' שם כו' ולא קנאה ותח­רות\"<sup data-n=\"154\">67</sup>, גם לא קנאה ותחרות דקדושה<sup data-n=\"155\">68</sup>, \"כי מלאה הארץ דעה את ה' כמים לים מכסים\"<sup data-n=\"156\">69</sup>.\n<span data-k=\"q\">(משיחות ש\"פ במדבר תשל\"ה, תשמ\"ג, תשד\"מ; ו' תשרי תשכ\"ח)</span>",[["145","58","שו\"ע (וכ\"ה בטור) או\"ח סתכ\"ח ס\"ד. ועד\"ז ברמב\"ם הל' תפלה פי\"ג ה\"ב: המנהג הפשוט שיהו קוראין כו'."],["146","59","ל' הרמב\"ם סוף הל' חנוכה."],["147","60","יתרו יט, ב."],["148","61","מכילתא עה\"פ. וראה גם רש\"י עה\"פ. מקומות שבהערה הבאה. וראה בארוכה לקו\"ש חכ\"א שיחה א' וב' לפ' יתרו."],["149","62","דרך ארץ זוטא פרק השלום. וראה גם ויק\"ר פ\"ט, ט. פתיחתא דאיכ\"ר כ. תנחומא (באבער) יתרו ט. ועוד."],["150","63","וראה לקו\"ש חכ\"א שם (ע' 112 ואילך)."],["151","64","ע\"ד שנאמר בדוד שהי' מחבר תורה שלמעלה בקוב\"ה (ס' הבהיר סנ\"ח (סקצ\"ו) [ושם, \"כי כל שעה שאדם לומד תורה לשמה התורה של מעלה מתחברת להקב\"ה\"], הובא בלקו\"ת שלח נא, א. סה\"מ תש\"ה ע' 123. ובכ\"מ. וכ\"ה בזח\"ג רכב, ב. ועוד), ומזה שאומרים זה על דוד במיוחד מובן שהו\"ע נעלה ביותר. וראה סה\"מ מלוקט ח\"ג ע' קנה­ו. וש\"נ."],["152","65","וראה גם ד\"א זוטא שם (ועד\"ז בויק\"ר שם ספ\"ט) שבשעה שמלך המשיח נגלה לישראל אינו פותח אלא בשלום."],["153","66","ראה רמב\"ם הל' תשובה פ\"ט ה\"ב. לקו\"ת צו יז, א­ב. וראה שער האמונה פנ\"ו."],["154","67","רמב\"ם סוף הל' מלכים."],["155","68","ראה \"הדרן\" על הרמב\"ם בסה\"ש תשמ\"ט ח\"א ע' 154 ובהערות שם."],["156","69","ישעי' יא, ט. רמב\"ם שם."]]],[1301430076,"<h3>שיחה א</h3>\nא. כתב הרמב\"ם<sup data-n=\"157\">1</sup>: \"מנהג פשוט שקורים ביום טוב הראשון (של עצרת) בחודש השלישי<sup data-n=\"158\">2</sup> ומפטירין במרכבה\"<sup data-n=\"159\">3</sup> (ומקורו בברייתא דמגילה<sup data-n=\"160\">4</sup>, כמ\"ש בכסף משנה). וכן נפסק להלכה בטור ושו\"ע<sup data-n=\"161\">5</sup>.\nובטעם הדבר שמפטירין במרכבה ד­יחזקאל כ' רש\"י<sup data-n=\"162\">6</sup> (והובא בשו\"ע אדמו\"ר הזקן<sup data-n=\"163\">7</sup>) \"על שם שנגלה<sup data-n=\"164\">8</sup> בסיני ברבוא רבבות<sup data-n=\"165\">9</sup> אלפי שנאן\"<sup data-n=\"166\">10</sup>. ובאריכות יותר מבואר בלבוש<sup data-n=\"167\">11</sup> — \"מפטירין במרכבה דיחזקאל משום שבאותו היום באותו ה­מעמד הנבחר השיגו כולם למעלת הנבו­אה, וכולם קטניהם וגדוליהם שמעו אנכי ולא יהי' לך מפי הגבורה<sup data-n=\"168\">12</sup> ובלי ספק שכולם השיגו באותו מעמד מעשה מרכ­בה בכל מה שהשיג יחזקאל כענין ש­נאמר<sup data-n=\"169\">13</sup> וכל העם רואים את הקולות שרמז כולו למעשה מרכבה לכך מפטי­רין ג\"כ במעשה מרכבה שהוא מעין ה­מאורע\". ומפורש ברד\"ק ליחזקאל<sup data-n=\"170\">14</sup> בשם רז\"ל<sup data-n=\"171\">15</sup>, \"כי ישראל ביום מתן תורה ראו המרכבה כמו שראה אותה יחזקאל עד שאמרו כי קטנה שבנשיהם גדולה היא כיחזקאל<sup data-n=\"172\">16</sup> בן בוזי\"<sup data-n=\"173\">17</sup>.\nולכאורה טעם זה (על הפטרת מרכבת יחזקאל) דורש ביאור: זה שהפטרה צ\"ל \"מעין המאורע\"<sup data-n=\"174\">18</sup> פירושו הפשוט הוא שבהפטרה מדובר (לא אודות ענין צדדי שבמאורע, אלא) אודות עיקרו של ה­מאורע. ובנדו\"ד, ראיית המרכבה שבמ\"ת אינו, לכאורה, מגוף ועצם הענין דמ\"ת — שהוא התגלות השם לכל ישראל ונתינת התורה לבני ישראל;\nועפ\"ז מתאים יותר לכאורה, דל­\nקריאת פרשת מ\"ת ביום א' (\"שהוא\nענינו של יום שבו נתנה התורה\"<sup data-n=\"175\">19</sup>), יפטירו בחבקוק<sup data-n=\"176\">20</sup> \"שמדבר<sup data-n=\"177\">21</sup> במתן תו­",[["157","1","הל' תפלה פי\"ג ה\"ט."],["158","2","יתרו יט, א ואילך."],["159","3","יחזקאל סי' א."],["160","4","לא, א."],["161","5","או\"ח סי' תצד."],["162","6","מגילה שם ד\"ה במרכבה."],["163","7","או\"ח שם ס\"ד."],["164","8","בשו\"ע אדה\"ז מוסיף \"(שנגלה) הקב\"ה\". וברש\"י כ\"י (הובא בדק\"ס מגילה שם) \"בעצרת על הר סיני\"."],["165","9","בב\"ח לפרש\"י הגי' \"ברכב רבותים\", ע\"ד ל' הכתוב (תהלים סח, יח). וכ\"ה ברש\"י שברי\"ף (וברש\"י כ\"י הנ\"ל \"רבוא רבותים\"). ובשו\"ע אדה\"ז הוא כברש\"י לפנינו."],["166","10","בר\"ן מגילה שם \"לפי שירד הקב\"ה על הר סיני בהוד מרכבתו\"."],["167","11","או\"ח שם ס\"א."],["168","12","יתרו כ, ב­ג. מכות כד, רע\"א. הוריות ח, סע\"א."],["169","13","יתרו כ, טו."],["170","14","א, כח."],["171","15","ראה תנחומא צו יב. פסיקתא דר\"כ פי' יב (בחודש השלישי). פסיקתא רבתי פי' כא (עשה\"ד)."],["172","16","וראה לקמן סוס\"ג."],["173","17","ולהעיר מז\"ח יתרו (לז, סע\"ד ואילך) דראיית יחזקאל היתה בחג השבועות ביום מ\"ת. וראה ברכי יוסף ומחזיק ברכה (להחיד\"א) או\"ח סתצ\"ד אות ג. נצוצי זהר (מרגליות) לז\"ח שם אות יח."],["174","18","ל' רש\"י מגילה ל, ב ד\"ה הא כדאיתא."],["175","19","ל' אדה\"ז בשו\"ע שם ס\"ד."],["176","20","ב, כ ואילך. — ראה מגילה לא, א דעת הת\"ק \"בעצרת שבעה שבועות ומפטירין בחבקוק\". והאידנא — ה\"ז הקריאה וההפטרה דיום ב' כפי שמסיק בגמ'."],["177","21","ל' רש\"י מגילה שם."]]],[1301430077,"רה<sup data-n=\"178\">22</sup> אלו­ה<sup data-n=\"179\">23</sup> מתימן יבוא במתן תורה (משתעי<sup data-n=\"180\">24</sup>)\".\nויתירה מזו: אפילו את\"ל שגם זה הי' מעיקרי הענינים דמ\"ת — שגילוי השכי­נה הי' עם המרכבה, וכמו שכ' בלבוש (שם) \"שבאותו היום באותו המעמד כו' השיגו כולם למעלת הנבואה. . מעשה מרכבה כו'\" — הרי לכאורה עיקר ה­הדגשה אינו בראיית המרכבה, אלא בהתגלות (כבוד) השם, ומה שכולם שמעו אנכי ולא יהי' לך מפי הגבורה. ובפרט אשר איתא ברז\"ל<sup data-n=\"181\">25</sup>, שמראיית המרכבה נסתעף אח\"כ מעשה העגל ר\"ל.\nואף את\"ל שצ\"ל הפטרה במרכבה, לכאורה הי' מתאים יותר להפטיר ב­ישעי'<sup data-n=\"182\">26</sup>, מרכבה שראה ישעי', כי שם ההדגשה היא ראיית כבוד השם, \"ואראה את אדנ\"י יושב על כסא רם ונשא ושוליו מלאים את ההיכל שרפים עומדים גו'\", וע\"ד המרכבה בקיצור (וכפי שאכן מפטירים בפ' יתרו במרכבת ישעי'), משא\"כ ביחזקאל — אריכות ופרטים ע\"ד המרכבה — ובקיצור ע\"ד השם.\nויש להוסיף: גילוי כבוד השם שב­מ\"ת אינו דומה לגילוי כבוד השם שב­מרכבת יחזקאל<sup data-n=\"183\">27</sup>, אלא בדומה יותר ל­נבואת ישעי', ועד ויתרה מזה כעין דרגת משה גדול שבנביאים, כמ\"ש<sup data-n=\"184\">28</sup> \"פנים בפנים דבר ה' עמכם בהר\" (וע\"ד, כנ\"ל דאנכי ולא יהי' לך מפי הגבורה שמענום)<sup data-n=\"185\">29</sup>.\nולפי זה צריך ביאור גם בדברי הרד\"ק הנ\"ל, שבמ\"ת הי' גילוי מרכבת יחזקאל — דמאחר שהי' גילוי (כבוד) השם שלמעלה מעלה מזה — הרי שרגא בטיהרא מאי אהני?\nגם צריך ביאור בגוף הדין ש\"מפטי­רין במרכבה\" — אף, ש\"אין דורשין. . במרכבה (אפילו) ביחיד אא\"כ הי' חכם ומבין מדעתו\"<sup data-n=\"186\">30</sup>, ומטעם זה \"ונוהגין בקצת מקומות שגדול וחכם קורא זאת ההפטרה<sup data-n=\"187\">31</sup> וסמך לדבר ולא במעשה במרכבה אא\"כ הי' חכם ומבין מדעתו\"<sup data-n=\"188\">32</sup>, ועד שלדעת הת\"ק<sup data-n=\"189\">33</sup> אין מפטירין ב­מרכבה \"דלמא אתי לשיולי ולעיוני בה\"<sup data-n=\"190\">34</sup>.\nבתוי\"ט<sup data-n=\"191\">35</sup> מסביר \"טעמא דמילתא דלא חיישינן (דילמא אתא לעיוני) נ\"ל דממ\"נ אם הוא חכם יודע שהדברים אלו לב המשכיל לא ישיגם ושתיקתו יפה מ­",[["178","22","ובלבוש שם ס\"ב כ' \"שהוא ג\"כ במעשה מרכבה\"."],["179","23","חבקוק ג, ג. תיב\"ע עה\"פ. ספרי (ורש\"י) האזינו לב, יא. ועוד."],["180","24","הגהת הב\"ח שם."],["181","25","תנחומא (תשא כא) ושמו\"ר (פמ\"ב, ה) — הובא ברד\"ק יחזקאל שם."],["182","26","סי' וא\"ו."],["183","27","ראה גם זח\"ב פב, א."],["184","28","ואתחנן ה, ד. דוגמת הנאמר במשה (בהעלותך לג, יא) \"ודבר ה' אל משה פנים אל פנים\" (ועוד) — ראה רמב\"ם הל' יסוה\"ת פ\"ז ה\"ה."],["185","29","כן הוא דעת הרמב\"ן עה\"ת (יתרו כ, ז), שב' דברות אלו \"היו שומעין הדבור ומבינין אותו ממנו כאשר יבין אותם משה\". אבל לדעת הרמב\"ם (מו\"נ ח\"ב פל\"ג) ועוד, גם בב' הדברות לא הגיעו למעלת משה. וראה בארוכה בשו\"ת הרשב\"א ח\"ד סרל\"ד. ועוד. — הדיעות והשקו\"ט בזה ראה תו\"ש יתרו במילואים ס\"ב."],["186","30","משנה חגיגה יא, ב. רמב\"ם הל' יסוה\"ת ספ\"ב."],["187","31","חק יעקב שם סק\"ג."],["188","32","שו\"ע אדה\"ז שם ס\"ה."],["189","33","משנה מגילה כה, סע\"א (ובמשנה שב­משניות — ספ\"ד)."],["190","34","רע\"ב למשנה שם. וראה גם רמב\"ם ב­פיהמ\"ש שם."],["191","35","למשנה מגילה שם."]]],[1301430078,"דיבורו, ואם לאו בר הכי הוא הכי נמי אויל מחריש חכם יחשב<sup data-n=\"192\">36</sup> והחרש יחריש באולתו ולא ישאל בענינים אלו שידע שאינו כדאי שישיבו לו שום מענה\".\nאבל גם עפ\"ז צ\"ב, מהי התועלת בקריאת הענין בצבור, שכוונת הקריאה אינה רק עבור יחידי סגולה שחננם ה' תבונה המבינים במרכבה, אלא עבור כאו\"א הנמצא בבית הכנסת ושומע ה­קריאה וההפטרה, שרובם אינם בדרגא דחכם ומבין מדעתו כו' — הבנת מעשה מרכבה.\nועכצ\"ל שיש במרכבת יחזקאל ענין מיוחד שבו מודגש החידוש דמ\"ת (שלכן הי' גילוי המרכבה בעת מ\"ת), ולכן הפטרה זו היא \"מעין המאורע\", החידוש הכללי דמ\"ת (ואפילו יותר מהנבואה ד­מרכבת ישעי') — וענין מיוחד זה שב­מרכבת יחזקאל (שבזה היא \"מעין ה­מאורע\" דמ\"ת) ניתן לכאו\"א מישראל להבין<sup data-n=\"193\">37</sup> (אף שפרטי הדברים שבמרכבת יחזקאל סתומים הם, ואינם בהבנת סתם בני אדם, ד\"עומק מעשה מרכבה. . רחוק מדעת ההמון\"<sup data-n=\"194\">38</sup>).\nב. ויש לומר הביאור בזה:\nמבואר בגמ'<sup data-n=\"195\">39</sup> החילוק בין מרכבה שראה ישעי' ומרכבה שראה יחזקאל — \"כל שראה יחזקאל ראה ישעי' למה יחזקאל דומה לבן כפר שראה את המלך ולמה ישעי' דומה לבן כרך שראה את המלך\".\nוהנה לפי פשוטו נראה שהחילוק ביניהם הוא לא במה שראו אלא במה שסיפרו, דישעי' \"לא<sup data-n=\"196\">40</sup> חש לפרש את הכל, שהי' בן מלכים וגדל בפלטין ובן כרך הרואה את המלך אינו נבהל ואינו תמה ואינו חש לספר\". אבל מזה גופא שישעי' מתואר כ\"בן כרך\" שהי' בן מלכים וגדל בפלטין ויחזקאל כ\"בן כפר\", שאין מקומו בפלטין של מלך<sup data-n=\"197\">41</sup> — מובן שנבואת ישעי' עליונה ושלימה יותר<sup data-n=\"198\">42</sup>, וכמחז\"ל<sup data-n=\"199\">43</sup> שישעי' נק' \"גדול שבנביאים\"<sup data-n=\"200\">44</sup> ומדריגת נבואתו והשגתו היתה למעלה מהשגת יחזקאל.\nויש לומר, שהחילוק מודגש בזה גופא, שבדברי יחזקאל באים ומפורטים כל פרטי עניני המרכבה ואילו אצל ישעי' מודגש בעיקר ענין ראיית המלך עצמו (ולא פרטי המרכבה) — והרי זה מתאים להחילוק בפשטות בין בן כפר שראה את המלך ובן כרך שראה את המלך: בן כרך שרואה את המלך, הרי מכיון שגדל בפלטין של מלך יש לו איזו השגה בגדלות המלך, ולכן אין ראיית (ריבוי פרטי הענינים ד)מרכבת",[["192","36","משלי יז, כח."],["193","37","ראה שו\"ע אדה\"ז או\"ח סרפ\"ד סי\"א: לא יתחיל המפטיר להפטיר עד שיגמור הגולל לגלול הס\"ת כדי שגם הגולל יוכל להבין ולשמוע<sup data-n=\"e7\">*</sup> ממנו שחובה הוא על הכל לשמוע ההפטרה כמו הפרשה שבס\"ת. . ויש נוהגים. . שלא לסמוך על שמיעה בלבדה אלא הם בעצמם קורין ההפטרה כו'."],["194","38","ל' הרמב\"ם מו\"נ ח\"ג בהקדמה."],["195","39","חגיגה יג, ב."],["196","40","פרש\"י חגיגה שם."],["197","41","להעיר מתוד\"ה לבן כפר — חגיגה שם."],["198","42","ראה מו\"נ ח\"ג ספ\"ו ובמפרשים שם."],["199","43","ילקוט ישעי' רמז שפה."],["200","44","והיינו, בערך לשאר הנביאים חוץ ממשה — ראה לקו\"ש ח\"ט ע' 204 הערה 7."],["e7","*","בפרש\"י סוטה (לט, ב ד\"ה שתגלל) שלא יהיו טרודים מלשמוע. ועד\"ז בטושו\"ע שם סקמ\"ז (ס\"ז). ובזה הי' אפשר לפרש שהמצוה היא עצם השמיעה, וכן הי' אפ\"ל בלשון הב\"י או\"ח סרפ\"ד שם (בשם המרדכי) \"כדי שגם הגולל יבין אל ה­מפטיר\". אבל מהכפל בשו\"ע אדה\"ז \"להבין ו­לשמוע\" משמע שמפרש גם להבין, כפשוטו. ועצ\"ע."]]],[1301430079,"המלך וכיו\"ב מוסיפה אצלו הפלאה ב­רוממות המלך, כ\"א רק ראיית המלך עצמו; משא\"כ בבן כפר שאין לו ידיעה והשגה בגדולת המלך, כאשר רואה עניני גדולתו וגודל יקר מלכותו, ה\"ז מעורר אצלו התפעלות מגדולתו של המלך (אף שגם אז אין לו השגה במהות גדלות המלך)<sup data-n=\"201\">45</sup>.\nוכן הוא החילוק בין ישעי' ליחזקאל — דנבואת ישעי', \"גדול שבנביאים\", היתה כבן כרך שיש לו השגה בגדלות המלך ולכן גדולת מרכבתו של מלך אינה תופסת מקום אצלו, משא\"כ יחזקאל, שעיקר ראייתו היתה במרכבה, אלא שראי' זו הביאתו לידי איזו ידיעה והתפעלות מגדלות המלך עצמו.\nויש להתאים זה עם המבואר בספר עבודת הקודש<sup data-n=\"202\">46</sup> בביאור מרכבת יחזקאל, וז\"ל: \"מתוך שראה והשיג במר­כבה התחתונה ידע בעליונה. . כי יש כסא למעלה מכסא ומרכבה למעלה מ­מרכבה ורוכב למעלה מרוכב וכבוד למעלה מכבוד, ומתוך שראה ארבע חיות למטה ידע והכיר כי יש דוגמתן למעלה בייחוד האמיתי כי כן הי' מקובל ומתוך שראה למטה חשמל מקיף לכסא הנקרא חשמל החיצון ידע שיש למעלה דוגמתו חשמל הפנימי כו' ועל דרך זה כל מה שראה למטה ידע שיש דוגמתו למעלה\" — והולך ומפרש (בעבודת ה­קודש<sup data-n=\"203\">47</sup>) בנוגע לכל הכתובים איך ש­יגידו בתחתונה וירמזו אל העליונה\".\nכלומר: מרכבת יחזקאל תוכנה ו­ענינה הוא שהענינים שלמטה הם \"דמות העליונות\"<sup data-n=\"204\">48</sup>, ולכן מפרט (יחזקאל) ו­מאריך בכל פרטי המרכבה ובאופנה, ומדגיש<sup data-n=\"205\">49</sup> \"ומתוכה דמות גו' דמות אדם להנה. . ודמות פניהם גו' ודמות החיות וגו'\".\nוי\"ל שזהו דיוק הלשון \"דמות\", שמורה על דבר והיפוכו: מצד אחד ראיית הדמות מורה שאינו רואה את הדבר כ\"א \"דמות\" שלו בלבד, וכמשל המסתכל במראה שרואה בה דמות הדבר בלבד; ולאידך מורה \"דמות\" שאין בה שום מציאות כ\"א דמות של הדבר. והיינו דלא רק דע\"י ראיית הדמות אפשר לידע בדיוק איך שנראה הדבר עצמו, אלא יתירה מזו — שכל \"מציאות\" ה\"דמות\" אינה מציאות כ\"א זה שהיא דומה להדבר.\nוזהו מה שראה יחזקאל בכל פרטי הענינים דלמטה, שכל ענינם הוא זה ורק זה שהם \"דמות העליונות\"<sup data-n=\"206\">50</sup>.\nמשא\"כ ישעי', להיותו בן כרך — לא מפרש ומפרט כל הפרטים של המרכבה. כי מלכתחילה לא ראה ה\"דמות\" כפי שהיא למטה, כ\"א את עצם הדבר של­מעלה. דלהיותו בן כרך שגדל בפלטין, הרי כל הענינים מלבד המלך לא תפסו מקום אצלו, עד שלא הורגשו אצלו כמציאות. ולכן אומר \"ואראה את אדנ\"י",[["201","45","להעיר עד\"ז — מתניא פמ\"ב (סא, א) בהגהה."],["202","46","ח\"ד ספי\"ח."],["203","47","שם פי\"ט."],["204","48","ל' עבודת הקודש שם בביאור הכתוב \"ומתוכה דמות ארבע חיות\"."],["205","49","א, ה­יג."],["206","50","להעיר מצפע\"נ למו\"נ ח\"ג פ\"א (נדפס בצפע\"נ עה\"ת בסוף ספר דברים) בביאור מ\"ש הרמב\"ם שם במרכבת יחזקאל, ד\"לפי ביאור רבינו בא הישג יחזקאל כל הנהגה לפי גדר עילה ועלול, גדר צבאות, היינו גדר טבע והנהגה, ומ\"מ הוא קודש\". ע\"ש בארוכה. ולפי זה, המבואר בפנים מתאים גם לדעת המו\"נ."]]],[1301430080,"יושב על כסא רם ונשא\" ומפרט רק השרפים שהם \"עומדים ממעל לו\", היינו שזהו פרט בראיית \"אדנ\"י יושב על כסא\".\nג. עפ\"ז מובנת השייכות דההפטרה במרכבת יחזקאל בהמשך לקריאת פר­שת מ\"ת ביום שבו נתנה תורה — לפי שהוא מענינו של יום ומעין המאורע, היינו תוכן החידוש דמ\"ת:\nגילוי השכינה שבמתן תורה לא הי' רק דבר שלפי שעה, אלא בשביל שעי\"ז בנ\"י יתעלו על ידי עבודתם<sup data-n=\"207\">51</sup> ולידבק בהקב\"ה, שהכח ע\"ז בא להם מהתגלות השם במ\"ת, שעי\"ז נקבע בלבנו לתמיד מעמד הר סיני, שעינינו ראו ולא זר כו'<sup data-n=\"208\">52</sup>.\nוזהו גם תוכן דברי המדרש<sup data-n=\"209\">53</sup>, שירי­דת ה' על הר סיני לא היתה רק גילוי לפי שעה, אלא התחלה דמצב העולם חדש לגמרי, ע\"י הביטול לתמיד של הגזירה, דעליונים לא ירדו לתחתונים ותחתונים לא יעלו לעליונים — וה­תוצאות של ביטול גזירה זו ובגלוי ה\"ז תלוי וע\"י עבודתם של ישראל.\nביאור הענין:\nמזה גופא שמתארים אותם בשם \"עליונים\" ו\"תחתונים\" מובן שבעצם ישנה שייכות ויותר מזה — קשר ביניהם. וב­פרט ע\"פ המבואר בכ\"מ כי המציאות של כל נברא שלמטה הרי שרשו ומקורו למעלה וממנו נשתלשל, דשורש השור שלמטה הוא מפני שור שבמרכבה וכיו\"ב — ועד לשרשו ומקורו שהוא דבר ה' ורוח פיו ית' המהווהו ומחייהו בכל רגע ורגע<sup data-n=\"210\">54</sup>. וגם \"צמיחתו\" לאח\"ז ה\"ז בא ממזלו שלמעלה כמחז\"ל<sup data-n=\"211\">55</sup> אין לך כל עשב כו' שאין לו מזל כו' גדל.\nאלא שלפני מ\"ת היתה \"גזירה\" — מלשון גזר וחתך — בין הנברא שלמטה ומקורו בעליונים, ו(במ\"ת) כאשר בטלה הגזירה ניתן הכח לכל או\"א ע\"י עבודתו<sup data-n=\"212\">56</sup> להמשיך ו\"לראות\" בכל נברא שלמטה את שרשו ומקורו שלמעלה, עד שמגלה עי\"ז אמיתית מציאותו, שלא נמצא אלא מאמיתת המצאו<sup data-n=\"213\">57</sup>.\nוכיון שכל התחלות קשות כו'<sup data-n=\"214\">58</sup>, לכן הי' במ\"ת (שאז \"ואני המתחיל\"<sup data-n=\"209\">53</sup>) גילוי נעלה ביותר\n[כמ\"ש בזהר<sup data-n=\"216\">59</sup> \"בההוא שעתא כל רזין דאורייתא וכל רזין עילאין ותתאין לא אעדי מינייהו בגין דהוו חמאן עינא בעינא זיו יקרא דמריהון מה דלא הוה כההוא יומא מיומא דאתברי עלמא דקב\"ה אתגלי ביקרי' על טורא דסיני. ואי תימא הא תנינן דחמאת שפחה על הים מה דלא חמא יחזקאל נביאה יכול",[["207","51","להעיר מס' השיחות תש\"ה (ע' 102) דשלשה דברים ניתנו בשעת מ\"ת: א) גליא דתורה, ב) סתרי תורה, ג) כח לעבודה. ע\"ש."],["208","52","ראה רמב\"ם הל' יסוה\"ת פ\"ח. רמב\"ן עה\"ת יתרו כ, ז. ועוד."],["209","53","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["210","54","ראה תניא שער היחוד והאמונה פ\"א ופ\"ג."],["211","55","ב\"ר פ\"י, ו. זח\"ב קעא, ב. וראה גם זח\"א רנא, א. מו\"נ ח\"ב פ\"י. וראה מאמרי אדה\"ז על מארז\"ל (ע' קלה ואילך). מאמרי אדהאמ\"צ דברים ח\"ג (ע' תתעו ואילך)."],["212","56","ראה דברי כ\"ק אדמו\"ר מהר\"ש (התמים חו' ג ע' כז [קל, א]), דזה שכ' אדה\"ז בשער היחוד וה­אמונה (רפ\"ג) \"אבל אילו ניתנה רשות לעין לראות כו' לא הי' גשמיות הנברא וחומרו וממשו נראה כלל לעינינו\", הכוונה בזה — \"ראיית העין\" בלי עבודה, אבל ע\"י עבודה ביכולת כל אחד לראות כו'. ע\"ש."],["213","57","רמב\"ם ריש הל' יסודי התורה."],["214","58","ראה מכילתא ופרש\"י יתרו יט, ה."],["209","53","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["216","59","ח\"ב (צג, סע\"ב ואילך). וראה גם זהר שם פב, א."]]],[1301430081,"כההוא יומא דקאימו ישראל על טורא דסיני, לאו הכי, בגין דההוא יומא דקיימו ישראל על טורא דסיני אעבר זוהמא מינייהו\" — שגם בעת קריעת ים סוף \"חמאת שפחה על הים מה דלא חמא יחזקאל נביאה\", ובמ\"ת הי' יתירה מזה]\n— אבל עיקר הכוונה לעולמים היתה \"מרכבת יחזקאל\", לגלות בעולם איך שכל המציאות של כל פרטיו אינה אלא \"דמות\" למציאות הפרט למעלה [ולכן הי' אז גילוי המרכבה]. ולכן נקבע ענין זה דוקא להפטרה דיום מ\"ת.\nומתורצת ג\"כ השאלה הנ\"ל — מדוע קבעו הפטרה במעשה מרכבה שלא ניתן להבין לרוב בנ\"א, כי אף שפרטי עניני המרכבה שנתפרטו בההפטרה אינם ב­הבנה והשגה כנ\"ל, הרי בכחו של כאו\"א להבין ולעמוד על תוכנה הכללי של ההפטרה, שכל פרטי המרכבה שראה יחזקאל הם \"דמות\", שעל ידם ידע יחזקאל והכיר ב\"דמות העליונות\".\nד. וע\"פ זה יש לבאר ג\"כ טעם ה­מנהג \"לסיים (הפטרה זו) בפסוק<sup data-n=\"217\">60</sup> ותשאני רוח גו'\"<sup data-n=\"218\">61</sup> (שמדלגין קאפיטל וחצי) \"אף שאינו כתוב כלל אצל ה­מרכבה\"<sup data-n=\"218\">61</sup>, ואדרבה, לפי פשוטן של מקראות<sup data-n=\"220\">62</sup> מדבר הכתוב ע\"ד הסתלקות כבוד השם לאחר הדיבור — כי בפסוק זה (\"ותשאני רוח ואשמע אחרי קול רעש גדול ברוך כבוד ה' ממקומו\") מודגש עיקר החידוש ותוכן הנ\"ל דמרכבת יחזקאל.\nוהענין:\nאחד החילוקים דמרכבת ישעי' ומרכ­בת יחזקאל הוא, שבמרכבת יחזקאל מדובר ע\"ד החיות והאופנים, ובמרכבת ישעי' — ע\"ד השרפים. והרי האופנים וחיות עבודתם ברעש, כידוע ש\"קול רעש גדול\" זה הוא מהאופנים כמ\"ש בברכות ק\"ש \"והאופנים וחיות הקודש ברעש גדול מתנשאים לעומת השרפים לעומתם משבחים ואומרים ברוך כבוד ה' ממקומו\", משא\"כ עבודת השרפים אינה ברעש.\nובטעם הדבר מבואר<sup data-n=\"221\">63</sup>, שהחילוק בין שרפים ואופנים הוא ע\"ד החילוק בין בן כרך שראה את המלך ובן כפר שראה את המלך: הרעש בא מצד החידוש, ולכן ה\"ז דוקא אצל בן כפר שראה את המלך, שראיית המלך ורוממותו גורמת אצלו רעש, מחמת החידוש שבדבר, משא\"כ בבן כרך שאינו חידוש בעיניו (כ\"כ), אין אצלו רעש. ועד\"ז הוא החילוק בין השרפים והאופנים.\nובפרטיות יותר<sup data-n=\"222\">64</sup>:\nהשרפים משיגים איך שהקב\"ה הוא קדוש ומובדל מן העולמות והעולמות אינם תופסים מקום לגבי', אבל האופנים משיגים איך שהקב\"ה מהווה כל דבר מאין ליש, ומציאות העולם נתהווה מאמיתת המצאו, ומשום זה ההתפעלות שלהם היא ברעש גדול, מפני שמשיגים האמת איך שהוא היפך מהנראה לעינים, שהעולם נראה ליש ודבר, ובאמת הוא בטל בתכלית, ולכן בא הרעש גדול, כמו אדם שמשיג השגה חדשה והפכית ממה שנראה לעינים ולכן יתהווה אצלו רעש.",[["217","60","יחזקאל ג, יב."],["218","61","ל' אדמו\"ר הזקן בשו\"ע סתצ\"ד ס\"ד."],["218","61","ל' אדמו\"ר הזקן בשו\"ע סתצ\"ד ס\"ד."],["220","62","ראה מפרשים שם."],["221","63","ראה לקו\"ת ברכה צז, ב. ד\"ה מגילה נקראת באוה\"ת הוספה למג\"א ע' מג (אוה\"ת מג\"א (הוצאת תש\"נ) ע' ערה) ואילך ובסה\"מ תרכ\"ט ע' עה ואילך. ועוד. וראה מו\"נ שם פ\"ו."],["222","64","סה\"מ תרס\"א ע' קצח."]]],[1301430082,"וזהו תוכן החידוש הנ\"ל דמתן תורה, שגם במציאות העולם, בתחתונים, יהי' ניכר אמיתיות מציאותו.\nה. ע\"פ הנ\"ל יש לבאר ג\"כ זה שב­מ\"ת היו \"קולות וברקים וקול שופר חזק מאד ויחרד כל העם אשר במחנה\"<sup data-n=\"223\">65</sup>:\nאם נפרש כפשוטו לבד — שכוונת ומטרת הקולות וברקים היתה לפעול יראה וחרדה בעולם, בבני ישראל, הרי לכאורה גילוי כבוד השם עצמו, \"אתם ראיתם כי מן השמים דברתי עמכם\"<sup data-n=\"224\">66</sup>, די לפעול בהם יראה וחרדה זו, ו­אדרבה, החרדה מחמת קולות וברקים כו' היא חרדה השייכת בעיקר להגוף ואילו היראה וחרדה מצד גלוי כבוד השם פנים בפנים, היא פעולה עמוקה וגדולה ופועלת (גם) בהנפש ועד בנשמ­תא דנשמתא. ובכ\"ז היו קולות וברקים כו' ענין עיקרי בההתגלות דמ\"ת?\nאלא דהן הן הדברים, שתוכן ענין ה\"רעש\" במתן תורה (הקולות ורעש כו', ויחרד כל העם אשר במחנה, ובלשון הכתוב<sup data-n=\"225\">67</sup> \"ארץ רעשה\") אין זה רק רעש הנשמע לאוזן הגשמי שהי' כפרט נוסף בהכנה והקדמה למתן תורה, אלא הוא רעש בתוכנו הרוחני: מחמת החידוש דמ\"ת שבכל פרט בהבריאה וכל הברי­אה כולה הי' נראה שאמיתית מציאותה היא לא מה שנראה ונגלה לעיני בשר, שהוא דבר ויש בפני עצמו, אלא מקורו שנתהווה מאמיתת המצאו דהבורא.\nו. תורה היא מלשון הוראה<sup data-n=\"226\">68</sup>, וכ\"ש וק\"ו כשמגיע היום בשנה שבו ניתנה תורה לישראל, דהימים האלה נזכרים ונעשים<sup data-n=\"227\">69</sup> — שכאו\"א מישראל צריך ללמוד הוראה מקריאת התורה וההפטרה דיום חג השבועות. וע\"פ הנ\"ל יש לומר, שיש בזה הוראה בשני הפרטים, בעבו­דתו בעצמו ובעבודתו בזולת:\nאף שבנוגע למעשה מרכבה נאמר \"אין דורשין כו' אא\"כ הי' חכם ומבין מדעתו\"<sup data-n=\"186\">30</sup>, ה\"ז דוקא \"במעשה מרכבה\" כפי שהם בתורה שבכתב ושבתושבע\"פ — כתובה בלשון הסוד שבתורה<sup data-n=\"229\">70</sup> (פרטי מרכבת יחזקאל, ספרא דצניעותא וכו'); אבל בנוגע ללימוד פנימיות התורה כפי שנתגלתה על ידי האריז\"ל ונתבארה על ידו, ואמר שבא הזמן ש\"מצוה לגלות זאת החכמה\"<sup data-n=\"230\">71</sup>, הרי כאו\"א מחוייב ב­זה<sup data-n=\"231\">72</sup>, ובפרט לאחרי עוד זמן — שנת­בארה בתורת החסידות, ובמיוחד ולאח­רי שנתבארה בלשון חכמי תורה בלשון דהבנה והשגה באופן ד\"יתפרנסון\"<sup data-n=\"232\">73</sup>, הרי זו \"מצוה<sup data-n=\"233\">74</sup> רמה ונשאה. . דע<sup data-n=\"234\">75</sup> את אלקי אביך כו' ומביאה ללב שלם\".",[["223","65","יתרו יט, טז."],["224","66","שם כ, יט."],["225","67","תהלים סח, ט."],["226","68","זח\"ג נג, ב. גו\"א ר\"פ בראשית בשם הרד\"ק."],["227","69","מג\"א ט, כח. וראה רמ\"ז בספר תיקון שובבים, הובא ונתבאר בספר לב דוד (להחיד\"א) פכ\"ט."],["186","30","משנה חגיגה יא, ב. רמב\"ם הל' יסוה\"ת ספ\"ב."],["229","70","משא\"כ רוב התורה — אף שכל התורה (כדברי השל\"ה (יג, ב. קסא, א ואילך. וראה עשרה מאמרות מאמר חקור דין ח\"ג פכ\"ג)) מדברת בעליונים ורק מרמזת בתחתונים — כתובה ונאמרה בלשון בנ\"א דוקא."],["230","71","תניא אגה\"ק סכ\"ו (קמב, ב)."],["231","72","ראה הל' ת\"ת לאדה\"ז פ\"א סוס\"ד. וראה ג\"כ הקדמת הרח\"ו לשער ההקדמות."],["232","73","לשון התקו\"ז (ת\"ו בסופו). וראה הקדמת מקדש מלך לזהר \"כשיפורש להם אמיתות מאמריו\". וראה כסא מלך לתקו\"ז שם — הועתק בלקו\"ש חט\"ו ע' 42 הערה 9."],["233","74","ל' אדה\"ז בתניא קונטרס אחרון ד\"ה להבין מ\"ש בפע\"ח (קנו, ב. וראה לוח התיקון שם)."],["234","75","דה\"א כח, ט."]]],[1301430083,"ועי\"ז באים לראות ולהכיר בכל דבר ודבר אמיתית מציאותו שנתהווה מ­אמיתת המצאו.\nועד\"ז מובן גם בנוגע לעבודה עם הזולת, שהפצת התורה והיהדות בתוככי כלל ישראל צריכה להעשות מתוך קול רעש גדול<sup data-n=\"235\">76</sup>,\nואדרבה, כאשר עבודת האדם היא עדיין בפנים, בד' אמות של תורה וקדושה, מספיק לפעמים אופן העבודה כמו שהיא, בקול דממה דקה;\nאבל כאשר יוצאים מחוץ לד' אמות הנ\"ל, ב\"קול המונה של רומי\"<sup data-n=\"236\">77</sup>, הרי בכדי לבטל קול זה הוא ע\"י קול רעש גדול דקדושה, ועי\"ז זוכים בקרוב ל­\"יתקע בשופר גדול\"<sup data-n=\"237\">78</sup> גדול דוקא שופר דלעתיד, ביחד עם \"קול מבשר מבשר ואומר\"<sup data-n=\"238\">79</sup> — מבשר הגאולה, בקרוב ממש.\n<span data-k=\"q\">(משיחות ש\"פ נשא תשמ\"ה, ש\"פ יתרו תש\"מ)</span>",[["235","76","ראה בארוכה עד\"ז בלקו\"ש חט\"ז ע' 340 ואילך."],["236","77","לשון הגמרא מכות כד, סע\"א."],["237","78","ישעי' כז, יג. וראה לקו\"ת ר\"ה ד\"ה והי' ביום ההוא (נח, א ואילך)."],["238","79","נוסח הושענות דהושענא רבה."]]],[1301430084,"<h3>שיחה ב</h3>\nא. אודות כריתת הברית בשעת מ\"ת, איתא בגמ'<sup data-n=\"239\">1</sup> שאבותינו \"לא נכנסו לברית אלא במילה וטבילה והרצאת דם (קרבן). . מילה דכתיב<sup data-n=\"240\">2</sup> כי מולים היו כל העם היוצאים. . הרצאת דמים דכתיב<sup data-n=\"241\">3</sup> וישלח את נערי בני ישראל. . טבילה מנלן דכתיב<sup data-n=\"242\">4</sup> ויקח משה את הדם<sup data-n=\"243\">5</sup> ויזרק על העם ואין הזאה בלא טבילה\".\nוהנה הפסוקים \"וישלח את נערי בני ישראל. . ויקח משה את הדם גו'\" נאמרו בס\"פ משפטים, ופליגי תנאים במכילתא<sup data-n=\"244\">6</sup> בזמנה של פרשה זו: לפי הת\"ק הי' כ\"ז בחמישי בסיון, שאז בנה משה מזבח והקריב הקרבנות וזרק ה­דמים כו' (וכן מובא בש\"ס במס' שבת<sup data-n=\"245\">7</sup>, וכ\"כ רש\"י בפירושו על התורה<sup data-n=\"246\">8</sup>); אבל \"ר' יוסי ברבי יהודה אומר בו ביום נעשו כל המעשים\", שבפשטות \"בו ביום\" היינו ביום דמתן תורה.\n[ברמב\"ן עה\"ת<sup data-n=\"247\">9</sup> פי' דברי ר' יוסי ב\"ר יהודה \"בו ביום נעשו כל המעשים\" — \"כלומר בו ביום לאחר מתן תורה\", היינו בשביעי בסיון (וזהו לשיטתו (וכ\"כ בעוד מפרשים<sup data-n=\"248\">10</sup>) שהפרשיות (דיתרו ומשפטים) נאמרו על הסדר, והדינים דפ' משפטים נאמרו ביום מ\"ת אחרי עשה\"ד, ובו ביום אמרו ישראל \"כל אשר דבר ה' נעשה\"<sup data-n=\"249\">11</sup>, וביום המחרת (בשביעי בסיון) — \"ויש­כם<sup data-n=\"250\">12</sup> (משה) בבקר ויבן מזבח גו' ויזבחו גו' ויקח ספר הברית גו' ויאמרו גו' נעשה ונשמע ויקח משה את הדם ויזרוק על העם גו'\").\nאבל במדרש לקח טוב<sup data-n=\"251\">13</sup> מפורש שה­דיעה ד\"כל אלו המעשים בו ביום נעשו\", היינו בבוקר יום מ\"ת קודם עשרת הדב­רות<sup data-n=\"252\">14</sup>, וכן היא פשטות הפירוש של דברי ר' יוסי \"בו ביום נעשו\", שמשמעו",[["239","1","כריתות ט, רע\"א (וראה יבמות מו, א­ב). רמב\"ם הל' איסורי ביאה רפי\"ג. רש\"י עה\"ת משפטים כד, ו."],["240","2","יהושע (ה, ה). — \"א\"נ מהכא (יחזקאל טז, ו) ואעבור עליך ואראך מתבוססת בדמיך גו'\" (כריתות שם). וברמב\"ם שם \"מילה היתה במצרים שנאמר (בא יב, מח) וכל ערל לא יאכל בו\" (וראה גם פיה\"מ שלו בהקדמה לסדר קדשים). וכבר שקו\"ט במעשה רוקח לרמב\"ם שם (ועוד) בטעם שלא הביא הרמב\"ם הכתוב שהובא בש\"ס. ואכ\"מ."],["241","3","משפטים כד, ה."],["242","4","שם, ח. — וכ\"ה מסקנת הגמ' יבמות שם (ע\"ב). וברמב\"ם שם \"שנאמר (יתרו יט, י. וראה רמב\"ן שם) וקדשתם היום ומחר וכבסו שמלותם\", כהקס\"ד בגמ' שם. וראה ב\"ח לטיו\"ד ר\"ס רסח (וב­עוד מפרשים), שכוונת הגמ' היא רק שאין להוכיח מכתוב זה שהכוונה לטבילה (כי דלמא משום נקיות היתה), אבל למסקנא שהיתה טבילה (כי אין הזאה בלא טבילה), הרי זו כוונת הכתוב \"וכבסו\", לענין הטבילה. וראה לקמן הערה 15."],["243","5","כ\"ה בשטמ\"ק (כבקרא). ובגמ' לפנינו \"חצי הדם\" (כל' הכתוב שם, ו)."],["244","6","יתרו יט, י."],["245","7","פח, א. וראה גם חגיגה ו, א וברש\"י שם ד\"ה ישנה (ותוד\"ה ר\"ע — שם ע\"ב)."],["246","8","משפטים כד, ד. וראה גם רש\"י יתרו יט, א."],["247","9","משפטים שם, א. וראה גם פי' \"זה ינחמנו\" למכילתא על אתר."],["248","10","ראב\"ע (שם ויתרו כ, כא), רשב\"ם, אברבנאל ועוד משפטים שם. וראה גם תיב\"ע שם."],["249","11","משפטים שם, ג."],["250","12","שם, ד ואילך."],["251","13","יתרו יט, י. ע\"ש באורך. — וראה תו\"ש משפטים שם במילואים סכ\"ז."],["252","14","כ\"ה בלקח טוב שם. וראה מרכבת המשנה על המכילתא שם. ואכ\"מ."]]],[1301430085,"ביום הידוע (והרי לא נזכר בכל ההמשך דדברי המכילתא שם — היום שלאחרי מ\"ת)].\nולכאורה דיעה זו, שטבילת בנ\"י (והרצאת דמים) היתה \"בו ביום\" דמ\"ת<sup data-n=\"253\">15</sup>, דורשת ביאור — כיצד הותרו ישראל לטבול<sup data-n=\"254\">*15</sup> לשם גירות ביום זה, והרי אחז\"ל (במס' שבת<sup data-n=\"255\">16</sup>) של\"כולי עלמא בשבת ניתנה תורה לישראל\", והלכה פסוקה ברמב\"ם<sup data-n=\"256\">17</sup> ושו\"ע<sup data-n=\"257\">18</sup> שאין מטבילין גר בשבת<sup data-n=\"258\">19</sup> (וכבר נצטוו על שבת ב­\nמרה<sup data-n=\"259\">20</sup> או באלוש<sup data-n=\"260\">21</sup>)?\n[מצינו במפרשי המכילתא<sup data-n=\"261\">22</sup> שהקשו (על דברי ר' יוסי ב\"ר יהודה) איך (בנה מזבח ו)הקריב קרבנות בשבת? ותירצו דריבר\"י ס\"ל דעולות תמיד היו ותמיד דוחה שבת<sup data-n=\"262\">23</sup>. אבל צ\"ע בנוגע (לבנית מזבח<sup data-n=\"263\">24</sup> ו)לטבילת (גירות) בני ישראל, ש­אין זה ענין קרבן ציבור].\nבפשטות י\"ל שר' יוסי ב\"ר יהודה (ב­מכילתא) אזיל לשיטת המכילתא (במ\"א<sup data-n=\"264\">25</sup>) שששי בסיון חל בששי בשבת (וכן מפו­רש בפרקי דר\"א<sup data-n=\"265\">26</sup> שמ\"ת הי' ביום ששי בשבת) — ולא כשיטת הש\"ס (דלכו\"ע בשבת ניתנה תורה). אבל במדרש לקח טוב שם<sup data-n=\"251\">13</sup> מפורש \"שבת קבלו עשרת הדברות. . והשכים משה בבקר ובנה מזבח כו' שלא קיבלו ישראל את התורה אלא ע\"י טבילה והזאה. . וכל אלו ה­מעשים בו ביום נעשו\", הרי מפורש ש­\"כל אלו המעשים\" נעשו ביום השבת<sup data-n=\"267\">27</sup>.",[["253","15","דכיון שהטבילה היתה \"כדי לקבל הזאה\" (תוד\"ה דאין הזאה — יבמות שם), מסתבר שהיתה בסמיכות לההזאה [משא\"כ לפמ\"ש הרמב\"ם (כנ\"ל הערה 4) שנלמד מ\"וקדשתם גו' וכבסו גו'\", שזה הי' ביום ד' וביום ה' (מכילתא יתרו שם) — לא היתה הטבילה בשבת<sup data-n=\"e8\">*</sup>].\nובכל אופן, גם את\"ל שהטבילה היתה לפנ\"ז, סו\"ס נכנסו לברית ב\"אותו יום\" שאז הייתה \"הרצאת דם\"* (ובתוס' שם — ע\"י \"הזאה\". ע\"ש), ויש בזה משום \"תיקוני גברא\" (ראה לקמן סעיף ב)."],["254","*15","להעיר מחי' חת\"ס לשבת פו, א (ד\"ה ומסוגיא זו)."],["255","16","פו, סע\"ב. וראה סדר עולם ספ\"ה."],["256","17","הל' איסו\"ב שם ה\"ו (וראה לקמן בפנים ריש ס\"ב)."],["257","18","יו\"ד סרס\"ח ס\"ד."],["258","19","כדעת ר' יוסי ביבמות שם (מו, ב).\nבב\"ח לטיו\"ד שם (ד\"ה וכל עניניו קרוב לסופו) תמה על הרי\"ף רא\"ש וטור, שהשמיטו דין איסור טבילת גר בשבת, וכ' שס\"ל שאין בזה משום תיקוני גברא כיון ד\"נראה כמיקר\" (כהא דביצה יח, סע\"א לענין טבילה מטומאה. ולא ס\"ל כחילוק התוס' ד\"ה תקוני ביבמות שם), ומסיים שכ\"כ בסמ\"ג בשם בה\"ג שמותר לכתחילה להטביל גר בשבת.\nאבל עצ\"ע לפי פסק הרמב\"ם והשו\"ע, כבפנים."],["259","20","שבת פז, ריש ע\"ב. ירושלמי ביצה פ\"ב ה\"א. רש\"י בשלח טו, כה. משפטים כד, ג. ואתחנן ה, יב."],["260","21","ירושלמי ביצה שם. סדר עולם פ\"ה. ועוד."],["261","22","מרכבת המשנה על מכילתא יתרו שם, י. וראה תו\"ש שצויין בהערה 13."],["262","23","ובתו\"ש שם מוסיף שהקרבנות היו בגדר קרבן ציבור (שזמנו קבוע). ע\"ש. ולהעיר מלשון הרמב\"ם שם ה\"ג \"וקרבן שנאמר. . ויעלו עולות על ידי כל ישראל הקריבום\"."],["263","24","וראה תו\"ש שם הטעם שהותר לבנות מזבח בשבת."],["264","25","בשלח טז, א. — וראה גם שבת פז, סע\"א."],["265","26","רפמ\"ו. וראה שם פמ\"א וברד\"ל שם (אות לה)."],["251","13","יתרו יט, י. ע\"ש באורך. — וראה תו\"ש משפטים שם במילואים סכ\"ז."],["267","27","ולהעיר ממדרש לקח טוב בפסוק שלאח\"ז (יט, יא), שמעתיק ל' המכילתא (שם) \"זה יום ששי שבו ניתנה התורה (ומוסיף) ביום השבת\", ומשמע קצת שמפרש כן במכילתא שם."],["e8","*","לכאורה י\"ל שהרמב\"ם ס\"ל להלכה שה­פרשה דס\"פ משפטים, נאמרה לאחרי מ\"ת (כפשטות הכתובים. וראה אברבנאל שם דכ\"ה שיטת חכמי ה­ספרדים), ואז הי' (הרצאת הדם ו)גמר הגירות (וראה לקמן ס\"ה). אבל בפיה\"מ (שצוין לעיל הערה 2), ש(גם) הקרבן הי' קודם מ\"ת. וראה פי' ר\"א בן הרמב\"ם משפטים שם. ואכ\"מ."]]],[1301430086,"ב. והנה לכאורה יש לתרץ, כי האי­סור דטבילת גר ביום השבת אינו אלא שבות דרבנן — כי שני טעמים נאמרו באיסור טבילת גירות בשבת: א) בגמ'<sup data-n=\"268\">28</sup> איתא משום ד\"תקוני גברא בשבת לא מתקנינן\", ב) ברמב\"ם<sup data-n=\"269\">29</sup> כתב ד\"הואיל והדבר (טבילת גר) צריך בית דין<sup data-n=\"270\">30</sup> אין מטבילין אותו בשבת\" — ושני הטעמים (תקוני גברא ואיסור לדון בשבת) הם איסורי שבות מדרבנן<sup data-n=\"271\">31</sup>.\nאבל עדיין יש דוחק בדבר, כי לא מסתבר לומר, שכניסת ישראל לברית תהי' ע\"י מעשה (הפכי)<sup data-n=\"272\">32</sup> שיש בו סרך איסור, איזה שהוא (אפילו איסור שבות), שהרי זה כמו דבר והיפוכו.\n[ואע\"פ שהמדובר באיסור שאינו אלא גזירה דרבנן — הרי אמרו חז\"ל<sup data-n=\"273\">33</sup> \"קיים אברהם אבינו כל התורה כולה. . אפילו עירובי תבשילין\" (\"שאינו. . אלא תקנת סופרים שעתידין לתקן\"<sup data-n=\"274\">34</sup>), ובפרש\"י עה\"ת<sup data-n=\"275\">35</sup> שאברהם הי' נזהר גם ב\"שבות לשבת\" ומזה מובן, שעצם מעשה השבות (גם קודם גזירה זו, קודם מ\"ת) יש בו גנאי (סרך איסור?)]<sup data-n=\"276\">*35</sup>.\nוביותר יוקשה לפמ\"ש במפרשים<sup data-n=\"277\">36</sup>, שלפי הדיעה<sup data-n=\"278\">37</sup> שמילה בשבת אסורה מ­פני המלאכה ד\"תיקון כלי\" (מכה ב­פטיש<sup data-n=\"279\">38</sup>), כיון שע\"י המילה \"נעשה הילד ישראל שלם\" — גם טבילת גר בשבת אסורה מה\"ת, שלפ\"ז נמצא, שטבילת בנ\"י אז לשם גירות<sup data-n=\"280\">39</sup> הי' בה מלאכה דאורייתא<sup data-n=\"281\">40</sup>.\nג. ויש לומר בזה, בהקדם מה שיש",[["268","28","יבמות מו, ב. וראה תוד\"ה תקוני שם (וראה הערה 19)."],["269","29","הל' איסו\"ב שם ה\"ו. וכ\"ה בשו\"ע יו\"ד שם ס\"ד [אלא שבט\"ז שם (סקי\"א) מפרש שאין כוונת הרמב\"ם לטעם שני, אלא לבאר למה לא אמרינן ד­\"נראה כמיקר\", ע\"ד דברי התוס' שבהערה ה­קודמת]."],["270","30","יבמות שם בסוף העמוד.\nוזה שייך גם קודם מ\"ת — ראה משנה ר\"ה (כה, א) \"וב\"ד שעמד מימות משה. . שנאמר (משפטים שם (כד, ט) — בהמשך לזריקת הדם על העם) ויעל משה ואהרן נדב ואביהוא ושבעים מזקני ישראל\"."],["271","31","ראה ריטב\"א יבמות שם (וכן מובן מתוד\"ה תקוני שם) — לענין \"תקוני גברא\". וראה משנה ביצה (לו, ב) האיסור לדון בשבת. וראה גם ב\"ח (שצויין בהערה 19) בעניננו."],["272","32","ובפרט שזוהי גירות דכל עם ישראל, ומגירות זו למדין לגירות דכל הדורות (ראה הציונים בהערה 1). ולהעיר מסברת המפרשים (גליוני הש\"ס (להר\"י ענגל) לשבת כא, ב. ועוד), ש\"חינוך\" צ\"ל בטהרה גמורה לא בדחיית טומאה כו' (ומביא שם כמה דוגמאות לזה)."],["273","33","יומא כח, ב (משנה סוף קידושין)."],["274","34","רש\"י יומא שם."],["275","35","תולדות כו, ה."],["276","*35","להעיר מחי' חת\"ס שם, דלדעת הסמ\"ג דמרע\"ה גזר על הזאה בשבת, גם הא דאין מטבילין גר בשבת הוא בכלל זה. ע\"ש."],["277","36","כתונת פסים על נמוק\"י יבמות שם."],["278","37","תרומת הדשן (שו\"ת סי' רסה) בדעת רש\"י (שבת קו, א ד\"ה מה לי). ע\"ש. והוא דלא כמסקנת המנ\"ח במוסך השבת אות כז."],["279","38","ראה מנ\"ח שם."],["280","39","משא\"כ בטבילה מטומאה. ולהעיר מתו\"י יבמות שם (בסוף הע') דהכא הוי \"תיקון גדול. . שבא על ידי כן לתורת יהדות\". ועד\"ז הוא בריטב\"א שם."],["281","40","ואולי י\"ל שבמרה לא נאמרו כל איסורי שבת (ראה שבת שם, שלחד דיעה אתחומין לא איפקוד במרה), ועדיין לא נצטוו על מלאכת תיקון כלי.\n[ועפ\"ז יש ליישב בפשיטות גם קושיית המפרשים הנ\"ל איך בנה מזבח והקריב קרבנות בשבת דמ\"ת — דיש לומר, שעדיין לא נצטוו על מלאכת הבנין ואיסור שחיטה כו']."]]],[1301430087,"לדייק במאמר חז\"ל שהכניסה לברית היא \"במילה וטבילה והרצאת דם\", שלכ­אורה אמאי לא מנו גם קבלת מצוות, שהיא ענין עיקרי בגירות, ואדרבה, זהו עיקר הגירות, כמו שנפסק להלכה ב­שו\"ע<sup data-n=\"282\">41</sup> שאם לא היתה קבלת מצוות בפני שלשה (וביום) מעכבת (משא\"כ הטבילה, שלכמה דיעות<sup data-n=\"283\">42</sup> אינה מעכבת אם לא היתה בפני ג').\nאך הביאור בזה — פשוט: קבלת מצוות אינה (רק) א' מהדברים המכניסים את האדם לברית, אלא היא היא (חלק מ)הברית עצמה, וכדיוק לשון הרמב\"ם<sup data-n=\"284\">43</sup> \"בשלשה דברים נכנסו ישראל לברית. . וכן לדורות כשירצה הגוי להכנס לברית ולהסתופף תחת כנפי השכינה ויקבל עליו עול תורה צריך מילה וטבילה ו­הרצאת קרבן\". הרי, שהענין ד\"יקבל עליו עול תורה\" הוא חלק מהרצון \"להכנס לברית\".\nומזה מובן בפשטות למה לא נמנית קבלת מצוות בין תנאי הגירות, כי כש­אין קבלת מצוות, אין זה חסרון בתנאי הגירות, אלא אין כאן גירות<sup data-n=\"285\">44</sup>, ורק לאחר שרוצה \"להכנס ולהסתופף תחת כנפי השכינה ויקבל עליו עול תורה\" יש חלות הגירות במילה וטבילה<sup data-n=\"286\">45</sup>, משא\"כ אם לא הקדים קבלת עול תורה ומצוות, אין כאן מעשה גירות.\nועפ\"ז יש לומר, שחלוקה הגירות דבני ישראל בעת מ\"ת מגירות שלאחרי מ\"ת: לאחרי מ\"ת, שג' הדברים באים לאחרי קבלת מצוות, הרי הם מכניסים אותו בפועל לברית ועושים אותו גר; משא\"כ בגירות בנ\"י במתן תורה, שקודם מ\"ת (אמירת עשה\"ד) עדיין לא היתה אצלם קבלת מצוות [דאף שאמרו \"כל אשר דבר ה' נעשה. . נעשה ונשמע\"<sup data-n=\"287\">46</sup>, אין אמירה זו נחשבת כמעשה קבלת מצוות לענין המצוות שלאחרי מ\"ת, כד­לקמן סעיף ד] — הרי ע\"י טבילתם ו­הרצאת הדמים עדיין לא נכנסו לברית בפועל, ולא נגמרה גירותם עד אמירת עשה\"ד, שאז היתה קבלת מצוות שלהם (כדלקמן ס\"ה).\n[ומה שאמרו חז\"ל שאבותינו \"לא נכנסו לברית אלא במילה וטבילה והר­צאת דם\", אין הכוונה בזה, שתיכף ל­אחרי עשיית ג' דברים הללו נכנסו לברית, אלא שבשביל כניסתם לברית היו צריכים לג' דברים אלה (ובלעדם לא היתה קבלת מצוות שלהם מועלת להכנס לברית), ולכן למדין מזה לדורות ש\"לא יכנסו לברית אלא במילה וטבילה והרצאת דמים\"<sup data-n=\"288\">47</sup>; אבל הגירות אז וכניסה לברית בפועל נעשתה בעת מ\"ת גופא].\nוזהו גם הטעם שלא הי' אז איסור לטבול ביום השבת לשם גירות — דרק בגירות שלאחרי מ\"ת, כשהטבילה גומרת",[["282","41","טושו\"ע יו\"ד שם ס\"ג. וראה ט\"ז שם (סק\"ט) \"שזהו גוף הדבר\". וראה לקמן בפנים."],["283","42","ראה ב' הדיעות בטושו\"ע שם."],["284","43","הל' איסו\"ב רפי\"ג ושם ה\"ד."],["285","44","וראה שו\"ת חמדת שלמה חיו\"ד סכ\"ט אות כא ואילך (צויין בפתחי תשובה ביו\"ד שם סק\"ט), דרק הודעת (שכר) המצות ועונשן אינה מעכבת בדיעבד (ראה רמב\"ם שם הי\"ז. שו\"ע שם סי\"ב. ועוד), אבל קבלת מצות מעכבת. ע\"ש באורך.\n[וכבר האריכו בגדר גר קטן שמטבילין אותו על דעת ב\"ד (כתובות יא, א. וראה ריטב\"א ושיטה ישנה (בשטמ\"ק) שם). ואכ\"מ]."],["286","45","ראה נ\"כ הטושו\"ע יו\"ד שם (בדין אם טבילה בלילה פסולה בדיעבד) — דקבלת מצות נחשבת התחלת דין (כי זהו \"גוף הדבר\" — ט\"ז שם), וטבילה — \"גמר דין\"."],["287","46","יתרו יט, ח. משפטים כד, ג. שם, ז."],["288","47","ל' הגמ' כריתות שם."]]],[1301430088,"הגירות ועל ידה נכנסים בפועל לברית, נאסרה משום \"תקוני גברא\"<sup data-n=\"289\">48</sup>; משא\"כ בטבילת ישראל קודם מ\"ת, שלא נגמרה הגירות על ידה, אין לאסור טבילה זו בשבת משום \"תקוני גברא\".\nוגם טעם הרמב\"ם (הנ\"ל ס\"ב) — שאין מטבילין גר בשבת כי \"הדבר צריך ב\"ד\" — אינו שייך בגירות בנ\"י בעת מ\"ת. כי רק בגירות שלאחרי מ\"ת, כשהמילה וטבילה כו' באות לאחרי קבלת מצוות והן פועלות הגירות וגומרות אותה, ה\"ה בגדר \"משפט\" שצריך ב\"ד; משא\"כ ב­גירות בנ\"י במ\"ת, כיון שע\"י הטבילה (והרצאת דמים) עדיין לא היתה חלות הגירות, אין הטבילה (והרצאת דמים) בגדר \"משפט\" שצריך ב\"ד<sup data-n=\"290\">49</sup>.\nד. הסברת הענין:\nבפירוש הכתוב<sup data-n=\"291\">50</sup> \"ויספר (משה) לעם את כל דברי ה' ואת כל המשפטים ויען כל העם קול אחד ויאמרו כל הדברים אשר דבר ה' נעשה\", כתב רש\"י (ע\"פ המכילתא<sup data-n=\"292\">51</sup>) דקאי על מצות פרישה ו­הגבלה, ז' מצות שנצטוו בני נח, ומצות שניתנו במרה (שבת כבוד אב ואם פרה אדומה ודינין<sup data-n=\"293\">52</sup>), ועד\"ז בפסוק<sup data-n=\"294\">53</sup> \"ויקח ספר הברית ויקרא באזני העם ויאמרו כל אשר דבר ה' נעשה ונשמע\", פרש\"י ש\"ספר הברית\" היינו \"מבראשית ועד מתן תורה ומצות שנצטו במרה\".\nוהנה קבלת ז' מצוות בני נח בודאי אינה בגדר קבלת מצות דישראל (תרי\"ג מצוות), ואפילו קבלת מצוות שנצטוו במרה צ\"ע אם די' להחשב קבלת מצוות. כי אע\"פ שאין צריכים להודיע לגר כל תרי\"ג מצוות (ודי להודיעו \"עיקרי<sup data-n=\"295\">54</sup> הדת שהוא ייחוד השם ואיסור עבודה זרה. . מקצת מצות קלות ומקצת מצות חמורות\") — הרי חייב לקבל עליו כל מצוות התורה, דאם קיבל עליו כל התורה כולה חוץ מדבר א' אינו גר<sup data-n=\"296\">55</sup> — וא\"כ גם במרה בקבלת מצות שנצטוו במרה אין כאן קבלת כל התורה. ועצ\"ע.\nונראה לומר, שגם לפי פשטות סוגיית הגמ'<sup data-n=\"297\">56</sup> שאמירת נעשה ונשמע היתה קב­לת כל התורה כולה (שקבלו אותה קודם ששמעו אותה, הקדמת נעשה לנשמע) — א\"א להחשיב אמירה זו שקודם מ\"ת גדר של קבלת מצוות (הנצרך לגירות).\nובהקדם הטעם לסדר קבלת גירות לדורות, שצריכים להודיע אותו \"מקצת",[["289","48","ויש להוסיף, שגם להדיעות שאין הסדר (דמילה לפני טבילה) מעכב — מ\"מ מובן, שגם הטבילה שלפני המילה (שאז אינה גומרת הגירות) אסורה בשבת, כיון שלכתחילה צ\"ל הטבילה אחרי המילה [והרצאת דמים בכלל אינה מעכבת עצם הגירות, כ\"א רק לענין אכילת קדשים — ראה בארוכה לקו\"ש חכ\"ו ע' 160 ואילך. וש\"נ]."],["290","49","כמובן מהנסמן לעיל הערה 45, שקבלת מצות נחשבת \"התחלת דין\" (ו\"גוף הדבר\") וטבילה גמר דין — משא\"כ במ\"ת שלא היתה הטבילה בגדר התחלת דין (כיון שעדיין חסר קבלת מצות שהיא \"גוף הדבר\"), וכ\"ש שאינו גמר דין. — וראה קרן אורה ליבמות שם."],["291","50","משפטים שם, ג."],["292","51","יתרו יט, י (בפירוש \"ספר הברית\" — משפטים שם, ז. וראה רש\"י שם (ושם, ד)). — אלא שרש\"י בפ' משפטים צירף ב' דיעות שבמכילתא שם. ונת' בארוכה בלקו\"ש חכ\"א ע' 138 ואילך."],["293","52","רש\"י שם. וראה רש\"י בשלח טו, כה. וכבר האריכו במפרשי רש\"י. ואכ\"מ."],["294","53","שם, ז. וראה בארוכה לקו\"ש שם."],["295","54","ל' הרמב\"ם הל' איסו\"ב פי\"ד ה\"ב. שו\"ע יו\"ד שם ס\"ב (ובטור שם השמיט התחלת הלשון \"עיקרי הדת שהוא ייחוד השם ואיסור ע\"ז\")."],["296","55","בכורות ל, ב. רמב\"ם שם ה\"ח."],["297","56","שבת פח, א.\nולהעיר, שגם לפרש\"י עה\"ת, אמירת ישראל (יתרו יט, ח) \"כל אשר דבר ה' נעשה\", היתה ב­פשטות קבלה על \"שמירת התורה\" (רש\"י שם, ה)."]]],[1301430089,"מצות חמורות. . ומודיעין אותו עונשן של מצות\"<sup data-n=\"298\">57</sup>, שהצורך בהודעה זו הוא בפשטות, (גם) לפי שאם לא נודיע אותו מקצת החמורות, וכן עונשן של מצות, חסר בקבלת מצות שלו<sup data-n=\"299\">*57</sup> (שיתכן שכ­שיוודע ע\"ד המצוות החמורות או עונשן יתחרט כו'<sup data-n=\"300\">**57</sup>).\nועד\"ז י\"ל בעניננו, דכל זמן שלא ניתנה תורה בסיני מפי הגבורה, א\"א להיות קבלה על מצוות שלאחרי מ\"ת.\nדכיון שהמצוות שלפנ\"ז אינם בגדר של המצוות שלאחרי מ\"ת, וכמובן, שאי­נה דומה כלל חומרת המצוות שקיימו האבות מעצמם, לחומרת המצוות לאחרי שנצטוו עליהם, ועד\"ז אינו דומה כלל חומר הציווים שנצטוו ישראל ע\"י משה לפני מ\"ת, לחומר הציוויים לאחרי מ\"ת, שאז שמעו את עשה\"ד מפי הגבורה<sup data-n=\"301\">58</sup>,\n[כדברי הרמב\"ם<sup data-n=\"302\">59</sup> \"שכל מה שאנו מרחיקים או עושים היום אין אנו עושין אלא במצות הקב\"ה ע\"י משה רבינו ע\"ה. . מסיני\" — ולא מפני \"שהקב\"ה אמר זה לנביאים שלפניו\", דאף שגם אלה היו ציוויי הקב\"ה לנביאים, מ\"מ, אינו דומה כלל לציוויי הקב\"ה בסיני],\nלכן, כל ענין של קבלת מצוות קודם שמיעת עשה\"ד מפי הגבורה, אין להח­שיבו כ\"קבלת מצוות\" שלאחרי מ\"ת, ד­קודם שהי' התוקף דתומ\"צ שלאחרי מ\"ת (שהם \"מפי הגבורה\") בעולם, לא שייך שתהי' ע\"ז קבלה (אמיתית), דהוי דבר שלא בא לעולם (ואין להם מושג בסוג ציוויים כאלה<sup data-n=\"301\">58</sup>).\n[ואע\"פ שהודעת (שכר) המצות ועונשן אינה מעכבת<sup data-n=\"304\">60</sup> — יש לחלק בין ההודעה לאחרי שכבר ניתנה תורה ומצוות ל­ישראל ושייך שידע אותם, אלא שב\"ד לא הודיעו שכר מצות ועונשן לגר זה הבא להתגייר (ובפרט שבזה י\"ל שכיון שבא להתגייר, סמכינן שחקר ודרש ו­יודע מעצמו טיבן של המצוות שיתחייב בהן כשיתגייר); אבל קודם שניתנה תורה, כשעדיין אין מציאות של תומ\"צ (בתוקף שלאחרי מ\"ת) בעולם, הרי לא שייך על זה גדר של \"קבלה\", כיון שהוא דבר שלא בא לעולם, כנ\"ל].\nועפ\"ז יתוסף ביאור בשיטת המפרשים (הנ\"ל ס\"א), שכל פרשה זו (דס\"פ משפ­טים) לאחרי מ\"ת נאמרה — שלכאורה, זמן המתאים לקבלת מצות הוא קודם נתינת התורה (שכאשר יסכימו לקבל עליהם עול מצוות תינתן להם התורה)?\nוע\"פ הנ\"ל מובן, שאדרבה, היא ה­נותנת: כיון שתוכן הפרשה הוא כריתת ברית על קיום התומ\"צ, ס\"ל שענין זה אפשרי רק אחרי מ\"ת ושמיעת עשה\"ד מפי הגבורה, משא\"כ לפני כן לא יתכן ברית על תומ\"צ, שהן בגדר דבר שלא בא לעולם (כיון שכל מה שידעו ונצטוו",[["298","57","יבמות מז, א. רמב\"ם, טושו\"ע שבהערה 54."],["299","*57","ראה רש\"י יבמות שם ע\"ב (ד\"ה ומודיעין) — אלא דשם קאי בהודעה בשעת טבילה."],["300","**57","ראה ב\"י יו\"ד שם (ד\"ה כשבא) בשם ה­סמ\"ג ובש\"ך שם סק\"ג. ובגמ' שם \"דאי פריש כו'\". ואכ\"מ."],["301","58","ואף שהודיע להם \"עונשין\" (שבת פז, סע\"א (פרש\"י יתרו יט, ג). וראה חדא\"ג מהרש\"א שם, שזהו לפי שצריכים להודיע לגר עונשן של מצות) — אינו דומה לרגש חומרת המצות לאחרי ששמעו עשה\"ד מפי הגבורה. ולהעיר מסה\"מ תש\"י (ע' 242), דאע\"פ שמשה רבינו ידע ושיער ה\"חרדה\" שתהי' במ\"ת, מ\"מ, לא הי' בערך כלל להחרדה כפי שהיתה בפועל."],["302","59","פיהמ\"ש חולין ספ\"ז. וראה לקו\"ש ח\"ח ע' 49 והערה 6 שם. ועוד."],["301","58","ואף שהודיע להם \"עונשין\" (שבת פז, סע\"א (פרש\"י יתרו יט, ג). וראה חדא\"ג מהרש\"א שם, שזהו לפי שצריכים להודיע לגר עונשן של מצות) — אינו דומה לרגש חומרת המצות לאחרי ששמעו עשה\"ד מפי הגבורה. ולהעיר מסה\"מ תש\"י (ע' 242), דאע\"פ שמשה רבינו ידע ושיער ה\"חרדה\" שתהי' במ\"ת, מ\"מ, לא הי' בערך כלל להחרדה כפי שהיתה בפועל."],["304","60","נסמן לעיל הערה 44."]]],[1301430090,"לפני מ\"ת, אינו כלל באותו הגדר של המצוות שלאחרי מ\"ת).\nה. ולכן מסתבר לומר, שעיקר ענין קבלת מצוות (שעל ידה נכנסו ישראל לברית) הי' בעת שמיעת עשה\"ד, שאז הודיע הקב\"ה ייחוד השם ואיסור ע\"ז — אנכי ולא יהי' לך [עם עונשם — \"א­ל קנא גו'\"<sup data-n=\"305\">61</sup>] ואיסור שבת ועוד מהחמורות (שהם בעונש מיתה), וגם מהקלות.\nועפ\"ז מתורצת בפשיטות קושיית התוס'<sup data-n=\"306\">62</sup> במחז\"ל<sup data-n=\"307\">63</sup> ש\"כפה עליהם את ההר כגיגית\" (ולכן \"מכאן מודעה רבה לאורייתא\"<sup data-n=\"307\">63</sup>, שיש לישראל תשובה ע\"ז שלא קיימו התורה, \"שקבלוה באונס\"<sup data-n=\"309\">64</sup>), והרי \"כבר הקדימו נעשה לנשמע\"<sup data-n=\"310\">65</sup> — וע\"פ הנ\"ל י\"ל, שאמירת נעשה ונשמע אין בזה תורת \"קבלת מצוות\", וקבלת ה­מצוות דישראל היתה בשעת עשה\"ד, ואז הי' זה באופן ד\"כפה עליהם הר כגיגית\".\nוזהו גם הביאור בשיטת ריבר\"י הנ\"ל, שטבילתם לשם גירות היתה ביום השבת — כי מעשה טבילה זו של בנ\"י לא היתה בו חלות כניסה לברית, כיון שעדיין לא היתה קבלת מצוות, והכניסה לברית בפועל וחלות הגירות נפעלה אח\"כ ע\"י מעשה הקב\"ה<sup data-n=\"311\">66</sup> (באמירת עשה\"ד כנ\"ל), שאז היתה קבלת תומ\"צ ע\"י ישראל.\nו. ויש להוסיף מקור לענין האמור (שהגירות דמ\"ת נפעלה רק בעת עשה\"ד) בדברי המדרש<sup data-n=\"312\">67</sup>, ד\"כשברא הקב\"ה את העולם גזר ואמר<sup data-n=\"313\">68</sup> השמים שמים לה' והארץ נתן לבני אדם, כשביקש ליתן את התורה בטל את הגזירה הראשונה ואמר התחתונים יעלו לעליונים והעליונים ירדו לתחתונים ואני המתחיל שנאמר<sup data-n=\"314\">69</sup> וירד ה' על הר סיני\".\nמדברי המדרש מובן, שאע\"פ שמצינו התגלות ה' לצדיקים ולנביאים לפני מ\"ת, מ\"מ, כיון שהי' לפני בטול \"גזירה ה­ראשונה\", ה\"ז נחשב שעדיין ה\"עליונים\" (השכינה) לא ירדו למטה. וכמבואר ב­כמה מקומות, שקודם מ\"ת לא היתה שלי­מות בהתגלותו של הקב\"ה, ורק בעת מ\"ת היתה ההתגלות של \"אנכי ה' אלקיך\", ולכן רק אז בטלה הגזירה דעליונים לא ירדו לתחתונים.\nומזה מובן גם בנוגע למשה רבינו עצמו, דאף שהקב\"ה נתגלה אליו בסנה ועוד, מ\"מ, אין זה כלל באותו הגדר של \"התגלות ה'\" כפי שהיתה בעת ירידת ה' על הר סיני ואמירת עשרת הדברות.\nובזה יש לבאר מה שמ\"ת נחשב כ­\nגירות של עם ישראל, שענין הגירות\nהוא שהגר נעשה מציאות חדשה, כ­\nקטן שנולד דמי<sup data-n=\"315\">70</sup>, ולכאורה הרי כבר ב­יציאת מצרים נאמר<sup data-n=\"316\">71</sup> \"לקחת לו גוי מקרב גוי\"<sup data-n=\"317\">72</sup>, וביותר יוקשה לפי הראשו­",[["305","61","יתרו כ, ה."],["306","62","שבת פח, א ד\"ה כפה."],["307","63","שבת שם."],["307","63","שבת שם."],["309","64","רש\"י שם."],["310","65","כשיטת הש\"ס (שבת שם) שאמירת נעשה ונשמע (שבס\"פ משפטים) היתה ביום חמישי בחודש (כבנין המזבח כו'), כהדיעות שהובאו לעיל ס\"א."],["311","66","ומובן שאין מקום להקשות למה נתן הקב\"ה את התורה ביום השבת (באופן שגמר גירותם של ישראל הי' בשבת). ועיין תו\"א ויקהל (פז, ג ואילך), השייכות דשבת ותורה. המשך תרס\"ו ע' רלט. ועוד."],["312","67","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["313","68","תהלים קטו, טז."],["314","69","יתרו יט, כ."],["315","70","יבמות כב, א. וש\"נ. — וראה בס' שנסמנו בלקו\"ש חכ\"א ע' 63 הערה 16."],["316","71","ואתחנן ד, לד."],["317","72","אלא שי\"ל שביצי\"מ היתה התחלת הגירות, שהרי \"מילה היתה במצרים\" (ל' הרמב\"ם הל' איסו\"ב רפי\"ג). וראה תו\"י יבמות מו, ב ד\"ה ורבי יהושע."]]],[1301430091,"נים<sup data-n=\"318\">73</sup> שס\"ל שהאבות כבר יצאו מגדר ב\"נ והי' להם דין ישראל, ואין לומר ש­במ\"ת היתה הגירות של עם ישראל<sup data-n=\"319\">74</sup>.\nוע\"פ הנ\"ל מבואר, דאע\"פ שכבר היו קשורים לה' לפני מ\"ת, הרי אופן ההתגלות דהקב\"ה לכל ישראל בעת מ\"ת פעלה בהם התחדשות גמורה, עד שנעשו כמציאות חדשה ממש, כקטן שנולד דמי.\nוזהו גם ההבדל בין המצוות שלפני מ\"ת לתומ\"צ שניתנו לנו בסיני, כי התג­לות זאת של הקב\"ה \"ניתנה\" בתורה ו­מצוות<sup data-n=\"320\">75</sup>, באופן כזה, שע\"י שאיש ישראל לומד תורה ומקיים מצוות, מתקשר ו­מתחבר עם עצמות הקב\"ה, ובלשון חז\"ל, שע\"י תורה \"אותי אתם לוקחים\"<sup data-n=\"321\">76</sup>.\n<span data-k=\"q\">(משיחות יום ב' דחג השבועות וש\"פ נשא תשל\"ט)</span>",[["318","73","ראה בארוכה פרשת דרכים דרך האתרים דרוש א'. בית האוצר (להר\"י ענגל) כלל א. וש\"נ."],["319","74","ובבית האוצר שם (סוף אות ח), דמהך מימרא דכריתות (שאבותינו נכנסו לברית במילה טבילה כו') מוכח בפשיטות שמקודם לכן (מ\"ת) הי' להם דין ב\"נ. ולהעיר מאוה\"ת משפטים (כרך ח) ע' ג'מב."],["320","75","ראה תניא פמ\"ז \"וה\"ז כאילו נתן לנו את עצמו כביכול\". וראה אוה\"ת שם ע' ג'מד. ובכ\"מ."],["321","76","תנחומא אמור יז. ויק\"ר פ\"ל, יג. וראה שמו\"ר פל\"ג, א. שם, ו. תנחומא תרומה ג."]]]]});
